"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[312],{8312:(e,a,t)=>{t.d(a,{U$:()=>n,UF:()=>i});let n=JSON.parse('{"brand":{"fa":"نوآشپز","en":"Noashpaz","ar":"نوآشپز"},"labels":{"fa":{"home":"خانه","countries":"کشورها","recipes":"دستورها","ingredients":"مواد اولیه","search":"جستجو","about":"درباره","rules":"قوانین","login":"ورود","servings":"نفر","prep":"آماده‌سازی","cook":"پخت","total":"زمان","minutes":"دقیقه","ingredientsTitle":"مواد لازم","steps":"دستور پخت","optional":"اختیاری","placeholder":"تصویر به‌زودی","results":"نتیجه","pick":"مواد را انتخاب کنید","noResults":"چیزی پیدا نشد.","comments":"نظرها","fullVersion":"این بخش در نسخهٔ کامل در دسترس است.","searchPlaceholder":"جستجو در نوآشپز","notFoundTitle":"این صفحه پیدا نشد","notFoundBody":"شاید نشانی اشتباه تایپ شده یا این صفحه جابه‌جا شده است. غذای مورد نظرتان را جستجو کنید یا از روی نقشه کشوری را انتخاب کنید.","offlineTitle":"اتصال اینترنت قطع است","offlineBody":"دستورهایی که قبلاً باز کرده‌اید را بدون اینترنت هم می‌توانید ببینید.","offlineEmpty":"هنوز دستوری ذخیره نشده. وقتی دوباره آنلاین شدید، هر دستوری که باز کنید اینجا هم می‌ماند.","maintenanceTitle":"در حال به‌روزرسانی هستیم","maintenanceBody":"نوآشپز به‌زودی برمی‌گردد. ممنون از صبرتان.","maintenanceStatus":"در حال به‌روزرسانی سایت هستیم و به‌زودی برمی‌گردیم.","copyright":"\xa9 ۱۴۰۵ نوآشپز"},"en":{"home":"Home","countries":"Countries","recipes":"Recipes","ingredients":"Ingredients","search":"Search","about":"About","rules":"Rules","login":"Sign in","servings":"servings","prep":"Prep","cook":"Cook","total":"Total","minutes":"min","ingredientsTitle":"Ingredients","steps":"Method","optional":"optional","placeholder":"Photo coming soon","results":"results","pick":"Choose ingredients you have","noResults":"Nothing matched.","comments":"Comments","fullVersion":"available in the full version","searchPlaceholder":"Search Noashpaz","notFoundTitle":"Page not found","notFoundBody":"The address may be mistyped or the page may have moved. Search for a dish or pick a country on the map.","offlineTitle":"You\'re offline","offlineBody":"Recipes you\'ve opened before are still available without internet.","offlineEmpty":"No recipes saved yet. Once you\'re back online, every recipe you open will also be kept here.","maintenanceTitle":"We\'re updating the site","maintenanceBody":"Noashpaz will be back soon. Thanks for your patience.","maintenanceStatus":"We\'re updating the site and will be back soon.","copyright":"\xa9 2026 Noashpaz"},"ar":{"home":"الرئيسية","countries":"البلدان","recipes":"الوصفات","ingredients":"المكونات","search":"بحث","about":"حول الموقع","rules":"القواعد","login":"دخول","servings":"أشخاص","prep":"تحضير","cook":"طبخ","total":"المدة","minutes":"د","ingredientsTitle":"المكونات","steps":"طريقة التحضير","optional":"اختياري","placeholder":"الصورة لاحقًا","results":"نتيجة","pick":"اختر المكونات المتوفرة","noResults":"لا توجد نتائج.","comments":"التعليقات","fullVersion":"هذا القسم متاح في النسخة الكاملة.","searchPlaceholder":"ابحث في نوآشپز","notFoundTitle":"لم يتم العثور على هذه الصفحة","notFoundBody":"ربما كُتب العنوان بشكل خاطئ أو نُقلت الصفحة. ابحث عن طبق أو اختر دولة من الخريطة.","offlineTitle":"أنت غير متصل بالإنترنت","offlineBody":"يمكنك تصفّح الوصفات التي فتحتها سابقًا من دون إنترنت.","offlineEmpty":"لا توجد وصفات محفوظة بعد. عندما تعود متصلًا، ستُحفظ هنا كل وصفة تفتحها.","maintenanceTitle":"نقوم بتحديث الموقع","maintenanceBody":"سيعود نوآشپز قريبًا. شكرًا لصبرك.","maintenanceStatus":"نقوم بتحديث الموقع وسنعود قريبًا.","copyright":"\xa9 ٢٠٢٦ نوآشپز"}},"rules":{"fa":{"title":"قوانین نوآشپز","intro":"نوآشپز جایی است برای آشپزی با طعم‌های همه‌ی دنیا، به سه زبان و برای همه. این چند قانون کمک می‌کند اینجا امن، مفید و دوستانه بماند.","sections":[{"heading":"آشپزخانه‌ی ما: بدون خوک و الکل","paragraphs":["همه‌ی دستورهای نوآشپز بدون گوشت خوک و فرآورده‌هایش و بدون هیچ نوع الکل‌اند؛ از جمله ژلاتین خوکی، شراب آشپزی، سرکه‌ی شراب، میرین و وانیل الکلی. اگر غذای اصلی چنین موادی دارد، جایگزین حلال و خوش‌طعمش را پیشنهاد می‌کنیم."]},{"heading":"حساب کاربری","paragraphs":["هر نفر یک حساب. اطلاعات درست وارد کنید و رمزتان را به کسی ندهید.","نام کاربری و عکس پروفایل باید محترمانه باشند و تبلیغ نکنند.","مسئولیت فعالیت‌هایی که با حساب شما انجام می‌شود با خودتان است."]},{"heading":"نظرها، امتیازها و عکس‌ها","paragraphs":["همه‌ی نظرها و عکس‌ها پیش از انتشار بررسی می‌شوند؛ نظر ویرایش‌شده هم دوباره بررسی می‌شود.","محترمانه بنویسید: فحش، توهین، تحقیر فرهنگ‌ها و آزار دیگران ممنوع است.","تبلیغ، لینک، اطلاعات شخصی و حرف‌های بی‌ربط منتشر نمی‌شوند.","امتیازتان (۰ تا ۵ ستاره) را بر اساس تجربه‌ی واقعی خودتان بدهید.","فقط عکس‌هایی را بفرستید که خودتان از غذای همین دستور گرفته‌اید."]},{"heading":"دستورهای کاربران","paragraphs":["دستور باید نوشته‌ی خودتان باشد؛ اگر از جایی الهام گرفته‌اید، منبعش را بنویسید.","هر دستور پیش از انتشار توسط ویراستاران ما بررسی می‌شود و ممکن است برای اصلاح به شما برگردد.","با ارسال دستور، به نوآشپز اجازه می‌دهید آن را منتشر، ویرایش جزئی و به زبان‌های دیگر سایت ترجمه کند؛ نام شما به‌عنوان نویسنده می‌ماند."]},{"heading":"گزارش مشکل و درخواست غذا","paragraphs":["اشتباهی در دستوری دیدید؟ گزارش دهید؛ گفت‌وگوی شما با تیم در پروفایلتان می‌ماند.","غذای دلخواهتان را درخواست کنید؛ همه‌ی درخواست‌ها را می‌خوانیم، هرچند نمی‌توانیم قول دهیم همه را بپزیم."]},{"heading":"اگر قانونی رعایت نشود","paragraphs":["محتوای نامناسب منتشر نمی‌شود و دلیلش را در پروفایلتان می‌بینید. در صورت تکرار تخلف یا تخلف جدی (مثل هرزنامه یا آزار)، ممکن است امکان ارسال محدود یا حساب مسدود شود."]},{"heading":"سؤال دارید؟","paragraphs":["صفحه‌های راهنما را ببینید یا از بخش \xabگزارش مشکل\xbb با ما در تماس باشید. ممنون که با ما می‌پزید!"]}]},"en":{"title":"Noashpaz Rules","intro":"Noashpaz is a place to cook the flavours of the whole world — in three languages, for everyone. These few rules keep it safe, useful and friendly.","sections":[{"heading":"Our kitchen: no pork, no alcohol","paragraphs":["Every Noashpaz recipe is free of pork, pork products and alcohol of any kind — including pork gelatin, cooking wine, wine vinegar, mirin and alcohol-based vanilla. If an original dish uses them, we offer a tasty halal alternative."]},{"heading":"Your account","paragraphs":["One account per person. Use accurate details and keep your password to yourself.","Usernames and profile photos must be respectful and not promotional.","You\'re responsible for activity on your account."]},{"heading":"Comments, ratings and photos","paragraphs":["All comments and photos are reviewed before publishing; edited comments are reviewed again.","Be respectful: no profanity, insults, putting down cultures, or harassment.","Ads, links, personal information and off-topic posts won\'t be published.","Give your rating (0–5 stars) based on your own real experience.","Only upload photos you took yourself of this recipe\'s dish."]},{"heading":"Recipes from users","paragraphs":["Recipes must be your own writing; if inspired by someone else, credit the source.","Every recipe is checked by our editors before publishing and may be sent back to you for changes.","By submitting, you allow Noashpaz to publish it, make light edits and translate it into the site\'s other languages; you stay credited as the author."]},{"heading":"Reports and dish requests","paragraphs":["Spotted a mistake? Report it — your conversation with the team stays in your profile.","Request the dishes you love; we read every request, though we can\'t promise to cook them all."]},{"heading":"If rules are broken","paragraphs":["Content that breaks the rules won\'t be published, and you\'ll see the reason in your profile. Repeated or serious violations (like spam or harassment) may lead to posting limits or account suspension."]},{"heading":"Questions?","paragraphs":["Check our help pages, or reach us through \\"Report a problem\\". Thanks for cooking with us!"]}]},"ar":{"title":"قواعد نوآشپز","intro":"نوآشپز مكانٌ لطهي نكهات العالم كله، بثلاث لغات وللجميع. وهذه القواعد القليلة تُبقيه آمنًا ومفيدًا وودودًا.","sections":[{"heading":"مطبخنا: بلا خنزير ولا كحول","paragraphs":["جميع وصفات نوآشپز خالية من لحم الخنزير ومشتقاته ومن الكحول بكل أنواعه، بما في ذلك جيلاتين الخنزير ونبيذ الطهي وخل النبيذ والميرين والفانيليا الكحولية. وإذا احتوى الطبق الأصلي على شيء منها، اقترحنا بديلًا حلالًا شهيًّا."]},{"heading":"حسابك","paragraphs":["حساب واحد لكل شخص. أدخل بيانات صحيحة ولا تشارك كلمة المرور مع أحد.","يجب أن يكون اسم المستخدم وصورة الملف الشخصي لائقين وخاليين من الترويج.","أنت مسؤول عن النشاط الذي يجري عبر حسابك."]},{"heading":"التعليقات والتقييمات والصور","paragraphs":["تُراجَع جميع التعليقات والصور قبل نشرها، ويُراجَع التعليق المعدَّل من جديد.","التزم الاحترام: لا ألفاظ نابية ولا إهانات ولا انتقاص من الثقافات ولا مضايقة.","لا تُنشَر الإعلانات والروابط والمعلومات الشخصية والمشاركات الخارجة عن الموضوع.","امنح تقييمك (من ٠ إلى ٥ نجوم) بناءً على تجربتك الفعلية.","لا ترفع إلا صورًا التقطتها بنفسك لطبق هذه الوصفة."]},{"heading":"وصفات المستخدمين","paragraphs":["يجب أن تكون الوصفة من كتابتك، وإن استوحيتها من غيرك فاذكر المصدر.","يراجع محرّرونا كل وصفة قبل نشرها، وقد تُعاد إليك لإجراء تعديلات.","بإرسال الوصفة تأذن لنوآشپز بنشرها وتحريرها تحريرًا طفيفًا وترجمتها إلى لغات الموقع الأخرى، مع بقاء اسمك مؤلفًا لها."]},{"heading":"البلاغات وطلبات الأطباق","paragraphs":["لاحظت خطأً في وصفة؟ أبلغنا به، وستبقى محادثتك مع الفريق في ملفك الشخصي.","اطلب الأطباق التي تحبها؛ نقرأ كل الطلبات، وإن كنا لا نستطيع الوعد بإعدادها كلها."]},{"heading":"عند مخالفة القواعد","paragraphs":["لا يُنشَر المحتوى المخالف، وستجد السبب في ملفك الشخصي. وقد تؤدي المخالفات المتكررة أو الجسيمة (كالرسائل المزعجة أو المضايقة) إلى تقييد النشر أو تعليق الحساب."]},{"heading":"لديك سؤال؟","paragraphs":["اطّلع على صفحات المساعدة أو تواصل معنا عبر \xabالإبلاغ عن مشكلة\xbb. شكرًا لأنك تطهو معنا!"]}]}},"countries":[{"code":"IR","slug":"iran","fa":"ایران","en":"Iran","ar":"إيران","flag":"\uD83C\uDDEE\uD83C\uDDF7","count":16},{"code":"IQ","slug":"iraq","fa":"عراق","en":"Iraq","ar":"العراق","flag":"\uD83C\uDDEE\uD83C\uDDF6","count":7}],"recipes":[{"id":"ab-doogh-khiar","country":"IR","slugs":{"fa":"آب-دوغ-خیار","en":"ab-doogh-khiar","ar":"آب-دوغ-خيار"},"title":{"fa":"آب‌دوغ‌خیار","en":"Ab-Doogh-Khiar (Cold Yogurt Soup)","ar":"آب دوغ خيار (حساء اللبن البارد)"},"summary":{"fa":"سوپ سرد تابستانی از ماست و دوغ با خیار، گردو، کشمش، سبزی تازه، نعناع و گل‌سرخ خشک که با تکه‌های نان خشک خورده می‌شود.","en":"A cold summer soup of yogurt and doogh with cucumber, walnuts, raisins, fresh herbs, dried mint and rose petals, eaten with pieces of dry bread.","ar":"حساء صيفي بارد من اللبن والدوغ مع الخيار والجوز والزبيب والأعشاب الطازجة والنعناع اليابس وبتلات الورد، يؤكل مع قطع الخبز اليابس."},"intro":{"fa":"آب‌دوغ‌خیار غذای ظهرهای گرم تابستان در سراسر ایران است: پختی ندارد، در چند دقیقه آماده می‌شود و فقط باید پیش از سرو خوب سرد شود. ترکیب ترشی ماست، طراوت خیار و سبزی، شیرینی کشمش و چربی گردو آن را یک وعدهٔ کامل می‌کند. نان خشک را درست پیش از خوردن در کاسه خرد کنید تا خمیر نشود.","en":"Ab-doogh-khiar is a hot-summer lunch all over Iran: there is no cooking, it comes together in minutes and only needs to be well chilled before serving. The tang of yogurt, the freshness of cucumber and herbs, the sweetness of raisins and the richness of walnuts make it a full meal. Break the dry bread into the bowl just before eating so it doesn\'t turn soggy.","ar":"آب دوغ خيار غداء ظهيرة الصيف الحارة في أنحاء إيران: لا طهي فيه، يُحضَّر في دقائق ويكفي أن يبرد جيدًا قبل التقديم. حموضة اللبن وانتعاش الخيار والأعشاب وحلاوة الزبيب ودسم الجوز تجعله وجبة كاملة. فتّت الخبز اليابس في الوعاء قبل الأكل مباشرة كي لا يتعجّن."},"seoTitle":{"fa":"آب‌دوغ‌خیار؛ طرز تهیه سوپ سرد تابستانی بدون پخت","en":"Ab-Doogh-Khiar Recipe (Persian Cold Yogurt Soup)","ar":"آب دوغ خيار: طريقة عمل حساء اللبن البارد الإيراني"},"seoDescription":{"fa":"طرز تهیه آب‌دوغ‌خیار برای ۴ نفر: ماست و دوغ با خیار، گردو، کشمش، سبزی تازه، نعناع و گل‌سرخ خشک، با نان خشک؛ بدون پخت، آسان، حدود ۵۰ دقیقه با سرد شدن.","en":"Easy no-cook Persian cold soup for 4: yogurt and doogh with cucumber, walnuts, raisins, fresh herbs, dried mint and rose petals, served with dry bread.","ar":"طريقة عمل آب دوغ خيار لأربعة أشخاص: لبن ودوغ مع الخيار والجوز والزبيب والأعشاب والنعناع اليابس وبتلات الورد، مع الخبز اليابس؛ سهل وبلا طهي."},"servings":4,"prep":20,"cook":0,"rest":30,"total":50,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"ماست پرچرب","en":"Full-fat yogurt","ar":"لبن زبادي كامل الدسم"},"amount":"500","unit":"گرم","optional":false,"group":{"fa":"پایه","en":"Base","ar":"القاعدة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"دوغ بدون گاز","en":"Still doogh","ar":"دوغ غير غازي"},"amount":"750","unit":"میلی‌لیتر","optional":false,"group":{"fa":"پایه","en":"Base","ar":"القاعدة"},"note":{"fa":"یا ۳۰۰ گرم ماست اضافه با ۵۰۰ میلی‌لیتر آب سرد.","en":"Or 300 g extra yogurt whisked with 500 ml cold water.","ar":"أو ٣٠٠ غرام لبن إضافي مخفوق مع ٥٠٠ مل ماء بارد."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"پایه","en":"Base","ar":"القاعدة"},"note":{"fa":"اگر دوغ شور است، کمتر.","en":"Less if the doogh is salty.","ar":"أقل إن كان الدوغ مالحًا."}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"پایه","en":"Base","ar":"القاعدة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"خیار","en":"Cucumber","ar":"خيار"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"متوسط (حدود ۴۰۰ گرم)، ریز خردشده یا درشت رنده‌شده.","en":"Medium (about 400 g), finely diced or coarsely grated.","ar":"متوسطة (نحو ٤٠٠ غرام)، مفرومة ناعمًا أو مبشورة خشنًا."}},{"name":{"fa":"گردو","en":"Walnuts","ar":"جوز"},"amount":"60","unit":"گرم","optional":false,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"درشت خردشده.","en":"Roughly chopped.","ar":"مفروم خشنًا."}},{"name":{"fa":"کشمش","en":"Raisins","ar":"زبيب"},"amount":"50","unit":"گرم","optional":false,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"سبزی تازه (نعناع، ترخون، ریحان، تره)","en":"Fresh herbs (mint, tarragon, basil, chives)","ar":"أعشاب طازجة (نعناع، طرخون، ريحان، ثوم معمّر)"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"حدود ۴۰ گرم، ریز خردشده.","en":"About 40 g, finely chopped.","ar":"نحو ٤٠ غرامًا، مفرومة ناعمًا."}},{"name":{"fa":"نعناع خشک","en":"Dried mint","ar":"نعناع يابس"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"پونهٔ خشک","en":"Dried pennyroyal","ar":"فوتنج يابس"},"amount":"1","unit":"قاشق چای‌خوری","optional":true,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"اختیاری.","en":"Optional.","ar":"اختياري."}},{"name":{"fa":"گل‌سرخ خشک (گل محمدی)","en":"Dried rose petals","ar":"بتلات ورد يابسة"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"افزودنی‌ها","en":"Add-ins","ar":"الإضافات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"یخ","en":"Ice cubes","ar":"مكعبات ثلج"},"amount":"8","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نان خشک (سنگک یا لواش)","en":"Dry bread (sangak or lavash)","ar":"خبز يابس (سنكك أو لواش)"},"amount":"100","unit":"گرم","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) کشمش را بشویید و ۱۰ دقیقه در آب سرد بخیسانید تا پف کند، سپس آبکش کنید.\\n۲) در همین فاصله خیارها را بشویید و ریز خرد یا درشت رنده کنید.\\n۳) گردو را درشت خرد کنید و سبزی‌ها را بشویید، کاملاً خشک و ریز خرد کنید.","en":"1) Rinse the raisins and soak in cold water for 10 minutes until plump, then drain.\\n2) Meanwhile wash the cucumbers and finely dice or coarsely grate them.\\n3) Roughly chop the walnuts; wash, dry thoroughly and finely chop the herbs.","ar":"١) اغسل الزبيب وانقعه في ماء بارد ١٠ دقائق حتى ينتفخ ثم صفّه.\\n٢) في الأثناء اغسل الخيار وافرمه ناعمًا أو ابشره خشنًا.\\n٣) افرم الجوز خشنًا، واغسل الأعشاب وجففها جيدًا وافرمها ناعمًا."},"time":12,"image":{"src":"/recipes/ab-doogh-khiar/step-01.webp","alt":"کشمش خیس‌خورده، خیار خردشده، گردوی خردشده و سبزی تازه روی تخته","width":1200,"height":900}},{"n":2,"title":{"fa":"مخلوط کردن","en":"Combine","ar":"الخلط"},"text":{"fa":"ماست را در کاسهٔ بزرگ با همزن دستی ۱ دقیقه بزنید تا صاف و بی‌گلوله شود. دوغ را کم‌کم اضافه کنید و هم بزنید. نمک و فلفل سیاه را بریزید. خیار، گردو، کشمش و سبزی تازه را اضافه کنید. نعناع خشک، پونه و گل‌سرخ را کف دست بسایید و روی کاسه بریزید و هم بزنید.","en":"Whisk the yogurt in a large bowl for 1 minute until smooth and lump-free. Gradually whisk in the doogh. Add the salt and black pepper. Add the cucumber, walnuts, raisins and fresh herbs. Rub the dried mint, pennyroyal and rose petals between your palms over the bowl and stir.","ar":"اخفق اللبن في وعاء كبير دقيقة حتى يصبح ناعمًا بلا كتل، وأضف الدوغ تدريجيًا مع الخفق. أضف الملح والفلفل الأسود، ثم الخيار والجوز والزبيب والأعشاب الطازجة. افرك النعناع اليابس والفوتنج والورد بين كفيك فوق الوعاء وقلّب."},"time":8,"image":{"src":"/recipes/ab-doogh-khiar/step-02.webp","alt":"مخلوط ماست و دوغ با خیار، گردو، کشمش و سبزی در کاسهٔ بزرگ","width":1200,"height":900}},{"n":3,"title":{"fa":"سرد کردن","en":"Chill","ar":"التبريد"},"text":{"fa":"روی کاسه را بپوشانید و ۳۰ دقیقه در یخچال بگذارید تا طعم‌ها به هم برسند و کاملاً خنک شود. بچشید و اگر لازم است نمک یا کمی آب سرد اضافه کنید؛ غلظت باید مثل دوغ غلیظ باشد.","en":"Cover and refrigerate for 30 minutes so the flavours meld and it is thoroughly cold. Taste and add salt or a little cold water if needed; it should be as thick as a rich doogh.","ar":"غطِّ الوعاء وضعه في الثلاجة ٣٠ دقيقة لتمتزج النكهات ويبرد تمامًا. تذوّق وأضف الملح أو قليلًا من الماء البارد إن لزم؛ يجب أن يكون قوامه كدوغ كثيف."},"time":30,"image":{"src":"/recipes/ab-doogh-khiar/step-03.webp","alt":"کاسهٔ پوشیدهٔ آب‌دوغ‌خیار در یخچال","width":1200,"height":900}},{"n":4,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"در هر کاسه ۲ تکه یخ بیندازید و آب‌دوغ‌خیار را بکشید. نان خشک را کنار سفره بگذارید تا هر کس درست پیش از خوردن، تکه‌تکه در کاسه‌اش خرد کند.","en":"Put 2 ice cubes in each bowl and ladle in the soup. Put the dry bread on the table so everyone breaks it into their bowl right before eating.","ar":"ضع مكعبي ثلج في كل وعاء واسكب الحساء. ضع الخبز اليابس على المائدة ليفتّته كل شخص في وعائه قبل الأكل مباشرة."},"time":0,"image":{"src":"/recipes/ab-doogh-khiar/step-04.webp","alt":"کشیدن آب‌دوغ‌خیار در کاسه‌های یخ‌دار کنار نان خشک","width":1200,"height":900}}],"tips":{"fa":["ماست پرچرب طعم بهتری می‌دهد.","نان را زود در کاسه نریزید.","نعناع خشک را کف دست بسایید تا عطرش آزاد شود."],"en":["Full-fat yogurt tastes better.","Don\'t add the bread early.","Rub dried mint between your palms to release its aroma."],"ar":["اللبن كامل الدسم أطيب.","لا تضع الخبز مبكرًا.","افرك النعناع اليابس بين كفيك ليفوح عطره."]},"cover":{"src":"/recipes/ab-doogh-khiar/cover.webp","alt":"کاسهٔ آب‌دوغ‌خیار با خیار، گردو، کشمش، سبزی، گل‌سرخ خشک و یخ کنار نان خشک","width":1600,"height":1200},"serving":{"src":"/recipes/ab-doogh-khiar/serving.webp","alt":"دست‌هایی در حال خرد کردن نان خشک در کاسهٔ آب‌دوغ‌خیار","width":1200,"height":1500}},{"id":"ash-jushpareh","country":"IR","slugs":{"fa":"آش-جوشپره","en":"ash-jushpareh","ar":"آش-جوشبره"},"title":{"fa":"آش جوش‌پره","en":"Ash-e Jushpareh (Kashk Dumpling Soup)","ar":"آش جوشبره (حساء العجين المحشو بالكشك)"},"summary":{"fa":"آش خراسانی از خمیرهای کوچک پرشده با پورهٔ عدس و نخود که در آب جوشانده و در سس کشک، پیاز داغ، نعناع داغ و زعفران سرو می‌شود.","en":"A Khorasani soup of small dumplings filled with lentil-and-chickpea pur\xe9e, boiled and then served in a sauce of kashk, fried onion, fried mint and saffron.","ar":"حساء خراساني من قطع عجين صغيرة محشوة بهريس العدس والحمص، تُسلق ثم تُقدَّم في صلصة من الكشك والبصل المقلي والنعناع المقلي والزعفران."},"intro":{"fa":"جوش‌پره از غذاهای قدیمی خراسان است که نامش در تاریخ بیهقی هم آمده و \xabآش جوشپره گناباد\xbb در دی ۱۳۹۹ در فهرست میراث معنوی کشور ثبت شد. اصل کار خمیر نازکی است که مربع‌های کوچکش با پورهٔ حبوبات پر و به هم چسبانده می‌شود؛ شبیه رویولی، ولی با کشک و نعناع داغ ایرانی. کار شکل دادن وقت‌گیر است، پس برای آن حوصله بگذارید یا با جمع خانواده انجامش دهید. حبوبات را از شب قبل خیس کنید.","en":"Jushpareh is an old Khorasani dish mentioned in the medieval Tarikh-e Beyhaqi, and \\"Ash-e Jushpareh of Gonabad\\" was added to Iran\'s national intangible heritage list in Dey 1399 (December 2020–January 2021). Its heart is a thin dough cut into small squares that are filled with legume pur\xe9e and sealed together, rather like ravioli but finished with Iranian kashk and fried mint. Shaping takes time, so be patient or share the work with family. Soak the legumes the night before.","ar":"جوشبره من أطباق خراسان القديمة وورد ذكره في \xabتاريخ البيهقي\xbb، وسُجّل \xabآش جوشبره كناباد\xbb في قائمة التراث الثقافي غير المادي الوطني في دي ١٣٩٩ (كانون الأول/ديسمبر ٢٠٢٠ – كانون الثاني/يناير ٢٠٢١). أساسه عجين رقيق يُقطّع مربعات صغيرة تُحشى بهريس البقول وتُلصق معًا، فيشبه الرافيولي لكنه يُختم بالكشك والنعناع المقلي على الطريقة الإيرانية. التشكيل يستغرق وقتًا، فتحلَّ بالصبر أو شارك العائلة فيه. انقع البقول من الليلة السابقة."},"seoTitle":{"fa":"آش جوش‌پره گنابادی؛ طرز تهیه با کشک و نعناع داغ","en":"Ash-e Jushpareh Recipe (Kashk Dumpling Soup)","ar":"آش جوشبره: طريقة عمل حساء العجين المحشو بالكشك الخراساني"},"seoDescription":{"fa":"طرز تهیه آش جوش‌پره خراسانی برای ۴ کاسه: خمیرهای کوچک پرشده با پورهٔ عدس و نخود در سس کشک، پیاز داغ، نعناع داغ و زعفران؛ حبوبات از شب قبل خیس می‌خورد.","en":"Khorasani soup for 4: small dumplings filled with lentil-chickpea pur\xe9e, served in kashk with fried onion, fried mint and saffron. Legumes soak overnight.","ar":"طريقة عمل آش جوشبره لأربعة أوعية: قطع عجين صغيرة محشوة بهريس العدس والحمص تُقدَّم في الكشك مع البصل المقلي والنعناع المقلي والزعفران؛ تُنقع البقول ليلة."},"servings":4,"prep":65,"cook":115,"rest":750,"total":930,"oven":null,"difficulty":{"fa":"سخت","en":"Hard","ar":"صعب"},"showNutrition":false,"ingredients":[{"name":{"fa":"عدس","en":"Lentils","ar":"عدس"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"پیمانهٔ ۲۴۰ میلی‌لیتری؛ هر سه دستور کامل (کوروش، پاپیون، عالی‌گرد) ۱ پیمانه/لیوان می‌گویند.","en":"240 ml cup; all three full recipes (Kourosh, Papion, Aaligard) use 1 cup.","ar":"كوب ٢٤٠ مل؛ الوصفات الكاملة الثلاث (كوروش، بابيون، عالي‌كرد) تستخدم كوبًا واحدًا."}},{"name":{"fa":"نخود","en":"Chickpeas","ar":"حمص"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"یا لوبیا (پاپیون، عالی‌گرد)؛ پیمانهٔ ۲۴۰ میلی‌لیتری.","en":"Or beans (Papion, Aaligard); 240 ml cup.","ar":"أو فاصوليا (بابيون، عالي‌كرد)؛ كوب ٢٤٠ مل."}},{"name":{"fa":"آب برای پخت حبوبات","en":"Water for cooking the legumes","ar":"ماء لطهي البقول"},"amount":"500","unit":"میلی‌لیتر","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"در مجموع برای دو قابلمه؛ فقط در حدی که روی حبوبات را بپوشاند (کوروش: \xabآب بسیار کم\xbb).","en":"Total for both pots; only enough to just cover the legumes (Kourosh: \\"very little water\\").","ar":"المجموع للقدرين؛ بقدر ما يغطي البقول فقط (كوروش: \xabماء قليل جدًا\xbb)."}},{"name":{"fa":"پیاز برای مواد میانی","en":"Onion for the filling","ar":"بصل للحشوة"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"متوسط، چهار قاچ (کوروش ۱ عدد؛ پاپیون و عالی‌گرد ۲ عدد).","en":"Medium, quartered (Kourosh 1; Papion and Aaligard 2).","ar":"متوسطة، مقطعة أرباعًا (كوروش ١؛ بابيون وعالي‌كرد ٢)."}},{"name":{"fa":"سیر","en":"Garlic","ar":"ثوم"},"amount":"2","unit":"حبه","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای مواد میانی","en":"Salt for the filling","ar":"ملح للحشوة"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زردچوبه برای مواد میانی","en":"Turmeric for the filling","ar":"كركم للحشوة"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مواد میانی","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آرد گندم","en":"Wheat flour","ar":"دقيق القمح"},"amount":"3","unit":"پیمانه","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجين"},"note":{"fa":"پیمانهٔ ۲۴۰ میلی‌لیتری، به‌علاوهٔ کمی برای آردپاشی (کوروش ۳ پیمانه؛ پاپیون و عالی‌گرد ۴ پیمانه برای ۵ نفر).","en":"240 ml cups, plus a little for dusting (Kourosh 3 cups; Papion and Aaligard 4 cups for 5 people).","ar":"أكواب ٢٤٠ مل، مع قليل للرش (كوروش ٣ أكواب؛ بابيون وعالي‌كرد ٤ أكواب لخمسة أشخاص)."}},{"name":{"fa":"آب ولرم","en":"Warm water","ar":"ماء فاتر"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجين"},"note":{"fa":"کم‌کم اضافه شود؛ شاید همه‌اش لازم نشود.","en":"Add gradually; you may not need it all.","ar":"يُضاف تدريجيًا؛ قد لا تحتاجه كله."}},{"name":{"fa":"نمک برای خمیر","en":"Salt for the dough","ar":"ملح للعجين"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجين"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب برای جوشاندن","en":"Water for boiling","ar":"ماء للسلق"},"amount":"3","unit":"لیتر","optional":false,"group":{"fa":"آب جوشاندن","en":"Boiling water","ar":"ماء السلق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای آب","en":"Salt for the water","ar":"ملح للماء"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"آب جوشاندن","en":"Boiling water","ar":"ماء السلق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع برای آب","en":"Oil for the water","ar":"زيت للماء"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"آب جوشاندن","en":"Boiling water","ar":"ماء السلق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"سرکهٔ سیب","en":"Apple vinegar","ar":"خل التفاح"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"آب جوشاندن","en":"Boiling water","ar":"ماء السلق"},"note":{"fa":"یا سرکهٔ انگور.","en":"Or grape vinegar.","ar":"أو خل العنب."}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"6","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"پیاز برای پیاز داغ","en":"Onion for frying","ar":"بصل للقلي"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"متوسط (حدود ۳۰۰ گرم)، خلالی.","en":"Medium (about 300 g), thinly sliced.","ar":"متوسطة (نحو ٣٠٠ غرام)، شرائح رفيعة."}},{"name":{"fa":"زردچوبه برای پیاز داغ","en":"Turmeric for the fried onion","ar":"كركم للبصل المقلي"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نعناع خشک","en":"Dried mint","ar":"نعناع يابس"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"کشک غلیظ","en":"Thick liquid kashk","ar":"كشك سائل كثيف"},"amount":"250","unit":"میلی‌لیتر","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"کوروش ۱ لیوان؛ پاپیون و عالی‌گرد بیشتر و به ذائقه.","en":"Kourosh 1 cup; Papion and Aaligard use more, to taste.","ar":"كوروش كوب واحد؛ بابيون وعالي‌كرد أكثر حسب الذوق."}},{"name":{"fa":"آب جوشاندن جوش‌پره","en":"Dumpling cooking water","ar":"ماء سلق قطع العجين"},"amount":"500","unit":"میلی‌لیتر","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"از قابلمهٔ جوشاندن برداشته شود.","en":"Taken from the boiling pot.","ar":"يؤخذ من قدر السلق."}},{"name":{"fa":"زعفران سابیده","en":"Ground saffron","ar":"زعفران مطحون"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب جوش برای دم کردن زعفران","en":"Boiling water for blooming the saffron","ar":"ماء مغلي لنقع الزعفران"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"سس کشک و پیاز داغ","en":"Kashk and fried-onion sauce","ar":"صلصة الكشك والبصل المقلي"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"مغز گردو","en":"Walnut kernels","ar":"لب الجوز"},"amount":"30","unit":"گرم","optional":false,"group":{"fa":"تزئین","en":"Garnish","ar":"التزيين"},"note":{"fa":"خردشده.","en":"Chopped.","ar":"مفروم."}},{"name":{"fa":"کنجد","en":"Sesame seeds","ar":"سمسم"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"تزئین","en":"Garnish","ar":"التزيين"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) عدس و نخود را جداگانه بشویید و سنگ‌ریزه‌ها را جدا کنید.\\n۲) هر کدام را در کاسه‌ای جدا با دو برابر حجمشان آب سرد بریزید.\\n۳) پیاز را چهار قاچ کنید و سیر را پوست بگیرید (برای روز بعد در یخچال بگذارید).","en":"1) Rinse the lentils and chickpeas separately and pick out any stones.\\n2) Cover each in its own bowl with twice its volume of cold water.\\n3) Quarter the onion and peel the garlic (keep in the fridge for the next day).","ar":"١) اغسل العدس والحمص كلًّا على حدة وانزع الحصى.\\n٢) غطِّ كلًّا منهما في وعاء منفصل بضعف حجمه من الماء البارد.\\n٣) قطّع البصل أرباعًا وقشّر الثوم (احفظهما في الثلاجة لليوم التالي)."},"time":15,"image":{"src":"/recipes/ash-jushpareh/step-01.webp","alt":"عدس و نخود خیس در آب، پیاز چهارقاچ و حبه‌های سیر","width":1200,"height":900}},{"n":2,"title":{"fa":"خیساندن حبوبات","en":"Soak the legumes","ar":"نقع البقول"},"text":{"fa":"حبوبات را ۱۲ ساعت (یک شب) خیس کنید و ۲ تا ۳ بار آبش را عوض کنید (عالی‌گرد برای نخود یا لوبیا تا ۲۴ ساعت هم می‌گوید).","en":"Soak the legumes for 12 hours (overnight), changing the water 2–3 times (Aaligard allows up to 24 hours for chickpeas or beans).","ar":"انقع البقول ١٢ ساعة (ليلة كاملة) وغيّر الماء ٢–٣ مرات (يسمح عالي‌كرد بما يصل إلى ٢٤ ساعة للحمص أو الفاصوليا)."},"time":720,"image":{"src":"/recipes/ash-jushpareh/step-02.webp","alt":"نخود و عدس خیس‌خورده و پف‌کرده در آب","width":1200,"height":900}},{"n":3,"title":{"fa":"پخت حبوبات و تهیهٔ مواد میانی","en":"Cook the legumes and make the filling","ar":"طهي البقول وتحضير الحشوة"},"text":{"fa":"حبوبات را آبکش کنید. نخود و عدس را در دو قابلمهٔ کوچک جدا بریزید، چون عدس زودتر می‌پزد؛ در هر قابلمه فقط آنقدر آب بریزید که رویش را بپوشاند و زردچوبه را به نخود اضافه کنید. روی حرارت زیاد به جوش بیاورید، کف را بگیرید و روی حرارت ملایم با درِ نیمه‌باز بپزید: عدس را همین که نرم شد بردارید و نخود را تا حدود ۴۵ دقیقه، تا بین دو انگشت به‌راحتی له شود. حبوبات باید تقریباً خشک باشند؛ هر ۱۰ دقیقه سر بزنید و اگر ته‌گرفتن شروع شد ۲ تا ۳ قاشق آب اضافه کنید، و اگر در پایان آب ماند، آبکش کنید. حبوبات پخته را با پیاز چهارقاچ، سیر، نمک و فلفل سیاه در غذاساز بریزید و ۱ تا ۲ دقیقه بزنید تا پوره‌ای غلیظ و یکدست شود که با قاشق شکلش را حفظ کند. بگذارید سرد شود.","en":"Drain the legumes. Put the chickpeas and lentils in two separate small pots, since lentils cook faster; add only enough water to cover each, and add the turmeric to the chickpeas. Bring to a boil on high, skim, then simmer on low with the lids ajar: take the lentils off as soon as they are soft, and cook the chickpeas for about 45 minutes, until they crush easily between two fingers. The legumes should end up almost dry; check every 10 minutes, add 2–3 tbsp water if they start to catch, and drain off any water left at the end. Put the cooked legumes with the quartered onion, garlic, salt and black pepper in a food processor and blitz 1–2 minutes into a thick, smooth pur\xe9e that holds its shape on a spoon. Let it cool.","ar":"صفِّ البقول. ضع الحمص والعدس في قدرين صغيرين منفصلين لأن العدس ينضج أسرع؛ أضف إلى كل قدر ماءً يغطيها فقط، وأضف الكركم إلى الحمص. اغلِها على نار عالية وأزل الرغوة، ثم اطهُها على نار هادئة والغطاء موارب: ارفع العدس حالما يطرى، واطهُ الحمص نحو ٤٥ دقيقة حتى يُهرس بسهولة بين إصبعين. يجب أن تكون البقول شبه جافة في النهاية؛ تفقّدها كل ١٠ دقائق وأضف ٢–٣ ملاعق ماء إن بدأت تلتصق، وصفِّ أي ماء متبقٍ في النهاية. ضع البقول المطهوة مع البصل والثوم والملح والفلفل الأسود في محضّرة الطعام واخلطها ١–٢ دقيقة حتى تصير هريسًا كثيفًا متجانسًا يحتفظ بشكله على الملعقة. اتركها تبرد."},"time":50,"image":{"src":"/recipes/ash-jushpareh/step-03.webp","alt":"پورهٔ غلیظ و طلایی عدس و نخود در کاسهٔ غذاساز","width":1200,"height":900}},{"n":4,"title":{"fa":"تهیهٔ خمیر","en":"Make the dough","ar":"تحضير العجين"},"text":{"fa":"آرد و نمک را الک کنید. آب ولرم را کم‌کم اضافه کنید و با دست مخلوط کنید و فقط تا جایی آب بریزید که خمیر جمع شود. ۸ تا ۱۰ دقیقه ورز دهید تا خمیر نرم، صاف و غیرچسبنده شود.","en":"Sift the flour and salt. Add the warm water gradually, mixing by hand, only until the dough comes together. Knead 8–10 minutes until soft, smooth and not sticky.","ar":"انخل الدقيق والملح. أضف الماء الفاتر تدريجيًا مع الخلط باليد حتى يتماسك العجين فقط. اعجن ٨–١٠ دقائق حتى يصبح طريًا أملس غير لزج."},"time":10,"image":{"src":"/recipes/ash-jushpareh/step-04.webp","alt":"گلولهٔ خمیر صاف گندم روی تختهٔ آردپاشی‌شده","width":1200,"height":900}},{"n":5,"title":{"fa":"استراحت خمیر و پیاز داغ","en":"Rest the dough and fry the onion","ar":"إراحة العجين وقلي البصل"},"text":{"fa":"خمیر را با سلفون بپوشانید و ۳۰ دقیقه در دمای اتاق استراحت دهید؛ وقتی با انگشت فشار دهید باید فوراً برگردد. در همین ۳۰ دقیقه (هم‌زمان، جدا شمرده نشده) پیاز داغ را آماده کنید: ۵ قاشق غذاخوری روغن را در تابه روی حرارت متوسط داغ کنید، پیاز خلالی را ۱۵ تا ۱۸ دقیقه تفت دهید تا طلایی‌قهوه‌ای شود و زردچوبه را در دقیقهٔ آخر اضافه کنید. نصف پیاز داغ را برای تزئین بردارید. حرارت را خاموش کنید، ۱ قاشق غذاخوری روغن باقی‌مانده را در گوشهٔ تابه بریزید، نعناع خشک را در آن بریزید و فقط ۱۰ ثانیه هم بزنید؛ نعناع نباید سیاه شود.","en":"Cover the dough with cling film and rest 30 minutes at room temperature; it should spring back at once when pressed. During these 30 minutes (concurrent, not counted separately) make the fried onion: heat 5 tbsp oil in a frying pan over medium heat and fry the sliced onion 15–18 minutes until golden brown, adding the turmeric in the last minute. Set half aside for garnish. Turn off the heat, add the remaining 1 tbsp oil to one side of the pan, stir in the dried mint for just 10 seconds; the mint must not turn black.","ar":"غطِّ العجين بغلاف بلاستيكي واتركه ٣٠ دقيقة في حرارة الغرفة؛ يجب أن يرتد فورًا عند الضغط عليه. خلال هذه الدقائق الثلاثين (بالتزامن، غير محسوبة منفصلة) حضّر البصل المقلي: سخّن ٥ ملاعق كبيرة من الزيت في مقلاة على نار متوسطة واقلِ البصل ١٥–١٨ دقيقة حتى يصبح ذهبيًا بنيًا، وأضف الكركم في الدقيقة الأخيرة. ضع نصفه جانبًا للتزيين. أطفئ النار وأضف ملعقة الزيت المتبقية إلى جانب المقلاة وقلّب فيها النعناع اليابس ١٠ ثوانٍ فقط؛ يجب ألا يسودّ."},"time":30,"image":{"src":"/recipes/ash-jushpareh/step-05.webp","alt":"خمیر پوشیده در حال استراحت کنار تابهٔ پیاز داغ طلایی و نعناع داغ","width":1200,"height":900}},{"n":6,"title":{"fa":"باز کردن و شکل دادن","en":"Roll out and shape","ar":"الفرد والتشكيل"},"text":{"fa":"سطح کار را آردپاشی کنید و خمیر را در دو نوبت با وردنه نازک باز کنید، حداکثر حدود ۵ میلی‌متر (نوبت دوم را زیر پارچه نگه دارید تا خشک نشود). با چاقو یا چرخ برش، مربع‌های ۴\xd7۴ سانتی ببرید. وسط نیمی از مربع‌ها به اندازهٔ نصف تا یک بند انگشت مواد میانی بگذارید، لبه‌ها را با انگشت خیس کنید، یک مربع دیگر رویش بگذارید و دور تا دور را مثل قطاب با فشار انگشت یا نوک چنگال محکم ببندید تا هوایی داخلش نماند و در آب باز نشود. جوش‌پره‌ها را روی سینی آردپاشی‌شده جدا از هم بچینید.","en":"Flour the work surface and roll the dough out thinly in two batches, to about 5 mm at most (keep the second batch under a cloth so it doesn\'t dry). Cut into 4\xd74 cm squares with a knife or pastry wheel. Put a half to a whole fingertip-joint of filling in the centre of half the squares, wet the edges with a fingertip, lay another square on top and press all round firmly, like qottab, with your fingers or a fork so no air is trapped and they don\'t open in the water. Lay the dumplings apart on a floured tray.","ar":"رشّ سطح العمل بالدقيق وافرد العجين رقيقًا على دفعتين، بسماكة ٥ ملم تقريبًا كحد أقصى (أبقِ الدفعة الثانية تحت قماشة كي لا تجف). قطّعه مربعات ٤\xd7٤ سم بسكين أو عجلة. ضع من الحشوة بقدر نصف عقلة إصبع إلى عقلة كاملة وسط نصف المربعات، وبلّل الحواف بطرف الإصبع، وضع مربعًا آخر فوقها واضغط حولها جيدًا كالقطّاب بالأصابع أو الشوكة حتى لا يبقى هواء ولا تنفتح في الماء. رصّ قطع العجين المحشوة متباعدةً على صينية مرشوشة بالدقيق."},"time":40,"image":{"src":"/recipes/ash-jushpareh/step-06.webp","alt":"بستن جوش‌پره‌های مربعی پر از پورهٔ حبوبات روی تختهٔ آردپاشی‌شده","width":1200,"height":900}},{"n":7,"title":{"fa":"جوشاندن جوش‌پره‌ها","en":"Boil the dumplings","ar":"سلق قطع العجين المحشوة"},"text":{"fa":"۳ لیتر آب را با نمک، ۱ قاشق غذاخوری روغن و سرکهٔ سیب در قابلمهٔ بزرگ روی حرارت زیاد به جوش بیاورید (حدود ۱۰ دقیقه). جوش‌پره‌ها را یکی‌یکی و در دو نوبت در آب بریزید، یک بار آرام هم بزنید تا به ته نچسبند، و حرارت را متوسط کنید تا جوش ملایم بماند. حدود ۴۰ دقیقه بجوشانید؛ از دقیقهٔ ۲۰ با تست پختگی امتحان کنید و اگر هنوز خام بود، تا ۶۰ دقیقه ادامه دهید. تست پختگی: جوش‌پره‌ها روی آب آمده‌اند، لبه‌های خمیر نیمه‌شفاف است و اگر یکی را نصف کنید، لایهٔ سفید و خام آرد در خمیر نمی‌بینید. ۵۰۰ میلی‌لیتر از آب جوشاندن را برای سس بردارید، سپس جوش‌پره‌ها را با کفگیر سوراخ‌دار بیرون بیاورید.","en":"Bring the 3 L water, salt, 1 tbsp oil and apple vinegar to a boil in a large pot over high heat (about 10 minutes). Drop the dumplings in one by one, in two batches, stir gently once so they don\'t stick, and lower to medium for a steady simmer. Boil about 40 minutes; start testing from 20 minutes, and if they are still raw continue up to 60 minutes. Doneness test: the dumplings float, the dough edges look translucent, and a halved one shows no raw white floury layer. Reserve 500 ml of the cooking water for the sauce, then lift out the dumplings with a slotted spoon.","ar":"اغلِ ٣ لترات من الماء مع الملح وملعقة كبيرة من الزيت وخل التفاح في قدر كبير على نار عالية (نحو ١٠ دقائق). أسقط قطع العجين المحشوة واحدةً واحدةً على دفعتين، وقلّب برفق مرة كي لا تلتصق، وخفّف إلى متوسطة ليبقى الغليان هادئًا. اسلقها نحو ٤٠ دقيقة؛ ابدأ الاختبار من الدقيقة ٢٠، وإن بقيت نيئة فاستمر حتى ٦٠ دقيقة. اختبار النضج: تطفو القطع، وتبدو حواف العجين شبه شفافة، ولا ترى طبقة دقيق بيضاء نيئة عند قطع واحدة نصفين. احتفظ بـ٥٠٠ مل من ماء السلق للصلصة ثم أخرج قطع العجين بمغرفة مثقبة."},"time":50,"image":{"src":"/recipes/ash-jushpareh/step-07.webp","alt":"جوش‌پره‌های مربعی شناور در قابلمهٔ آب در حال جوشیدن","width":1200,"height":900}},{"n":8,"title":{"fa":"سس کشک","en":"Kashk sauce","ar":"صلصة الكشك"},"text":{"fa":"زعفران را با ۲ قاشق غذاخوری آب جوش دم کنید. کشک را با ۵۰۰ میلی‌لیتر آب جوشاندن در قابلمهٔ پهن هم بزنید تا یکدست شود، نیمی از پیاز داغ و نعناع داغ را اضافه کنید و روی حرارت متوسط مدام هم بزنید تا به جوش بیاید؛ ۵ دقیقه بگذارید بجوشد (کشک باید حتماً بجوشد). زعفران دم‌کرده را اضافه کنید.","en":"Bloom the saffron in 2 tbsp boiling water. Whisk the kashk with the 500 ml reserved cooking water in a wide pot until smooth, add half the fried onion and mint, and stir constantly over medium heat until it boils; let it boil 5 minutes (kashk must be boiled). Add the saffron water.","ar":"انقع الزعفران في ملعقتين كبيرتين من الماء المغلي. اخفق الكشك مع ٥٠٠ مل من ماء السلق المحفوظ في قدر عريض حتى يتجانس، وأضف نصف البصل المقلي والنعناع، وقلّب باستمرار على نار متوسطة حتى يغلي؛ اتركه يغلي ٥ دقائق (يجب غلي الكشك). أضف ماء الزعفران."},"time":10,"image":{"src":"/recipes/ash-jushpareh/step-08.webp","alt":"سس کشک با پیاز داغ و زعفران در حال جوشیدن در قابلمهٔ پهن","width":1200,"height":900}},{"n":9,"title":{"fa":"ترکیب و سرو","en":"Combine and serve","ar":"الدمج والتقديم"},"text":{"fa":"جوش‌پره‌ها را آرام در سس کشک بریزید و ۵ دقیقه روی حرارت ملایم بگذارید تا سس کمی غلیظ شود و به جوش‌پره‌ها بچسبد؛ با کفگیر از زیر آرام برگردانید تا پاره نشوند. نمک را بچشید (کشک شور است، معمولاً نمک لازم نیست). در کاسه بکشید و با باقی پیاز داغ، نعناع داغ، گردو و کنجد تزئین کنید.","en":"Gently tip the dumplings into the kashk sauce and leave 5 minutes on low until the sauce thickens slightly and clings to them; fold gently from below so they don\'t tear. Taste for salt (kashk is salty; usually none is needed). Ladle into bowls and garnish with the remaining fried onion and mint, walnuts and sesame.","ar":"اسكب قطع العجين المحشوة برفق في صلصة الكشك واتركها ٥ دقائق على نار هادئة حتى تتكاثف الصلصة قليلًا وتلتصق بها؛ قلّب من الأسفل برفق كي لا تتمزق. تذوّق الملح (الكشك مالح وغالبًا لا حاجة إليه). اسكبها في الأوعية وزيّنها بباقي البصل والنعناع المقلي والجوز والسمسم."},"time":5,"image":{"src":"/recipes/ash-jushpareh/step-09.webp","alt":"کاسهٔ آش جوش‌پره با سس کشک، پیاز داغ، نعناع داغ، گردو و کنجد","width":1200,"height":900}}],"tips":{"fa":["مواد میانی باید غلیظ باشد؛ پورهٔ آبکی از خمیر بیرون می‌زند.","خمیر باز شده را زیر پارچه نگه دارید.","جوش‌پرهٔ خام را می‌توان روی سینی فریز کرد و بعد در کیسه ریخت."],"en":["The filling must be thick; a runny pur\xe9e leaks out.","Keep rolled dough under a cloth.","Raw dumplings can be tray-frozen, then bagged."],"ar":["يجب أن تكون الحشوة كثيفة؛ الهريس المائي يتسرب.","أبقِ العجين المفرود تحت قماشة.","يمكن تجميد قطع العجين المحشوة النيئة على صينية ثم وضعها في كيس."]},"cover":{"src":"/recipes/ash-jushpareh/cover.webp","alt":"کاسهٔ آش جوش‌پره با سس کشک، پیاز داغ، نعناع داغ، زعفران، گردو و کنجد","width":1600,"height":1200},"serving":{"src":"/recipes/ash-jushpareh/serving.webp","alt":"کاسهٔ بزرگ آش جوش‌پره با نان تافتون و کاسه‌های پیاز داغ و نعناع داغ","width":1200,"height":1500}},{"id":"chelow-kabab","country":"IR","slugs":{"fa":"چلوکباب","en":"chelow-kabab","ar":"تشلو-كباب"},"title":{"fa":"چلوکباب","en":"Chelow Kabab","ar":"تشلو كباب"},"summary":{"fa":"چلوی زعفرانی دم‌کشیده با کباب کوبیدهٔ گوسفندی و گوساله، گوجهٔ کبابی، سماق و کره؛ غذای ملی و رستورانی ایران.","en":"Saffron-crowned steamed Persian rice served with skewers of minced lamb-and-beef koobideh, charred tomatoes, sumac and butter: Iran\'s classic restaurant meal.","ar":"أرز فارسي مطهو بالبخار يعلوه الزعفران، يُقدَّم مع أسياخ الكباب الكوبيده من لحم الضأن والعجل المفروم، والطماطم المشوية والسمّاق والزبدة؛ الوجبة الإيرانية الكلاسيكية في المطاعم."},"intro":{"fa":"چلوکباب ترکیب دو مهارت پایه‌ی آشپزی ایرانی است: چلوی آبکش و دم‌کشیده که دانه‌هایش بلند و جدا از هم می‌ماند، و کباب کوبیده که از گوشت چرخ‌کردهٔ چرب، پیاز آب‌گرفته، نمک و فلفل درست می‌شود و روی زغال پخته می‌شود. راز کار در سه چیز است: گوشت با چربی کافی، ورز طولانی تا مایه چسبناک شود، و استراحت مایه در یخچال تا روی سیخ بماند. این دستور برای ۴ نفر و ۸ سیخ است و چلو و کباب را طوری زمان‌بندی می‌کند که هم‌زمان آماده شوند.","en":"Chelow kabab joins two core Persian techniques: parboiled, steamed rice whose long grains stay separate, and koobideh, a kebab of fatty minced meat, squeezed onion, salt and pepper cooked over charcoal. Three things matter most: meat with enough fat, long kneading until the mixture turns sticky, and a rest in the fridge so it clings to the skewer. This recipe makes 8 skewers for 4 people and times the rice and kebab to finish together.","ar":"يجمع تشلو كباب بين مهارتين أساسيتين في المطبخ الإيراني: الأرز المسلوق جزئيًا ثم المطهو بالبخار بحيث تبقى حبّاته الطويلة منفصلة، والكباب الكوبيده المصنوع من اللحم المفروم الدسم والبصل المعصور والملح والفلفل ويُشوى على الفحم. يتوقف النجاح على ثلاثة أمور: لحم بنسبة دهن كافية، وعجن طويل حتى يصبح الخليط لزجًا، وتبريد الخليط في الثلاجة كي يثبت على السيخ. تكفي هذه الوصفة ٤ أشخاص (٨ أسياخ)، ومواعيدها مضبوطة لينضج الأرز والكباب معًا."},"seoTitle":{"fa":"چلوکباب؛ طرز تهیه با کوبیده زغالی و چلوی زعفرانی","en":"Chelow Kabab Recipe (Persian Saffron Rice with Kebab)","ar":"تشلو كباب: طريقة عمل الأرز بالزعفران مع الكباب المشوي"},"seoDescription":{"fa":"طرز تهیه چلوکباب برای ۴ نفر: چلوی زعفرانی دم‌کشیده با کوبیدهٔ گوسفندی و گوساله روی زغال، گوجه کبابی، سماق و کره؛ حدود ۳.۵ ساعت با استراحت مایه.","en":"Persian chelow kabab for 4: steamed saffron rice with charcoal-grilled lamb-and-beef kebab, charred tomatoes, sumac and butter. About 3.5 h incl. resting.","ar":"طريقة عمل تشلو كباب لأربعة أشخاص: أرز بالزعفران مع كباب الضأن والعجل المفروم على الفحم، وطماطم مشوية وسمّاق وزبدة؛ نحو ٣.٥ ساعات مع الراحة."},"servings":4,"prep":30,"cook":63,"rest":120,"total":213,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"گوشت چرخ‌کردهٔ گوسفندی","en":"Minced lamb","ar":"لحم ضأن مفروم"},"amount":"500","unit":"گرم","optional":false,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"از سردست یا گردن با حدود ۲۰٪ چربی؛ دو بار چرخ‌شده.","en":"Shoulder or neck with about 20% fat, minced twice.","ar":"من الكتف أو الرقبة بنسبة دهن نحو ٢٠٪، مفروم مرتين."}},{"name":{"fa":"گوشت چرخ‌کردهٔ گوساله","en":"Minced veal","ar":"لحم عجل مفروم"},"amount":"300","unit":"گرم","optional":false,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"دو بار چرخ‌شده.","en":"Minced twice.","ar":"مفروم مرتين."}},{"name":{"fa":"دنبه","en":"Lamb tail fat","ar":"ألية الخروف"},"amount":"50","unit":"گرم","optional":true,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"فقط اگر گوشت کم‌چرب است؛ ریز چرخ یا رنده‌شده.","en":"Only if the meat is lean; finely minced or grated.","ar":"فقط إذا كان اللحم قليل الدهن؛ مفرومة أو مبشورة ناعمًا."}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"متوسط (حدود ۳۰۰ گرم)؛ رنده و کاملاً آب‌گرفته، حدود ۲۰۰ گرم پس از آب‌گیری.","en":"Medium (about 300 g); grated and squeezed very dry, about 200 g after squeezing.","ar":"متوسطة (نحو ٣٠٠ غرام)؛ مبشورة ومعصورة جيدًا، نحو ٢٠٠ غرام بعد العصر."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"2","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"تازه آسیاب‌شده.","en":"Freshly ground.","ar":"مطحون طازج."}},{"name":{"fa":"جوش شیرین","en":"Baking soda","ar":"بيكربونات الصوديوم"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":true,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"روش رستورانی برای چسبندگی بیشتر؛ بیشتر نریزید چون طعم صابونی می‌دهد.","en":"Restaurant trick for extra binding; do not use more or it tastes soapy.","ar":"حيلة المطاعم لزيادة التماسك؛ لا تزد الكمية وإلا ظهر طعم صابوني."}},{"name":{"fa":"گوجه‌فرنگی","en":"Tomato","ar":"طماطم"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"کباب کوبیده","en":"Koobideh kebab","ar":"الكباب الكوبيده"},"note":{"fa":"متوسط و سفت، برای کباب کردن.","en":"Medium and firm, for grilling.","ar":"متوسطة ومتماسكة، للشوي."}},{"name":{"fa":"برنج ایرانی دانه‌بلند","en":"Iranian long-grain rice","ar":"أرز إيراني طويل الحبة"},"amount":"3","unit":"پیمانه","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"حدود ۶۰۰ گرم.","en":"About 600 g.","ar":"نحو ٦٠٠ غرام."}},{"name":{"fa":"آب برای خیساندن برنج","en":"Water for soaking the rice","ar":"ماء لنقع الأرز"},"amount":"1500","unit":"میلی‌لیتر","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای خیساندن برنج","en":"Salt for soaking the rice","ar":"ملح لنقع الأرز"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب برای جوشاندن برنج","en":"Water for boiling the rice","ar":"ماء لسلق الأرز"},"amount":"3","unit":"لیتر","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای آب جوش برنج","en":"Salt for the rice boiling water","ar":"ملح لماء سلق الأرز"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب برای دم کردن برنج","en":"Water for steaming the rice","ar":"ماء لتبخير الأرز"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زعفران سابیده","en":"Ground saffron","ar":"زعفران مطحون"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب جوش برای دم کردن زعفران","en":"Boiling water for blooming the saffron","ar":"ماء مغلي لنقع الزعفران"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"کره","en":"Butter","ar":"زبدة"},"amount":"40","unit":"گرم","optional":false,"group":{"fa":"چلو","en":"Chelow (steamed rice)","ar":"الأرز المطهو بالبخار (تشلو)"},"note":{"fa":"۲۰ گرم روی چلو، ۲۰ گرم آب‌شده برای کباب‌ها.","en":"20 g on the rice, 20 g melted for brushing the kebabs.","ar":"٢٠ غرامًا على الأرز و٢٠ غرامًا مذابة لدهن الكباب."}},{"name":{"fa":"سماق","en":"Sumac","ar":"سمّاق"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"ریحان تازه","en":"Fresh basil","ar":"ريحان طازج"},"amount":"1","unit":"پیمانه","optional":true,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"شاخه‌ای، شسته و خشک‌شده.","en":"Sprigs, washed and dried.","ar":"أغصان مغسولة ومجففة."}},{"name":{"fa":"زردهٔ تخم‌مرغ","en":"Egg yolk","ar":"صفار بيض"},"amount":"4","unit":"عدد","optional":true,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"سنتی است و خام روی چلو داغ می‌ریزند؛ فقط با تخم‌مرغ تازه و پاستوریزه. برای کودکان، باردارها و سالمندان حذف کنید.","en":"Traditionally served raw on the hot rice; use only very fresh, pasteurised eggs. Leave out for children, pregnant people and the elderly.","ar":"يُقدَّم تقليديًا نيئًا فوق الأرز الساخن؛ استخدم بيضًا طازجًا مبسترًا فقط، واحذفه للأطفال والحوامل وكبار السن."}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) برنج را در کاسهٔ بزرگ ۴ تا ۵ بار با آب سرد آرام بشویید تا آب تقریباً زلال شود. ۱۵۰۰ میلی‌لیتر آب و ۲ قاشق غذاخوری نمک را رویش بریزید و کنار بگذارید (۲ ساعت هم‌زمان با استراحت گوشت خیس می‌خورد).\\n۲) پیازها را پوست بگیرید و با رندهٔ ریز رنده کنید. رندهٔ پیاز را در پارچهٔ تمیز بپیچید و محکم فشار دهید تا تقریباً خشک شود. آب پیاز را برای خیس کردن دست هنگام سیخ کشیدن نگه دارید.\\n۳) اگر دنبه دارید آن را بسیار ریز خرد یا رنده کنید.\\n۴) زعفران سابیده را در فنجان کوچک بریزید، ۳ قاشق غذاخوری آب جوش رویش بریزید و درش را بگذارید تا دم بکشد.","en":"1) Rinse the rice gently in a large bowl with cold water 4–5 times until the water is almost clear. Cover with 1500 ml water and 2 tbsp salt and set aside (it soaks for 2 hours while the meat rests).\\n2) Peel the onions and grate them finely. Wrap the pulp in a clean cloth and squeeze hard until almost dry. Keep the onion juice for wetting your hands while skewering.\\n3) If using tail fat, chop or grate it very finely.\\n4) Put the ground saffron in a small cup, pour over 3 tbsp boiling water, cover and leave to bloom.","ar":"١) اغسل الأرز برفق في وعاء كبير بالماء البارد ٤–٥ مرات حتى يصفو الماء تقريبًا. أضف ١٥٠٠ ملليلتر من الماء وملعقتين كبيرتين من الملح واتركه جانبًا (ينقع ساعتين أثناء راحة اللحم).\\n٢) قشّر البصل وابشره بالمبشرة الناعمة، ثم لفّه في قطعة قماش نظيفة واعصره بقوة حتى يجف تقريبًا. احتفظ بعصير البصل لترطيب يديك عند التسييخ.\\n٣) إن استخدمت الألية فافرمها أو ابشرها ناعمًا جدًا.\\n٤) ضع الزعفران المطحون في فنجان صغير، واسكب فوقه ٣ ملاعق كبيرة من الماء المغلي، وغطّه ليتشرّب."},"time":15,"image":{"src":"/recipes/chelow-kabab/step-01.webp","alt":"برنج خیس‌خورده در کاسهٔ آب و پیاز رنده‌شده در پارچه برای گرفتن آب","width":1200,"height":900}},{"n":2,"title":{"fa":"ورز دادن مایهٔ کباب","en":"Knead the kebab mixture","ar":"عجن خليط الكباب"},"text":{"fa":"هر دو گوشت، دنبه، پیاز آب‌گرفته، نمک، فلفل سیاه و جوش شیرین (اگر استفاده می‌کنید) را در کاسهٔ بزرگ بریزید. با یک دست ۱۵ دقیقه ورز دهید و مایه را مدام به دیوارهٔ کاسه بکوبید. تست آمادگی: مایه رنگ روشن‌تر و حالت چسبناک پیدا می‌کند و وقتی یک مشت از آن را برمی‌دارید، کش می‌آید و خرد نمی‌شود.","en":"Put both meats, the tail fat, squeezed onion, salt, black pepper and baking soda (if using) in a large bowl. Knead with one hand for 15 minutes, slapping the mixture against the side of the bowl. Ready test: it turns paler and tacky, and a handful stretches rather than crumbling.","ar":"ضع اللحمين والألية والبصل المعصور والملح والفلفل الأسود والبيكربونات (إن استخدمتها) في وعاء كبير. اعجن بيد واحدة ١٥ دقيقة مع ضرب الخليط على جدار الوعاء. علامة الجاهزية: يفتح لونه ويصبح لزجًا، وإذا رفعت حفنة منه تمددت ولم تتفتت."},"time":15,"image":{"src":"/recipes/chelow-kabab/step-02.webp","alt":"دستی در حال ورز دادن گوشت چرخ‌کرده با پیاز و ادویه در کاسهٔ بزرگ","width":1200,"height":900}},{"n":3,"title":{"fa":"استراحت در یخچال","en":"Rest in the fridge","ar":"التبريد في الثلاجة"},"text":{"fa":"روی کاسه را با درپوش یا سلفون بپوشانید و ۲ ساعت در یخچال بگذارید تا مایه سفت شود. اگر وقت دارید تا ۱۲ ساعت هم می‌شود نگه داشت (این زمان اضافی را به زمان کل اضافه کنید). در همین فاصله برنج خیس می‌خورد و اگر کباب را روی زغال می‌پزید، ۳۰ دقیقه پیش از سیخ کشیدن زغال را روشن کنید.","en":"Cover the bowl and refrigerate for 2 hours so the mixture firms up. You can leave it up to 12 hours if you have time (add the extra time to the total). Meanwhile the rice soaks; if you are using charcoal, light it 30 minutes before skewering.","ar":"غطِّ الوعاء وضعه في الثلاجة ساعتين حتى يتماسك الخليط. يمكن تركه حتى ١٢ ساعة إن توفر الوقت (أضف الوقت الإضافي إلى المجموع). في هذه الأثناء ينقع الأرز، وإن كنت ستشوي على الفحم فأشعله قبل التسييخ بثلاثين دقيقة."},"time":120,"image":{"src":"/recipes/chelow-kabab/step-03.webp","alt":"کاسهٔ مایهٔ کباب پوشیده با سلفون روی طبقهٔ یخچال","width":1200,"height":900}},{"n":4,"title":{"fa":"آبکش کردن برنج","en":"Parboil and drain the rice","ar":"سلق الأرز وتصفيته"},"text":{"fa":"۳ لیتر آب و ۱ قاشق غذاخوری نمک را در قابلمهٔ بزرگ روی حرارت زیاد بجوشانید. برنج خیس‌خورده را آبکش کنید و در آب در حال جوش بریزید و یک بار آرام هم بزنید. ۶ تا ۸ دقیقه بجوشانید. تست: دانه را بین دو انگشت فشار دهید؛ بیرونش نرم و وسطش هنوز کمی سفت است. فوراً در آبکش بریزید و با یک پیمانه آب ولرم رویش را بشویید.","en":"Bring 3 litres water and 1 tbsp salt to a rolling boil over high heat in a large pot. Drain the soaked rice, add it to the boiling water and stir once gently. Boil for 6–8 minutes. Test: press a grain between two fingers; the outside is soft but the centre is still slightly firm. Drain at once and rinse with a cup of lukewarm water.","ar":"اغلِ ٣ لترات من الماء مع ملعقة كبيرة من الملح في قدر كبير على نار عالية. صفِّ الأرز المنقوع وأضفه إلى الماء المغلي وحرّكه مرة واحدة برفق. اسلقه ٦–٨ دقائق. الاختبار: اضغط حبة بين إصبعين؛ يكون خارجها طريًا ووسطها متماسكًا قليلًا. صفِّه فورًا واشطفه بكوب من الماء الفاتر."},"time":15,"image":{"src":"/recipes/chelow-kabab/step-04.webp","alt":"برنج در حال جوشیدن در قابلمهٔ بزرگ و ریختن آن در آبکش","width":1200,"height":900}},{"n":5,"title":{"fa":"دم کردن چلو","en":"Steam the rice","ar":"تبخير الأرز"},"text":{"fa":"۳ قاشق غذاخوری روغن و ۳ قاشق غذاخوری آب را در همان قابلمه بریزید. برنج را با کفگیر به شکل هرم در قابلمه بریزید و با دستهٔ کفگیر ۴ تا ۵ سوراخ تا کف قابلمه باز کنید. ۵ دقیقه روی حرارت متوسط بگذارید تا بخار بلند شود. بعد درِ قابلمه را با دم‌کنی یا حولهٔ تمیز بپیچید و بگذارید، حرارت را خیلی کم کنید و ۴۰ دقیقه دم بکشد. ۲۰ گرم کره را ۵ دقیقه آخر روی برنج بگذارید. چلو وقتی آماده است که دانه‌ها کاملاً نرم و جدا از هم باشند و ته قابلمه ته‌دیگ طلایی بسته باشد.","en":"Add 3 tbsp oil and 3 tbsp water to the same pot. Spoon the rice in as a mound and poke 4–5 holes to the bottom with the handle of the spoon. Leave on medium heat for 5 minutes until steam rises. Wrap the lid in a clean tea towel, cover, turn the heat to very low and steam for 40 minutes. Put 20 g butter on the rice for the last 5 minutes. The rice is ready when the grains are fully tender and separate and a golden crust (tahdig) has formed on the bottom.","ar":"ضع ٣ ملاعق كبيرة من الزيت و٣ ملاعق كبيرة من الماء في القدر نفسه. اسكب الأرز على شكل هرم وافتح ٤–٥ ثقوب حتى القاع بمقبض الملعقة. اتركه على نار متوسطة ٥ دقائق حتى يتصاعد البخار، ثم لفّ الغطاء بمنشفة نظيفة وغطِّ القدر واخفض النار جدًا ودعه ينضج بالبخار ٤٠ دقيقة. ضع ٢٠ غرامًا من الزبدة على الأرز في آخر ٥ دقائق. يكون جاهزًا حين تصبح الحبات طرية منفصلة وتتكوّن قشرة ذهبية (ته‌ديگ) في القاع."},"time":45,"image":{"src":"/recipes/chelow-kabab/step-05.webp","alt":"برنج هرمی‌شکل در قابلمه با چند سوراخ و درِ پیچیده در دم‌کنی پارچه‌ای","width":1200,"height":900}},{"n":6,"title":{"fa":"سیخ کشیدن کباب","en":"Shape the kebabs on skewers","ar":"تشكيل الكباب على الأسياخ"},"text":{"fa":"این کار را هم‌زمان با دم کشیدن برنج انجام دهید. مایه را از یخچال بیرون بیاورید و به ۸ قسمت حدود ۱۰۰ گرمی تقسیم کنید. دست را با آب پیاز خیس کنید، یک قسمت را دور سیخ پهن کوبیده بگذارید و با فشار انگشت شست و اشاره آن را در طول سیخ به ضخامت حدود ۱ سانتی‌متر باز کنید. دو سر گوشت را محکم به سیخ بفشارید و با انگشت‌ها شیارهای مورب روی آن بیندازید. گوجه‌ها را جداگانه به سیخ بکشید.","en":"Do this while the rice steams. Take the mixture out of the fridge and divide it into 8 portions of about 100 g. Wet your hands with onion juice, wrap one portion around a wide koobideh skewer and press it along the skewer with thumb and forefinger to about 1 cm thick. Press both ends firmly onto the skewer and pinch diagonal ridges along the meat. Thread the tomatoes onto separate skewers.","ar":"قم بذلك أثناء تبخير الأرز. أخرج الخليط من الثلاجة وقسّمه إلى ٨ أجزاء وزن كلٍّ منها نحو ١٠٠ غرام. رطّب يديك بعصير البصل، ولفّ جزءًا حول سيخ الكوبيده العريض، واضغطه بالإبهام والسبابة على طول السيخ بسماكة نحو سنتيمتر واحد. اضغط الطرفين جيدًا على السيخ واصنع بأصابعك تموجات مائلة على اللحم. اشبك الطماطم على أسياخ منفصلة."},"time":15,"image":{"src":"/recipes/chelow-kabab/step-06.webp","alt":"دست خیس در حال پهن کردن مایهٔ کوبیده دور سیخ پهن با جای انگشت","width":1200,"height":900}},{"n":7,"title":{"fa":"کباب کردن روی زغال","en":"Grill over charcoal","ar":"الشوي على الفحم"},"text":{"fa":"این کار هم در ۱۵ دقیقهٔ آخر دم کشیدن برنج انجام می‌شود (هم‌زمان، جدا شمرده نشده). زغال باید سرخ و رویش لایهٔ نازک خاکستر نشسته باشد و شعله نداشته باشد (حرارت متوسط رو به زیاد؛ دست را در ۱۰ سانتی‌متری بالای زغال فقط ۳ تا ۴ ثانیه می‌توانید نگه دارید). سیخ‌ها را روی منقل بگذارید و ۲ دقیقهٔ اول هر ۱۰ تا ۱۵ ثانیه یک بار بچرخانید تا رویه ببندد و گوشت از سیخ نیفتد. بعد هر یک دقیقه بچرخانید؛ کل پخت ۸ تا ۱۰ دقیقه است. تست پختگی: رویه قهوه‌ای یکدست شده، آب صورتی از گوشت بیرون نمی‌آید و وسط کباب صورتی نیست (اگر دماسنج دارید، ۷۱ درجهٔ سانتی‌گراد). گوجه‌ها را کنار کباب ۸ تا ۱۰ دقیقه بچرخانید تا پوستشان سیاه‌سوخته و چروک شود. روی کباب‌ها کرهٔ آب‌شده بمالید.","en":"This also happens during the last 15 minutes of steaming the rice (concurrent, not counted separately). The coals should glow red under a thin layer of ash, with no flames (medium-high heat: you can hold your hand 10 cm above them for only 3–4 seconds). Set the skewers over the coals and for the first 2 minutes turn them every 10–15 seconds so the surface sets and the meat does not slide off. Then turn every minute; total cooking is 8–10 minutes. Doneness test: evenly browned outside, no pink juices, no pink in the centre (71 \xb0C if you have a thermometer). Grill the tomatoes alongside for 8–10 minutes, turning, until the skins blister and char. Brush the kebabs with melted butter.","ar":"يتم هذا أيضًا خلال آخر ١٥ دقيقة من تبخير الأرز (بالتزامن، لا يُحسب منفصلًا). يجب أن يكون الفحم متوهجًا أحمر تعلوه طبقة رقيقة من الرماد ودون لهب (حرارة متوسطة إلى عالية: لا تستطيع إبقاء يدك على ارتفاع ١٠ سم فوقه أكثر من ٣–٤ ثوانٍ). ضع الأسياخ على المنقل، وفي أول دقيقتين اقلبها كل ١٠–١٥ ثانية حتى يتماسك السطح ولا يسقط اللحم، ثم اقلبها كل دقيقة؛ مجموع الشوي ٨–١٠ دقائق. اختبار النضج: سطح بني متجانس، ولا تخرج عصارة وردية، ولا يبقى لون وردي في الوسط (٧١ درجة مئوية إن كان لديك ميزان حرارة). اشوِ الطماطم بجانبها ٨–١٠ دقائق مع التقليب حتى يتفحم قشرها ويتجعد. ادهن الكباب بالزبدة المذابة."},"time":12,"image":{"src":"/recipes/chelow-kabab/step-07.webp","alt":"سیخ‌های کباب کوبیده روی زغال سرخ و بی‌شعله همراه گوجه‌فرنگی","width":1200,"height":900}},{"n":8,"title":{"fa":"آماده کردن زعفران و سرو","en":"Saffron rice and serving","ar":"تحضير الزعفران والتقديم"},"text":{"fa":"حدود یک پیمانه از برنج دم‌کشیده را در کاسه بریزید و با زعفران دم‌کرده مخلوط کنید تا زرد شود. چلو را در دیس بکشید و برنج زعفرانی را رویش بپاشید. کباب‌ها را با کمک نان یا چنگال از سیخ جدا کنید و کنار چلو بچینید، گوجه‌ها را کنارشان بگذارید و سماق و ریحان را جدا سرو کنید. اگر زرده استفاده می‌کنید، آن را در گودی روی چلوی داغ بشکنید.","en":"Mix about one cup of the steamed rice with the bloomed saffron until yellow. Spoon the rice onto a platter and scatter the saffron rice over it. Slide the kebabs off the skewers with bread or a fork, lay them next to the rice with the tomatoes, and serve sumac and basil on the side. If using a yolk, drop it into a hollow in the hot rice.","ar":"اخلط نحو كوب من الأرز المطهو بالزعفران المنقوع حتى يصفرّ. اسكب الأرز في طبق التقديم وانثر عليه الأرز الزعفراني. أزل الكباب عن الأسياخ بالخبز أو الشوكة وضعه بجانب الأرز مع الطماطم، وقدّم السمّاق والريحان جانبًا. إن استخدمت الصفار فضعه في تجويف وسط الأرز الساخن."},"time":3,"image":{"src":"/recipes/chelow-kabab/step-08.webp","alt":"دیس چلو با برنج زعفرانی، کباب‌های جداشده از سیخ و گوجهٔ کبابی","width":1200,"height":900}}],"tips":{"fa":["مایه باید کاملاً سرد باشد؛ مایهٔ گرم از سیخ می‌ریزد.","نمک را می‌توان ۳۰ دقیقه پیش از سیخ کشیدن هم زد؛ هر دو روش در منابع آمده.","سیخ‌های پهن (حدود ۲ سانتی‌متر) گوشت را بهتر نگه می‌دارند."],"en":["The mixture must be fully chilled; warm meat slides off the skewer.","Salt can also be added 30 minutes before skewering; sources give both methods.","Wide skewers (about 2 cm) hold the meat better."],"ar":["يجب أن يكون الخليط باردًا تمامًا؛ اللحم الدافئ يسقط عن السيخ.","يمكن إضافة الملح قبل التسييخ بثلاثين دقيقة أيضًا؛ تذكر المصادر الطريقتين.","الأسياخ العريضة (نحو ٢ سم) تمسك اللحم أفضل."]},"cover":{"src":"/recipes/chelow-kabab/cover.webp","alt":"دیس چلوکباب با برنج زعفرانی، دو سیخ کباب کوبیده، گوجهٔ کبابی و کاسهٔ سماق","width":1600,"height":1200},"serving":{"src":"/recipes/chelow-kabab/serving.webp","alt":"سفرهٔ چهارنفره با دیس‌های چلوکباب، پیاز، ریحان، سماق و دوغ از نمای بالا","width":1200,"height":1500}},{"id":"kabab-gerashi","country":"IR","slugs":{"fa":"کباب-گراشی","en":"kabab-gerashi","ar":"كباب-كراشي"},"title":{"fa":"کباب گراشی","en":"Gerashi Kabab (Yogurt Kabab)","ar":"كباب كراشي (كباب باللبن)"},"summary":{"fa":"کباب آیینی گراش و لارستان: تکه‌های درشت گوشت که یک تا دو شبانه‌روز در ماست ترش پرچرب، پیاز قرمز و فلفل سیاه می‌خوابد و روی زغال آرام تا رنگ نارنجی‌قهوه‌ای کباب می‌شود.","en":"The ceremonial kebab of Gerash and Larestan: large chunks of meat steeped for one to two days in sour full-fat yogurt, red onion and black pepper, then grilled slowly over calm coals until orange-brown.","ar":"كباب طقسي من كراش ولارستان: قطع كبيرة من اللحم تُنقع يومًا إلى يومين في لبن حامض كامل الدسم مع البصل الأحمر والفلفل الأسود، ثم تُشوى ببطء على جمر هادئ حتى يصير لونها برتقاليًا مائلًا إلى البني."},"intro":{"fa":"در گراش، این کباب بخشی از آیین عروسی و جشن بوده است: گوشت با پارچهٔ نخی خشک می‌شد، در ماست ترش محلی و پیاز در ظرف سفالی بی‌لعاب می‌خوابید و هر چند ساعت با کفگیر چوبی هم زده می‌شد تا سفال آب ماست را بکشد. در شهرهای همسایهٔ لارستان همین کباب با نام \xabکنجه لاری\xbb یا \xabچنجه ماستی\xbb شناخته می‌شود و بر سر نام آن میان گراش و لار رقابتی دیرینه هست. اسید ماست گوشت را ترد می‌کند، پس نمک را تا هنگام کباب کردن نزنید. این دستور شیوهٔ سنتی را برای آشپزخانهٔ خانگی با یخچال تطبیق داده است.","en":"In Gerash this kebab belonged to weddings and feasts: the meat was dried with a cotton cloth, steeped with local sour yogurt and onion in an unglazed clay pot, and stirred every few hours with a wooden paddle while the clay drew off the whey. In neighbouring Larestan towns the same kebab is called \\"kenjeh lari\\" or \\"chenjeh masti\\", and Gerash and Lar have long competed over the name. The acid in the yogurt tenderises the meat, so hold the salt until grilling. This recipe adapts the traditional method to a home kitchen with a refrigerator.","ar":"كان هذا الكباب في كراش جزءًا من الأعراس والولائم: يُجفف اللحم بقماش قطني، ويُنقع في اللبن الحامض المحلي والبصل في وعاء فخاري غير مزجج، ويُقلّب كل بضع ساعات بمجداف خشبي بينما يمتص الفخار مصل اللبن. ويُعرف الكباب نفسه في مدن لارستان المجاورة باسم \xabكنجه لاري\xbb أو \xabچنجه ماستي\xbb، وبين كراش ولار تنافس قديم على الاسم. حمض اللبن يُطري اللحم، فلا تُضف الملح حتى الشوي. تكيّف هذه الوصفة الطريقة التقليدية لمطبخ منزلي فيه ثلاجة."},"seoTitle":{"fa":"کباب گراشی؛ کباب ماستی آیینی گراش و لارستان","en":"Gerashi Kabab Recipe (Persian Yogurt Kebab from Fars)","ar":"كباب كراشي: طريقة عمل كباب اللبن من فارس"},"seoDescription":{"fa":"طرز تهیه کباب گراشی برای ۴ نفر: تکه‌های درشت گوشت که ۲۴ ساعت در ماست ترش پرچرب، پیاز قرمز و فلفل سیاه می‌خوابد و روی زغال ملایم کباب می‌شود.","en":"Gerashi yogurt kabab for 4: large meat chunks marinated 24 h in sour full-fat yogurt, red onion and black pepper, then grilled slowly over gentle coals.","ar":"طريقة عمل كباب كراشي لأربعة أشخاص: قطع لحم كبيرة تُنقع ٢٤ ساعة في لبن حامض كامل الدسم مع البصل الأحمر والفلفل الأسود، ثم تُشوى ببطء على جمر هادئ."},"servings":4,"prep":30,"cook":25,"rest":1470,"total":1525,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"گوشت بی‌استخوان بره، بزغاله یا گوساله","en":"Boneless lamb, kid or veal","ar":"لحم مسحّب من الحمل أو الجدي أو العجل"},"amount":"1000","unit":"گرم","optional":false,"group":{"fa":"گوشت و مرینیت ماستی","en":"Meat and yogurt marinade","ar":"اللحم وتتبيلة اللبن"},"note":{"fa":"ران یا راسته؛ سنتی آن گوشت بزغالهٔ نر جوان است.","en":"Leg or loin; traditionally young male kid.","ar":"من الفخذ أو الظهر؛ تقليديًا لحم جدي ذكر صغير."}},{"name":{"fa":"ماست ترش پرچرب","en":"Sour full-fat yogurt","ar":"لبن زبادي حامض كامل الدسم"},"amount":"500","unit":"گرم","optional":false,"group":{"fa":"گوشت و مرینیت ماستی","en":"Meat and yogurt marinade","ar":"اللحم وتتبيلة اللبن"},"note":{"fa":"ماستی که ۱ تا ۲ روز بیرون از یخچال ترش شده یا ماست چکیدهٔ ترش؛ سنتی آن ماست شیر بز است.","en":"Yogurt soured for 1–2 days, or sour strained yogurt; traditionally goat\'s-milk yogurt.","ar":"لبن تُرك ليحمض يومًا أو يومين أو لبن مصفّى حامض؛ تقليديًا من حليب الماعز."}},{"name":{"fa":"پیاز قرمز","en":"Red onion","ar":"بصل أحمر"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"گوشت و مرینیت ماستی","en":"Meat and yogurt marinade","ar":"اللحم وتتبيلة اللبن"},"note":{"fa":"درشت (حدود ۳۰۰ گرم)، ریز خردشده.","en":"Large (about 300 g), finely chopped.","ar":"كبيرة (نحو ٣٠٠ غرام)، مفرومة ناعمًا."}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"1.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"گوشت و مرینیت ماستی","en":"Meat and yogurt marinade","ar":"اللحم وتتبيلة اللبن"},"note":{"fa":"تازه آسیاب‌شده.","en":"Freshly ground.","ar":"مطحون طازجًا."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"2","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"برای پخت و سرو","en":"For cooking and serving","ar":"للطهي والتقديم"},"note":{"fa":"هنگام کباب کردن.","en":"At grilling time.","ar":"عند الشوي."}},{"name":{"fa":"نان محلی نازک یا لواش","en":"Thin local flatbread or lavash","ar":"خبز محلي رقيق أو لواش"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"برای پخت و سرو","en":"For cooking and serving","ar":"للطهي والتقديم"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) گوشت را به تکه‌های درشت ۴ تا ۵ سانتی‌متری ببرید و رگ‌های سفت را جدا کنید.\\n۲) تکه‌ها را روی پارچهٔ نخی تمیز پهن کنید و با پارچهٔ دیگر رویشان را فشار دهید تا رطوبت سطحی کاملاً گرفته شود؛ سطح گوشت باید مات و خشک باشد.\\n۳) پیاز قرمز را ریز خرد کنید.","en":"1) Cut the meat into large 4–5 cm chunks and trim hard sinew.\\n2) Spread the pieces on a clean cotton cloth and press another cloth on top until all surface moisture is gone; the surface should look matte and dry.\\n3) Finely chop the red onion.","ar":"١) قطّع اللحم قطعًا كبيرة ٤–٥ سم وانزع الأعصاب القاسية.\\n٢) افرد القطع على قماش قطني نظيف واضغط فوقها بقماش آخر حتى تزول الرطوبة السطحية تمامًا؛ يجب أن يبدو السطح باهتًا جافًا.\\n٣) افرم البصل الأحمر ناعمًا."},"time":20,"image":{"src":"/recipes/kabab-gerashi/step-01.webp","alt":"تکه‌های درشت گوشت روی پارچهٔ نخی برای خشک کردن و پیاز رنده‌شده","width":1200,"height":900}},{"n":2,"title":{"fa":"خواباندن در ماست","en":"Steep in yogurt","ar":"النقع في اللبن"},"text":{"fa":"ماست ترش، پیاز و فلفل سیاه را در ظرف سفالی یا شیشه‌ای بزرگ مخلوط کنید. گوشت را اضافه کنید و با کفگیر چوبی هم بزنید تا همهٔ تکه‌ها زیر ماست بروند. نمک نزنید. درِ ظرف را بگذارید.","en":"Mix the sour yogurt, onion and black pepper in a large clay or glass pot. Add the meat and stir with a wooden spoon until every piece is buried in yogurt. No salt. Cover.","ar":"اخلط اللبن الحامض والبصل والفلفل الأسود في وعاء فخاري أو زجاجي كبير. أضف اللحم وقلّب بملعقة خشبية حتى تغمر اللبن كل القطع. بلا ملح. غطِّ الوعاء."},"time":10,"image":{"src":"/recipes/kabab-gerashi/step-02.webp","alt":"تکه‌های گوشت غرق در ماست در ظرف سفالی با قاشق چوبی","width":1200,"height":900}},{"n":3,"title":{"fa":"استراحت ۲۴ ساعته در یخچال","en":"Rest 24 hours in the fridge","ar":"الراحة ٢٤ ساعة في الثلاجة"},"text":{"fa":"ظرف را ۲۴ ساعت در یخچال بگذارید و هر ۴ تا ۶ ساعت (در ساعات بیداری) با کفگیر چوبی هم بزنید تا ماست به همه جا برسد. شیوهٔ سنتی ۴۸ ساعت است؛ اگر می‌خواهید طولانی‌تر بخوابانید، حتماً در یخچال نگه دارید و از ۴۸ ساعت بیشتر نکنید.","en":"Refrigerate for 24 hours, stirring with a wooden spoon every 4–6 hours (while you are awake) so the yogurt reaches everywhere. The traditional time is 48 hours; if you want to go longer, keep it refrigerated and do not exceed 48 hours.","ar":"ضع الوعاء في الثلاجة ٢٤ ساعة وقلّبه بملعقة خشبية كل ٤–٦ ساعات (في ساعات اليقظة) ليصل اللبن إلى كل مكان. المدة التقليدية ٤٨ ساعة؛ إن أردت الإطالة فأبقه في الثلاجة ولا تتجاوز ٤٨ ساعة."},"time":1440,"image":{"src":"/recipes/kabab-gerashi/step-03.webp","alt":"ظرف سفالی پوشیدهٔ گوشت و ماست در یخچال","width":1200,"height":900}},{"n":4,"title":{"fa":"آبکش کردن و روشن کردن زغال","en":"Drain and light the coals","ar":"التصفية وإشعال الفحم"},"text":{"fa":"گوشت و ماست را در کیسهٔ پارچه‌ای یا آبکشِ پوشیده با پارچهٔ نخی بریزید و ۳۰ دقیقه بگذارید آب ماست بچکد؛ گوشت باید فقط با لایهٔ نازکی از ماست غلیظ پوشیده بماند. هم‌زمان زغال را روشن کنید تا کاملاً سرخ شود، شعله‌اش بخوابد و رویش خاکستر بنشیند (این زمان با آبکش شدن هم‌پوشانی دارد و جدا شمرده نشده است).","en":"Tip the meat and yogurt into a cloth bag or a colander lined with cotton cloth and let the whey drip for 30 minutes; the meat should keep only a thin coat of thick yogurt. Meanwhile light the charcoal and let it burn down until red, flameless and ashed over (this overlaps the draining and is not counted separately).","ar":"اسكب اللحم واللبن في كيس قماشي أو مصفاة مبطنة بقماش قطني واترك المصل يقطر ٣٠ دقيقة؛ يجب أن يبقى على اللحم غطاء رقيق من اللبن الكثيف. في الوقت نفسه أشعل الفحم حتى يحمر ويخمد لهبه ويعلوه الرماد (هذا يتزامن مع التصفية ولم يُحسب منفصلًا)."},"time":30,"image":{"src":"/recipes/kabab-gerashi/step-04.webp","alt":"چکیدن آب ماست از گوشت در آبکش پوشیده با پارچه","width":1200,"height":900}},{"n":5,"title":{"fa":"کباب کردن آرام","en":"Grill slowly","ar":"الشوي ببطء"},"text":{"fa":"تکه‌ها را به سیخ بکشید و سیخ‌ها را بالای زغال‌های آرام و خاکسترنشسته، با حرارت ملایم بگذارید (دست را در ۱۰ سانتی‌متری ۷ تا ۸ ثانیه می‌توانید نگه دارید). هر ۲ تا ۳ دقیقه بچرخانید و در دور دوم نمک را روی تکه‌ها بپاشید. ۱۵ تا ۲۰ دقیقه کباب کنید تا ماستِ روی گوشت سفت و رنگش نارنجی مایل به قهوه‌ای شود. اگر شعله زد، سیخ را کنار ببرید. تست پختگی: یک تکهٔ درشت را ببرید؛ وسط آن آبدار ولی بدون رگهٔ قرمز است.","en":"Thread the chunks and set the skewers over calm, ashed coals on low heat (you can hold your hand 10 cm above for 7–8 seconds). Turn every 2–3 minutes and sprinkle the salt over on the second turn. Grill for 15–20 minutes until the yogurt coating sets and turns orange-brown. If flames flare, move the skewer aside. Doneness test: cut a large piece; the centre is juicy with no red streaks.","ar":"اشبك القطع على الأسياخ وضعها فوق جمر هادئ مغطى بالرماد على حرارة منخفضة (تستطيع إبقاء يدك على ارتفاع ١٠ سم ٧–٨ ثوانٍ). اقلب كل ٢–٣ دقائق ورشّ الملح في الدورة الثانية. اشوِ ١٥–٢٠ دقيقة حتى يتماسك غطاء اللبن ويصير برتقاليًا مائلًا إلى البني. إن اشتعل لهب فأبعد السيخ. اختبار النضج: اقطع قطعة كبيرة؛ يكون وسطها مليئًا بالعصارة بلا خطوط حمراء."},"time":20,"image":{"src":"/recipes/kabab-gerashi/step-05.webp","alt":"سیخ‌های تکه‌های درشت گوشت روی زغال آرام و خاکسترنشسته","width":1200,"height":900}},{"n":6,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"تکه‌ها را از سیخ در نان نازک بکشید و در سینی بچینید و فوراً سرو کنید.","en":"Slide the chunks off the skewers into thin bread, arrange on a tray and serve at once.","ar":"أزل القطع عن الأسياخ داخل الخبز الرقيق ورتّبها في صينية وقدّمها فورًا."},"time":5,"image":{"src":"/recipes/kabab-gerashi/step-06.webp","alt":"جدا کردن تکه‌های کباب از سیخ در نان نازک روی سینی","width":1200,"height":900}}],"tips":{"fa":["ماست هر چه ترش‌تر، گوشت تردتر.","خشک کردن گوشت پیش از مرینیت را جا نیندازید.","ظرف سفالی بی‌لعاب آب ماست را می‌کشد؛ ظرف شیشه‌ای هم کار می‌کند."],"en":["The sourer the yogurt, the more tender the meat.","Don\'t skip drying the meat before marinating.","An unglazed clay pot draws off whey; glass also works."],"ar":["كلما كان اللبن أحمض كان اللحم أطرى.","لا تُهمل تجفيف اللحم قبل التتبيل.","الفخار غير المزجج يمتص المصل؛ والزجاج يفي بالغرض."]},"cover":{"src":"/recipes/kabab-gerashi/cover.webp","alt":"تکه‌های درشت کباب گراشی با رویهٔ ماست برشته روی سیخ‌های آهنی بالای زغال","width":1600,"height":1200},"serving":{"src":"/recipes/kabab-gerashi/serving.webp","alt":"تکه‌های کباب گراشی در نان نازک روی سینی فلزی گرد با ریحان و پیاز","width":1200,"height":1500}},{"id":"kahoo-sekanjabin","country":"IR","slugs":{"fa":"کاهو-سکنجبین","en":"kahoo-sekanjabin","ar":"خس-سكنجبين"},"title":{"fa":"کاهو سکنجبین","en":"Lettuce with Sekanjabin","ar":"خس بالسكنجبين"},"summary":{"fa":"برگ‌های ترد کاهوی رسمی که در شربت غلیظ سکنجبین (سرکهٔ انگور، شکر و نعناع) زده و خورده می‌شود؛ میان‌وعدهٔ خنک تابستانی.","en":"Crisp romaine leaves dipped into thick sekanjabin syrup made from grape vinegar, sugar and mint; a cooling summer snack.","ar":"أوراق خس روماني مقرمشة تُغمس في السكنجبين الكثيف المصنوع من خل العنب والسكر والنعناع؛ وجبة خفيفة منعشة في الصيف."},"intro":{"fa":"\xabسکنجبین\xbb همان \xabسرکه‌انگبین\xbb است: در اصل سرکه و عسل که با هم جوشانده می‌شد و بعدها با شکر هم درست شد. این شربت غلیظ با نعناع معطر می‌شود و دو کاربرد دارد: رقیق‌شده با آب یخ و خیار به‌عنوان نوشیدنی، و غلیظ برای زدن کاهو. اینجا شربت را برای کاهو غلیظ‌تر درست می‌کنیم؛ نعناع را بعد از خاموش کردن شعله دم می‌دهیم تا عطرش تلخ نشود.","en":"\\"Sekanjabin\\" comes from \\"serkeh-angabin\\", vinegar-and-honey: originally vinegar and honey boiled together, later also made with sugar. The thick syrup is scented with mint and has two uses: diluted with iced water and cucumber as a drink, or thick as a dip for lettuce. Here it is made thicker for lettuce, and the mint is steeped after the heat is off so its aroma doesn\'t turn bitter.","ar":"\xabالسكنجبين\xbb أصله \xabسركه أنكبين\xbb أي الخل والعسل: كان يُغلى الخل مع العسل ثم صار يُصنع بالسكر أيضًا. يُعطَّر هذا السكنجبين الكثيف بالنعناع وله استعمالان: مخففًا بالماء المثلج والخيار كمشروب، وكثيفًا لغمس الخس. نحضّره هنا أكثف للخس، ونُنقع النعناع بعد إطفاء النار كي لا تصير رائحته مُرّة."},"seoTitle":{"fa":"کاهو سکنجبین؛ طرز تهیه سکنجبین غلیظ با نعناع","en":"Kahoo Sekanjabin Recipe (Lettuce with Mint Vinegar Syrup)","ar":"خس بالسكنجبين: طريقة عمل صلصة الخل والنعناع الإيرانية"},"seoDescription":{"fa":"طرز تهیه کاهو سکنجبین برای ۴ نفر: شربت غلیظ سکنجبین از سرکهٔ انگور، شکر و نعناع تازه با برگ ترد کاهوی رسمی؛ میان‌وعدهٔ خنک تابستانی و آسان.","en":"Easy Persian summer snack for 4: crisp romaine leaves dipped in thick sekanjabin syrup of grape vinegar, sugar and fresh mint. About 110 min incl. cooling.","ar":"طريقة عمل الخس بالسكنجبين لأربعة أشخاص: أوراق خس روماني مقرمشة تُغمس في سكنجبين كثيف من خل العنب والسكر والنعناع الطازج؛ وجبة صيفية خفيفة وسهلة."},"servings":4,"prep":10,"cook":25,"rest":75,"total":110,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"شکر","en":"Sugar","ar":"سكر"},"amount":"200","unit":"گرم","optional":false,"group":{"fa":"شربت سکنجبین","en":"Sekanjabin syrup","ar":"السكنجبين"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"175","unit":"میلی‌لیتر","optional":false,"group":{"fa":"شربت سکنجبین","en":"Sekanjabin syrup","ar":"السكنجبين"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"سرکهٔ انگور","en":"Grape vinegar","ar":"خل العنب"},"amount":"80","unit":"میلی‌لیتر","optional":false,"group":{"fa":"شربت سکنجبین","en":"Sekanjabin syrup","ar":"السكنجبين"},"note":{"fa":"یا سرکهٔ سیب؛ سرکهٔ شراب نه.","en":"Or apple vinegar; not wine vinegar.","ar":"أو خل التفاح؛ لا خل النبيذ."}},{"name":{"fa":"نعناع تازه","en":"Fresh mint","ar":"نعناع طازج"},"amount":"15","unit":"گرم","optional":false,"group":{"fa":"شربت سکنجبین","en":"Sekanjabin syrup","ar":"السكنجبين"},"note":{"fa":"یک دستهٔ کوچک با ساقه.","en":"A small bunch, with stems.","ar":"باقة صغيرة بسيقانها."}},{"name":{"fa":"کاهوی رسمی (رومی)","en":"Romaine lettuce","ar":"خس روماني"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"کاهو","en":"Lettuce","ar":"الخس"},"note":{"fa":"حدود ۷۰۰ گرم در مجموع.","en":"About 700 g in total.","ar":"نحو ٧٠٠ غرام إجمالًا."}},{"name":{"fa":"یخ","en":"Ice cubes","ar":"مكعبات ثلج"},"amount":"10","unit":"عدد","optional":false,"group":{"fa":"کاهو","en":"Lettuce","ar":"الخس"},"note":{"fa":"برای آب یخ.","en":"For the ice bath.","ar":"لحمّام الماء المثلج."}},{"name":{"fa":"آب سرد برای آب یخ","en":"Cold water for the ice bath","ar":"ماء بارد لحمّام الثلج"},"amount":"2","unit":"لیتر","optional":false,"group":{"fa":"کاهو","en":"Lettuce","ar":"الخس"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) نعناع را بشویید و تکان دهید تا آبش برود.\\n۲) برگ‌های کاهو را از هم جدا کنید، برگ‌های زرد و پلاسیده را دور بریزید و زیر آب روان بشویید؛ اگر لازم است طبق دستور روی بستهٔ ضدعفونی‌کنندهٔ سبزی ضدعفونی و دوباره آبکشی کنید.","en":"1) Rinse the mint and shake off the water.\\n2) Separate the lettuce leaves, discard yellow or wilted ones and wash under running water; if needed, sanitise following the produce-wash label and rinse again.","ar":"١) اغسل النعناع وانفضه ليذهب الماء.\\n٢) افصل أوراق الخس وتخلّص من الصفراء والذابلة واغسلها تحت الماء الجاري؛ وإن لزم عقّمها وفق تعليمات معقّم الخضار ثم اشطفها مجددًا."},"time":10,"image":{"src":"/recipes/kahoo-sekanjabin/step-01.webp","alt":"شستن برگ‌های کاهو زیر آب روان کنار دستهٔ نعناع","width":1200,"height":900}},{"n":2,"title":{"fa":"جوشاندن شربت","en":"Boil the syrup","ar":"غلي السكنجبين"},"text":{"fa":"شکر و آب را در قابلمهٔ کوچک (ترجیحاً استیل یا لعابی، نه آلومینیومی) روی حرارت متوسط هم بزنید تا شکر حل شود و به جوش بیاید (حدود ۵ دقیقه). سرکه را اضافه کنید، حرارت را ملایم کنید و بدون هم زدن ۱۵ تا ۲۰ دقیقه بجوشانید و کف را بگیرید. نشانهٔ آماده بودن: شربت پشت قاشق را می‌پوشاند و یک قطره روی بشقاب سرد پهن نمی‌شود؛ غلظتش هنوز از عسل رقیق‌تر است، چون با سرد شدن غلیظ‌تر می‌شود.","en":"Stir the sugar and water in a small pot (ideally stainless steel or enamel, not aluminium) over medium heat until dissolved and boiling (about 5 minutes). Add the vinegar, lower the heat and simmer without stirring for 15–20 minutes, skimming the foam. Ready when the syrup coats the back of a spoon and a drop on a cold plate doesn\'t spread; it should still be thinner than honey, as it thickens on cooling.","ar":"حرّك السكر والماء في قدر صغير (يُفضّل من الستانلس أو المطلي بالمينا لا الألومنيوم) على نار متوسطة حتى يذوب ويغلي (نحو ٥ دقائق). أضف الخل وخفّف النار واتركه يغلي برفق دون تقليب ١٥–٢٠ دقيقة مع إزالة الرغوة. يكون جاهزًا حين يغطي ظهر الملعقة ولا تنتشر قطرة منه على صحن بارد؛ ويبقى أرق من العسل لأنه يتكاثف عند البرودة."},"time":25,"image":{"src":"/recipes/kahoo-sekanjabin/step-02.webp","alt":"شربت شکر و سرکه در حال جوشیدن در قابلمهٔ کوچک استیل","width":1200,"height":900}},{"n":3,"title":{"fa":"دم کردن نعناع","en":"Steep the mint","ar":"نقع النعناع"},"text":{"fa":"شعله را خاموش کنید، نعناع را در شربت داغ فرو کنید، درِ قابلمه را بگذارید و ۱۵ دقیقه صبر کنید. بعد نعناع را بیرون بیاورید و فشار دهید تا شربتش برگردد.","en":"Turn off the heat, push the mint into the hot syrup, cover and wait 15 minutes. Then lift out the mint and squeeze it back into the pot.","ar":"أطفئ النار واغمس النعناع في السكنجبين الساخن وغطِّ القدر وانتظر ١٥ دقيقة، ثم أخرج النعناع واعصره فوق القدر."},"time":15,"image":{"src":"/recipes/kahoo-sekanjabin/step-03.webp","alt":"ساقه‌های نعناع فرورفته در شربت داغ در قابلمه","width":1200,"height":900}},{"n":4,"title":{"fa":"سرد کردن و ترد کردن کاهو","en":"Cool the syrup and crisp the lettuce","ar":"تبريد السكنجبين وتقريش الخس"},"text":{"fa":"شربت را در شیشهٔ تمیز بریزید و ۶۰ دقیقه بگذارید تا به دمای اتاق برسد، سپس در یخچال خنک کنید. در ۱۵ دقیقهٔ آخر، یخ و آب سرد را در کاسهٔ بزرگ بریزید و برگ‌های کاهو را در آن بخیسانید تا کاملاً ترد شوند؛ بعد آبکش کنید و با دستمال تمیز خشک کنید.","en":"Pour the syrup into a clean jar and leave 60 minutes to reach room temperature, then chill. In the last 15 minutes, fill a large bowl with ice and cold water and soak the lettuce leaves until fully crisp; then drain and pat dry with a clean towel.","ar":"اسكب السكنجبين في برطمان نظيف واتركه ٦٠ دقيقة ليبلغ حرارة الغرفة ثم برّده. في آخر ١٥ دقيقة املأ وعاءً كبيرًا بالثلج والماء البارد وانقع فيه أوراق الخس حتى تتقرمش تمامًا، ثم صفّها وجففها بمنشفة نظيفة."},"time":60,"image":{"src":"/recipes/kahoo-sekanjabin/step-04.webp","alt":"شیشهٔ شربت سکنجبین و برگ‌های کاهو در کاسهٔ آب و یخ","width":1200,"height":900}},{"n":5,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"برگ‌های ترد کاهو را در دیس بچینید و شربت را در کاسه‌های کوچک کنارش بگذارید تا برگ‌ها را در شربت بزنید.","en":"Arrange the crisp leaves on a platter with the syrup in small bowls for dipping.","ar":"رتّب أوراق الخس المقرمشة في طبق مع السكنجبين في أوعية صغيرة للغمس."},"time":0,"image":{"src":"/recipes/kahoo-sekanjabin/step-05.webp","alt":"برگ‌های کاهو در دیس با کاسه‌های کوچک شربت کنارش","width":1200,"height":900}}],"tips":{"fa":["کاهو را تا لحظهٔ سرو در آب یخ نگه دارید.","برای نوشیدنی: ۲ قاشق غذاخوری شربت در ۲۰۰ میلی‌لیتر آب یخ با خیار رنده‌شده."],"en":["Keep the lettuce in ice water until serving.","As a drink: 2 tbsp syrup in 200 ml iced water with grated cucumber."],"ar":["أبقِ الخس في الماء المثلج حتى التقديم.","كمشروب: ملعقتان كبيرتان من السكنجبين في ٢٠٠ مل ماء مثلج مع خيار مبشور."]},"cover":{"src":"/recipes/kahoo-sekanjabin/cover.webp","alt":"دیس برگ‌های کاهوی سبز کنار کاسهٔ شیشه‌ای شربت سکنجبین و نعناع","width":1600,"height":1200},"serving":{"src":"/recipes/kahoo-sekanjabin/serving.webp","alt":"دستی در حال زدن برگ کاهو در کاسهٔ کوچک شربت سکنجبین","width":1200,"height":1500}},{"id":"khoresh-mahi","country":"IR","slugs":{"fa":"خورش-ماهی","en":"khoresh-mahi","ar":"مرق-سمك-جنوبي"},"title":{"fa":"خورش ماهی جنوبی","en":"Southern Fish Stew (Khoresh Mahi)","ar":"مرق السمك الجنوبي (خورش ماهي)"},"summary":{"fa":"فیلهٔ سرخ‌شدهٔ ماهی سفت‌گوشت جنوبی در سس غلیظ پیاز، گوجه و زردچوبه که با رب خرما ملسِ ترش‌وشیرین می‌شود؛ با چلو سرو می‌شود.","en":"Pan-fried fillets of firm southern fish simmered in a thick onion, tomato and turmeric sauce, balanced sweet-sour with date syrup; served with chelow rice.","ar":"شرائح سمك جنوبي متماسك اللحم مقلية ثم مطهوة في صلصة كثيفة من البصل والطماطم والكركم، يوازنها دبس التمر بين الحلو والحامض؛ تُقدَّم مع الأرز."},"intro":{"fa":"خورش ماهی غذای خانه‌های بندرهای جنوب ایران است و با قلیه ماهی خویشاوندی دارد، ولی سبزی و تمر هندی غلیظ قلیه را ندارد و سسش بر پایهٔ پیاز سرخ‌شده، گوجه و رب خرماست. کلید کار انتخاب ماهی است: ماهی‌های گوشت‌سفت خلیج فارس مثل هامور، شیر یا سنگسر در خورش از هم نمی‌پاشند، در حالی که ماهی‌های نرم‌گوشت له می‌شوند. خورش را غلیظ و تقریباً بی‌آب سرو کنید.","en":"Khoresh mahi is home cooking from Iran\'s southern ports and a relative of qalieh mahi, but without qalieh\'s herbs and heavy tamarind: its sauce is built on fried onion, tomato and date syrup. The key is the fish: firm Persian Gulf species such as grouper, kingfish or grunt hold together in a stew, while soft-fleshed fish fall apart. Serve it thick, with very little liquid.","ar":"خورش ماهي من طبخ البيوت في موانئ جنوب إيران، وهو قريب من قليه ماهي لكن دون أعشابها وتمرهنديها الكثيف؛ إذ تقوم صلصته على البصل المقلي والطماطم ودبس التمر. السر في اختيار السمك: أنواع الخليج الفارسي المتماسكة مثل الهامور والكنعد والسنكسر لا تتفتت في المرق، أما السمك الطري فيتهرّس. يُقدَّم كثيفًا قليل المرق."},"seoTitle":{"fa":"خورش ماهی جنوبی با رب خرما؛ طرز تهیه آسان","en":"Khoresh Mahi Recipe (Persian Southern Fish Stew)","ar":"مرق السمك الجنوبي الإيراني: طريقة عمل خورش ماهي"},"seoDescription":{"fa":"طرز تهیه خورش ماهی جنوبی برای ۴ نفر: فیلهٔ ماهی گوشت‌سفت سرخ‌شده در سس پیاز، گوجه و زردچوبه با رب خرما؛ آسان، حدود ۹۰ دقیقه، با چلو.","en":"Easy southern Iranian fish stew for 4: pan-fried firm fish fillets in a thick onion, tomato and turmeric sauce with date syrup. About 90 min, with rice.","ar":"طريقة عمل مرق السمك الجنوبي لأربعة أشخاص: شرائح سمك متماسك مقلية في صلصة البصل والطماطم والكركم مع دبس التمر؛ سهل، نحو ٩٠ دقيقة، ويُقدَّم مع الأرز."},"servings":4,"prep":15,"cook":65,"rest":10,"total":90,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"فیلهٔ ماهی جنوبی گوشت‌سفت","en":"Firm southern fish fillet","ar":"شرائح سمك جنوبي متماسك"},"amount":"800","unit":"گرم","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"هامور، شیر یا سنگسر؛ تکه‌های ۵ تا ۶ سانتی.","en":"Grouper, kingfish or grunt; 5–6 cm pieces.","ar":"هامور أو كنعد أو سنكسر؛ قطع ٥–٦ سم."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"برای ماهی.","en":"For the fish.","ar":"للسمك."}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"برای ماهی.","en":"For the fish.","ar":"للسمك."}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"برای ماهی.","en":"For the fish.","ar":"للسمك."}},{"name":{"fa":"ادویهٔ ماهی","en":"Fish spice mix","ar":"بهارات السمك"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"6","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"۳ قاشق برای ماهی، ۳ قاشق برای سس.","en":"3 tbsp for the fish, 3 for the sauce.","ar":"٣ ملاعق للسمك و٣ للصلصة."}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"متوسط (حدود ۳۰۰ گرم)، نگینی ریز.","en":"Medium (about 300 g), finely diced.","ar":"متوسطة (نحو ٣٠٠ غرام)، مقطعة مكعبات صغيرة."}},{"name":{"fa":"سیر","en":"Garlic","ar":"ثوم"},"amount":"2","unit":"حبه","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"رنده‌شده.","en":"Grated.","ar":"مبشور."}},{"name":{"fa":"زردچوبه برای سس","en":"Turmeric for the sauce","ar":"كركم للصلصة"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"رب گوجه‌فرنگی","en":"Tomato paste","ar":"معجون الطماطم"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"گوجه‌فرنگی","en":"Tomato","ar":"طماطم"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"متوسط (حدود ۳۰۰ گرم)، رنده‌شده.","en":"Medium (about 300 g), grated.","ar":"متوسطة (نحو ٣٠٠ غرام)، مبشورة."}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"250","unit":"میلی‌لیتر","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"رب خرما (شیرهٔ خرما)","en":"Date syrup","ar":"دبس التمر"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای سس","en":"Salt for the sauce","ar":"ملح للصلصة"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آبلیموی تازه","en":"Fresh lemon juice","ar":"عصير ليمون طازج"},"amount":"1","unit":"قاشق غذاخوری","optional":true,"group":{"fa":"خورش","en":"Stew","ar":"المرق"},"note":{"fa":"برای پایان کار، اختیاری.","en":"To finish, optional.","ar":"للنهاية، اختياري."}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) ماهی را بشویید، اگر پوست یا تیغ دارد جدا کنید و به تکه‌های ۵ تا ۶ سانتی ببرید؛ با دستمال کاغذی کاملاً خشک کنید.\\n۲) پیاز را نگینی ریز خرد کنید، سیر و گوجه‌فرنگی را رنده کنید.","en":"1) Rinse the fish, remove any skin or bones and cut into 5–6 cm pieces; pat completely dry with paper towels.\\n2) Finely dice the onion; grate the garlic and tomatoes.","ar":"١) اغسل السمك وأزل الجلد والشوك إن وُجد، وقطّعه قطعًا ٥–٦ سم وجففه تمامًا بالمناديل الورقية.\\n٢) قطّع البصل مكعبات صغيرة، وابشر الثوم والطماطم."},"time":15,"image":{"src":"/recipes/khoresh-mahi/step-01.webp","alt":"تکه‌های ماهی روی دستمال کاغذی با پیاز خردشده و گوجه و سیر رنده‌شده","width":1200,"height":900}},{"n":2,"title":{"fa":"مزه‌دار کردن ماهی","en":"Season the fish","ar":"تتبيل السمك"},"text":{"fa":"نمک، فلفل سیاه، \xbd قاشق چای‌خوری زردچوبه و ادویهٔ ماهی را روی هر دو طرف تکه‌ها بپاشید و ۱۰ دقیقه بگذارید بماند.","en":"Sprinkle the salt, black pepper, \xbd tsp turmeric and fish spice over both sides of the pieces and leave for 10 minutes.","ar":"رشّ الملح والفلفل الأسود ونصف ملعقة صغيرة من الكركم وبهارات السمك على جانبي القطع واتركها ١٠ دقائق."},"time":10,"image":{"src":"/recipes/khoresh-mahi/step-02.webp","alt":"تکه‌های ماهی آغشته به نمک، فلفل، زردچوبه و ادویه","width":1200,"height":900}},{"n":3,"title":{"fa":"سرخ کردن ماهی","en":"Fry the fish","ar":"قلي السمك"},"text":{"fa":"۳ قاشق غذاخوری روغن را در تابهٔ بزرگ روی حرارت متوسط تا زیاد داغ کنید (یک تکهٔ کوچک ماهی فوراً جلز کند). تکه‌ها را با فاصله بچینید و هر طرف ۳ تا ۴ دقیقه سرخ کنید تا رویه طلایی شود؛ وسط لازم نیست کامل بپزد. تا رویه نبسته، ماهی را تکان ندهید. روی بشقاب بگذارید.","en":"Heat 3 tbsp oil in a large frying pan over medium-high heat (a small piece of fish should sizzle at once). Lay the pieces apart and fry 3–4 minutes per side until golden; the centre need not be cooked through. Do not move them until the crust sets. Set aside on a plate.","ar":"سخّن ٣ ملاعق كبيرة من الزيت في مقلاة كبيرة على نار متوسطة إلى عالية (يجب أن تئز قطعة سمك صغيرة فورًا). رصّ القطع متباعدة واقلِ كل جانب ٣–٤ دقائق حتى يذهبّ؛ لا يلزم أن ينضج الوسط. لا تحركها قبل أن تتماسك القشرة. ضعها جانبًا في طبق."},"time":8,"image":{"src":"/recipes/khoresh-mahi/step-03.webp","alt":"تکه‌های ماهی در حال سرخ شدن تا طلایی در تابهٔ بزرگ","width":1200,"height":900}},{"n":4,"title":{"fa":"تفت پیاز و ادویه","en":"Fry the onion and spices","ar":"تشويح البصل والبهارات"},"text":{"fa":"۳ قاشق غذاخوری روغن باقی‌مانده را در قابلمهٔ پهن بریزید و پیاز را روی حرارت متوسط ۱۰ تا ۱۲ دقیقه تفت دهید تا طلایی شود. سیر را اضافه کنید و ۱ دقیقه هم بزنید تا بویش بلند شود. ۱ قاشق چای‌خوری زردچوبه و رب گوجه را اضافه کنید و ۲ دقیقه تفت دهید تا رنگ رب از قرمز روشن به آجری برسد.","en":"Put the remaining 3 tbsp oil in a wide pot and fry the onion over medium heat for 10–12 minutes until golden. Add the garlic and stir for 1 minute until fragrant. Add 1 tsp turmeric and the tomato paste and fry 2 minutes until the paste turns from bright red to brick red.","ar":"ضع الملاعق الثلاث المتبقية من الزيت في قدر عريض وشوّح البصل على نار متوسطة ١٠–١٢ دقيقة حتى يذهبّ. أضف الثوم وقلّب دقيقة حتى تفوح رائحته. أضف ملعقة صغيرة من الكركم ومعجون الطماطم وشوّح دقيقتين حتى يتحول لونه من الأحمر الفاتح إلى الطوبي."},"time":15,"image":{"src":"/recipes/khoresh-mahi/step-04.webp","alt":"پیاز طلایی با سیر، زردچوبه و رب گوجه در قابلمهٔ پهن","width":1200,"height":900}},{"n":5,"title":{"fa":"پخت سس","en":"Cook the sauce","ar":"طهي الصلصة"},"text":{"fa":"گوجهٔ رنده‌شده را اضافه کنید و ۵ تا ۷ دقیقه هم بزنید تا آبش کم شود. آب و \xbd قاشق چای‌خوری نمک را بریزید، بگذارید بجوشد، حرارت را ملایم کنید و ۱۵ دقیقه با درِ نیمه‌باز بپزید تا سس کمی غلیظ شود.","en":"Add the grated tomatoes and stir 5–7 minutes until their liquid reduces. Add the water and \xbd tsp salt, bring to a boil, then lower the heat and simmer 15 minutes, lid ajar, until slightly thickened.","ar":"أضف الطماطم المبشورة وقلّب ٥–٧ دقائق حتى يقل ماؤها. أضف الماء ونصف ملعقة صغيرة من الملح، واتركه يغلي، ثم خفّف النار واطهُ ١٥ دقيقة والغطاء موارب حتى تتكاثف الصلصة قليلًا."},"time":22,"image":{"src":"/recipes/khoresh-mahi/step-05.webp","alt":"سس قرمز گوجه در حال جوشیدن آرام در قابلمه با درِ نیمه‌باز","width":1200,"height":900}},{"n":6,"title":{"fa":"جا افتادن خورش","en":"Finish the stew","ar":"إنضاج المرق"},"text":{"fa":"رب خرما را در سس هم بزنید و بچشید؛ باید ملس باشد. تکه‌های ماهی را کنار هم در سس بچینید، کمی سس رویشان بریزید و دیگر با قاشق هم نزنید؛ فقط قابلمه را آرام تکان دهید. درِ قابلمه را بگذارید و ۲۰ دقیقه روی حرارت ملایم بپزید تا ماهی کاملاً سفید و با فشار چنگال به‌راحتی ورقه‌ورقه شود و روغن روی خورش بیاید. اگر دوست دارید آبلیمو را اضافه کنید.","en":"Stir the date syrup into the sauce and taste; it should be gently sweet-sour. Nestle the fish pieces in the sauce, spoon a little over them, and from now on do not stir; just shake the pot gently. Cover and cook on low for 20 minutes until the fish is opaque white, flakes easily with a fork and oil rises to the surface. Add the lemon juice if you like.","ar":"اخلط دبس التمر في الصلصة وتذوّقها؛ يجب أن تكون حلوة حامضة برفق. رصّ قطع السمك في الصلصة واسكب عليها قليلًا منها، ولا تقلّب بعد الآن بالملعقة بل حرّك القدر برفق. غطِّ واطهُ على نار هادئة ٢٠ دقيقة حتى يبيضّ السمك تمامًا ويتفتت بسهولة بالشوكة ويطفو الزيت على السطح. أضف عصير الليمون إن شئت."},"time":20,"image":{"src":"/recipes/khoresh-mahi/step-06.webp","alt":"تکه‌های ماهی سرخ‌شده کنار هم در سس غلیظ قابلمه","width":1200,"height":900}}],"tips":{"fa":["ماهی را پیش از سرخ کردن کاملاً خشک کنید.","بعد از افزودن ماهی هم نزنید.","رب خرما نداشتید: ۱ قاشق غذاخوری تمر هندی را در ۵۰ میلی‌لیتر آب جوش حل و صاف کنید."],"en":["Dry the fish thoroughly before frying.","Don\'t stir after the fish goes in.","No date syrup: dissolve 1 tbsp tamarind in 50 ml boiling water and strain."],"ar":["جفف السمك جيدًا قبل القلي.","لا تقلّب بعد إضافة السمك.","إن لم يتوفر دبس التمر: أذب ملعقة كبيرة من التمر هندي في ٥٠ مل ماء مغلي وصفّه."]},"cover":{"src":"/recipes/khoresh-mahi/cover.webp","alt":"خورش ماهی جنوبی با تکه‌های ماهی سرخ‌شده در سس غلیظ پیاز و گوجه در ظرف سفالی","width":1600,"height":1200},"serving":{"src":"/recipes/khoresh-mahi/serving.webp","alt":"بشقاب برنج سفید با خورش ماهی، ترشی انبه و قاچ لیمو","width":1200,"height":1500}},{"id":"lule-kabab","country":"IR","slugs":{"fa":"لوله-کباب","en":"lule-kabab","ar":"لوله-كباب"},"title":{"fa":"لوله‌کباب","en":"Lule Kabab","ar":"لوله كباب"},"summary":{"fa":"کباب چرخ‌کردهٔ گوسفندی که به شکل لوله‌های کوتاه و ضخیم دور سیخ پهن شکل می‌گیرد، روی زغال پخته و با لواش، پیاز سماقی و جعفری سرو می‌شود.","en":"Minced lamb kebab shaped into short, thick rolls on wide skewers, grilled over charcoal and served on lavash with sumac onions and parsley.","ar":"كباب من لحم الضأن المفروم يُشكَّل لفائف قصيرة سميكة على أسياخ عريضة، ويُشوى على الفحم ويُقدَّم على خبز اللواش مع البصل بالسمّاق والبقدونس."},"intro":{"fa":"لوله‌کباب خویشاوند کوبیده است: همان گوشت چرخ‌کردهٔ چرب و پیاز آب‌گرفته، ولی به‌جای پهن شدن در طول سیخ، به شکل لوله‌ای کوتاه و چاق درمی‌آید و مغزش آبدارتر می‌ماند. در منابع ایرانی دو شیوه دیده می‌شود: سیخی روی زغال، و \xabلول کباب تهرانی\xbb که در تابه با کره و گوجه پخته می‌شود. این دستور شیوهٔ زغالی را اصل گرفته و روش تابه و فر را در جایگزین‌ها آورده است.","en":"Lule kabab is a cousin of koobideh: the same fatty minced meat and squeezed onion, but shaped into a short, plump roll instead of being spread along the skewer, so the centre stays juicier. Iranian sources describe two ways: on skewers over charcoal, and the Tehrani \\"lule\\" cooked in a pan with butter and tomato. This recipe follows the charcoal method and gives the pan and oven methods as alternatives.","ar":"لوله كباب قريب من الكوبيده: اللحم المفروم الدسم نفسه والبصل المعصور، لكنه يُشكَّل لفافة قصيرة ممتلئة بدل أن يُفرد على طول السيخ، فيبقى قلبه أكثر عصارة. تذكر المصادر الإيرانية طريقتين: على الأسياخ فوق الفحم، و\xabلول كباب\xbb الطهرانية التي تُطهى في المقلاة بالزبدة والطماطم. تعتمد هذه الوصفة طريقة الفحم وتذكر المقلاة والفرن كبدائل."},"seoTitle":{"fa":"لوله‌کباب زغالی؛ طرز تهیه با لواش و پیاز سماقی","en":"Lule Kabab Recipe (Persian Minced Lamb Kebab)","ar":"لوله كباب: طريقة عمل كباب الضأن المفروم على الفحم"},"seoDescription":{"fa":"طرز تهیه لوله‌کباب برای ۴ نفر: ۸ لولهٔ کوتاه و چاق از گوشت چرخ‌کردهٔ گوسفندی و پیاز، روی زغال، با لواش، پیاز سماقی و جعفری؛ حدود ۲ ساعت با استراحت.","en":"Persian lule kabab for 4: 8 thick rolls of minced lamb and onion, grilled over charcoal and served on lavash with sumac onions and parsley. About 2 h.","ar":"طريقة عمل لوله كباب لأربعة أشخاص: ٨ لفائف سميكة من لحم الضأن المفروم والبصل تُشوى على الفحم وتُقدَّم على خبز اللواش مع البصل بالسمّاق والبقدونس."},"servings":4,"prep":40,"cook":20,"rest":60,"total":120,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"گوشت چرخ‌کردهٔ گوسفندی","en":"Minced lamb","ar":"لحم ضأن مفروم"},"amount":"600","unit":"گرم","optional":false,"group":{"fa":"مایهٔ کباب","en":"Kebab mixture","ar":"خليط الكباب"},"note":{"fa":"سردست با حدود ۲۰٪ چربی، دو بار چرخ‌شده؛ می‌توان ۲۰۰ گرم آن را گوساله گذاشت.","en":"Shoulder with about 20% fat, minced twice; 200 g may be veal.","ar":"من الكتف بنسبة دهن نحو ٢٠٪، مفروم مرتين؛ يمكن أن يكون ٢٠٠ غرام منه لحم عجل."}},{"name":{"fa":"دنبه","en":"Lamb tail fat","ar":"ألية الخروف"},"amount":"60","unit":"گرم","optional":true,"group":{"fa":"مایهٔ کباب","en":"Kebab mixture","ar":"خليط الكباب"},"note":{"fa":"ریز چرخ‌شده؛ اگر گوشت چرب است حذف کنید.","en":"Finely minced; omit if the meat is fatty.","ar":"مفرومة ناعمًا؛ احذفها إن كان اللحم دسمًا."}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"مایهٔ کباب","en":"Kebab mixture","ar":"خليط الكباب"},"note":{"fa":"متوسط (حدود ۲۵۰ گرم)، رنده و کاملاً آب‌گرفته.","en":"Medium (about 250 g), grated and squeezed dry.","ar":"متوسطة (نحو ٢٥٠ غرامًا)، مبشورة ومعصورة جيدًا."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ کباب","en":"Kebab mixture","ar":"خليط الكباب"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ کباب","en":"Kebab mixture","ar":"خليط الكباب"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"سماق","en":"Sumac","ar":"سمّاق"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ کباب","en":"Kebab mixture","ar":"خليط الكباب"},"note":{"fa":"داخل مایه.","en":"In the mixture.","ar":"داخل الخليط."}},{"name":{"fa":"گوجه‌فرنگی","en":"Tomato","ar":"طماطم"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"برای کباب کردن.","en":"For grilling.","ar":"للشوي."}},{"name":{"fa":"پیاز قرمز","en":"Red onion","ar":"بصل أحمر"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"نازک حلقه‌شده.","en":"Thinly sliced into rings.","ar":"مقطّعة حلقات رفيعة."}},{"name":{"fa":"سماق برای پیاز","en":"Sumac for the onion","ar":"سمّاق للبصل"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"جعفری تازه","en":"Fresh parsley","ar":"بقدونس طازج"},"amount":"0.5","unit":"پیمانه","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"درشت خردشده.","en":"Roughly chopped.","ar":"مفروم خشنًا."}},{"name":{"fa":"لیموترش","en":"Lemon","ar":"ليمون"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"قاچ‌شده.","en":"Cut into wedges.","ar":"مقطّع شرائح."}},{"name":{"fa":"نان لواش","en":"Lavash bread","ar":"خبز لواش"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) پیازهای متوسط را رنده کنید و در پارچهٔ تمیز محکم بفشارید تا آبشان کاملاً گرفته شود؛ آب پیاز را برای خیس کردن دست نگه دارید.\\n۲) دنبه را اگر چرخ‌نشده است بسیار ریز خرد کنید.\\n۳) پیاز قرمز را نازک حلقه کنید، با ۱ قاشق غذاخوری سماق مخلوط کنید و کنار بگذارید. جعفری را بشویید، خشک و درشت خرد کنید.","en":"1) Grate the medium onions and squeeze them hard in a clean cloth until dry; keep the juice for wetting your hands.\\n2) If the tail fat is not minced, chop it very finely.\\n3) Slice the red onion into thin rings, toss with 1 tbsp sumac and set aside. Wash, dry and roughly chop the parsley.","ar":"١) ابشر البصل المتوسط واعصره بقوة في قماش نظيف حتى يجف، واحتفظ بالعصير لترطيب يديك.\\n٢) إن لم تكن الألية مفرومة فافرمها ناعمًا جدًا.\\n٣) قطّع البصل الأحمر حلقات رفيعة واخلطه بملعقة كبيرة من السمّاق واتركه جانبًا. اغسل البقدونس وجففه وافرمه خشنًا."},"time":15,"image":{"src":"/recipes/lule-kabab/step-01.webp","alt":"فشردن پیاز رنده‌شده در پارچه و حلقه‌های پیاز قرمز با سماق","width":1200,"height":900}},{"n":2,"title":{"fa":"ورز دادن","en":"Knead","ar":"العجن"},"text":{"fa":"گوشت، دنبه، پیاز آب‌گرفته، نمک، فلفل سیاه و ۱ قاشق چای‌خوری سماق را در کاسه بریزید و ۱۰ تا ۱۵ دقیقه ورز دهید تا مایه چسبناک و یکدست شود و از دیوارهٔ کاسه راحت جدا شود.","en":"Put the meat, tail fat, squeezed onion, salt, black pepper and 1 tsp sumac in a bowl and knead for 10–15 minutes until sticky and uniform and it comes away cleanly from the side of the bowl.","ar":"ضع اللحم والألية والبصل المعصور والملح والفلفل الأسود وملعقة صغيرة من السمّاق في وعاء، واعجن ١٠–١٥ دقيقة حتى يصبح لزجًا متجانسًا وينفصل بسهولة عن جدار الوعاء."},"time":15,"image":{"src":"/recipes/lule-kabab/step-02.webp","alt":"ورز دادن گوشت چرخ‌کرده با پیاز، ادویه و سماق در کاسه","width":1200,"height":900}},{"n":3,"title":{"fa":"استراحت در یخچال","en":"Rest in the fridge","ar":"التبريد في الثلاجة"},"text":{"fa":"روی کاسه را بپوشانید و ۱ ساعت در یخچال بگذارید تا مایه سفت شود. ۳۰ دقیقهٔ آخر زغال را روشن کنید.","en":"Cover the bowl and chill for 1 hour until firm. Light the charcoal during the last 30 minutes.","ar":"غطِّ الوعاء وبرّده ساعة حتى يتماسك. أشعل الفحم في آخر ٣٠ دقيقة."},"time":60,"image":{"src":"/recipes/lule-kabab/step-03.webp","alt":"کاسهٔ پوشیدهٔ مایهٔ کباب در یخچال","width":1200,"height":900}},{"n":4,"title":{"fa":"شکل دادن لوله‌ها","en":"Shape the rolls","ar":"تشكيل اللفائف"},"text":{"fa":"مایه را به ۸ گلولهٔ حدود ۸۰ گرمی (اندازهٔ یک نارنگی کوچک) تقسیم کنید. دست را با آب پیاز خیس کنید، هر گلوله را دور سیخ پهن بگذارید و با فشار ملایم کف دست به لوله‌ای به طول ۱۰ تا ۱۲ و قطر حدود ۴ سانتی‌متر تبدیل کنید. دو سر لوله را محکم به سیخ بچسبانید. می‌توانید روی هر سیخ دو لوله با فاصله بگذارید.","en":"Divide the mixture into 8 balls of about 80 g (the size of a small tangerine). Wet your hands with onion juice, fit each ball around a wide skewer and roll it gently with your palm into a log 10–12 cm long and about 4 cm thick. Press both ends firmly onto the skewer. You can put two rolls, spaced apart, on each skewer.","ar":"قسّم الخليط إلى ٨ كرات وزن كلٍّ منها نحو ٨٠ غرامًا (بحجم يوسفية صغيرة). رطّب يديك بعصير البصل، وضع كل كرة حول سيخ عريض ودحرجها بكف اليد برفق لتصبح لفافة طولها ١٠–١٢ سم وقطرها نحو ٤ سم. اضغط الطرفين جيدًا على السيخ. يمكن وضع لفافتين متباعدتين على كل سيخ."},"time":10,"image":{"src":"/recipes/lule-kabab/step-04.webp","alt":"شکل دادن گلولهٔ گوشت به لوله‌ای ضخیم دور سیخ پهن با کف دست","width":1200,"height":900}},{"n":5,"title":{"fa":"کباب کردن","en":"Grill","ar":"الشوي"},"text":{"fa":"زغال باید سرخ، بی‌شعله و با لایهٔ نازک خاکستر باشد (حرارت متوسط). سیخ‌ها را بگذارید و در ۲ دقیقهٔ اول مرتب بچرخانید تا رویه ببندد؛ بعد هر ۱ تا ۲ دقیقه بچرخانید. کل پخت ۱۰ تا ۱۲ دقیقه است، چون لوله ضخیم‌تر از کوبیده است. تست پختگی: رویه قهوه‌ای تیره و کمی برشته، با فشار انگشت سفت ولی فنری، و وسط آن پس از برش صورتی نیست (۷۱ درجهٔ سانتی‌گراد با دماسنج). گوجه‌ها را هم‌زمان کنار آتش کباب کنید تا پوستشان چروک و سیاه شود.","en":"The coals should be red, flameless and lightly ashed (medium heat). Lay the skewers on and turn them constantly for the first 2 minutes so the surface sets; then turn every 1–2 minutes. Total cooking is 10–12 minutes, as the rolls are thicker than koobideh. Doneness test: deep brown and lightly charred outside, firm but springy when pressed, and no pink inside when cut (71 \xb0C with a thermometer). Grill the tomatoes at the same time until the skins wrinkle and blacken.","ar":"يجب أن يكون الفحم أحمر بلا لهب مع طبقة رماد رقيقة (حرارة متوسطة). ضع الأسياخ واقلبها باستمرار في أول دقيقتين حتى يتماسك السطح، ثم كل ١–٢ دقيقة. مجموع الشوي ١٠–١٢ دقيقة لأن اللفائف أسمك من الكوبيده. اختبار النضج: سطح بني داكن ومحمّر قليلًا، متماسك ومرن عند الضغط، ولا لون وردي في الداخل عند القطع (٧١ درجة مئوية بميزان الحرارة). اشوِ الطماطم في الوقت نفسه حتى يتجعد قشرها ويسودّ."},"time":12,"image":{"src":"/recipes/lule-kabab/step-05.webp","alt":"سیخ‌های لوله‌کباب روی زغال سرخ و بی‌شعله","width":1200,"height":900}},{"n":6,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"نان لواش را روی دیس پهن کنید، لوله‌ها را با کمک نان از سیخ جدا کنید و رویش بگذارید. پیاز سماقی، جعفری، گوجهٔ کبابی و قاچ لیموترش را کنارش بچینید.","en":"Spread lavash on a platter, slide the rolls off the skewers with a piece of bread and lay them on top. Arrange the sumac onions, parsley, grilled tomatoes and lemon wedges alongside.","ar":"افرد خبز اللواش في طبق، وأزل اللفائف عن الأسياخ بقطعة خبز وضعها فوقه، ورتّب البصل بالسمّاق والبقدونس والطماطم المشوية وشرائح الليمون بجانبها."},"time":8,"image":{"src":"/recipes/lule-kabab/step-06.webp","alt":"لوله‌ها روی لواش در دیس با پیاز سماقی، جعفری، گوجه و لیمو","width":1200,"height":900}}],"tips":{"fa":["لوله را خیلی بلند نکنید؛ لولهٔ کوتاه و چاق بهتر روی سیخ می‌ماند.","دست خیس مانع چسبیدن گوشت به دست می‌شود."],"en":["Keep the rolls short; short, plump rolls hold better.","Wet hands stop the meat sticking."],"ar":["لا تُطِل اللفائف؛ القصيرة الممتلئة تثبت أفضل.","اليد المبللة تمنع التصاق اللحم."]},"cover":{"src":"/recipes/lule-kabab/cover.webp","alt":"لوله‌کباب‌های کوتاه و ضخیم روی لواش با پیاز سماقی، جعفری، گوجهٔ کبابی و لیمو","width":1600,"height":1200},"serving":{"src":"/recipes/lule-kabab/serving.webp","alt":"لوله‌کباب پیچیده در لواش با جعفری و پیاز سماقی در دست","width":1200,"height":1500}},{"id":"shish-kabab","country":"IR","slugs":{"fa":"شیش-کباب","en":"shish-kabab","ar":"شيش-كباب"},"title":{"fa":"شیش‌کباب","en":"Shish Kabab","ar":"شيش كباب"},"summary":{"fa":"تکه‌های ۳ سانتی گوشت گوسفند یا گوساله که یک شب در ماست، پیاز، زعفران و آبلیمو خوابیده و یک‌درمیان با پیاز، فلفل دلمه‌ای و گوجه روی زغال کباب می‌شود.","en":"3 cm cubes of lamb or veal marinated overnight in yogurt, onion, saffron and lemon, threaded with onion, bell pepper and tomato and grilled over charcoal.","ar":"مكعبات من لحم الضأن أو العجل بطول ٣ سم تُنقع ليلة في اللبن والبصل والزعفران والليمون، ثم تُشكّ بالتناوب مع البصل والفلفل الحلو والطماطم وتُشوى على الفحم."},"intro":{"fa":"\xabشیش\xbb در ترکی به معنای سیخ است و شیش‌کباب نام کلی کباب‌های تکه‌ای سیخی است که در ایران با مرینیت ماست و زعفران رنگ و طعم ایرانی گرفته است. گوشت بی‌استخوان راسته یا ران به مکعب‌های هم‌اندازه بریده می‌شود تا یکنواخت بپزد، و سبزیجات لابه‌لای گوشت هم آب کباب را می‌گیرند و هم طعم دودی پیدا می‌کنند. نمک را آخر کار بزنید تا گوشت آبش را از دست ندهد.","en":"\\"Shish\\" means skewer in Turkish, and shish kabab is the general name for skewered meat cubes; in Iran it takes on a local character from a yogurt-and-saffron marinade. Boneless loin or leg is cut into even cubes so it cooks evenly, and the vegetables between the pieces catch the juices and pick up smoke. Salt at the end so the meat stays juicy.","ar":"\xabشيش\xbb تعني السيخ بالتركية، والشيش كباب اسم عام لقطع اللحم المشوية على الأسياخ، وقد اكتسب في إيران طابعًا محليًا من تتبيلة اللبن والزعفران. يُقطع اللحم المسحّب من الظهر أو الفخذ مكعبات متساوية لينضج بالتساوي، وتلتقط الخضار بين القطع عصارة اللحم ونكهة الدخان. يُضاف الملح في النهاية ليبقى اللحم طريًا."},"seoTitle":{"fa":"شیش‌کباب با ماست و زعفران؛ طرز تهیه روی زغال","en":"Shish Kabab Recipe (Persian Yogurt-Saffron Kebab)","ar":"شيش كباب: طريقة عمل الكباب الإيراني باللبن والزعفران"},"seoDescription":{"fa":"طرز تهیه شیش‌کباب برای ۴ نفر: تکه‌های گوشت گوسفند یا گوساله در ماست، پیاز، زعفران و آبلیمو یک شب می‌خوابد و با پیاز، فلفل دلمه‌ای و گوجه کباب می‌شود.","en":"Persian shish kabab for 4: lamb or veal cubes marinated overnight in yogurt, onion, saffron and lemon, grilled over charcoal with onion, pepper and tomato.","ar":"طريقة عمل شيش كباب لأربعة أشخاص: مكعبات ضأن أو عجل تُنقع ليلة في اللبن والبصل والزعفران والليمون، وتُشوى على الفحم مع البصل والفلفل والطماطم."},"servings":4,"prep":25,"cook":40,"rest":720,"total":785,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"گوشت راستهٔ گوسفندی یا گوساله","en":"Lamb or veal loin","ar":"لحم ظهر ضأن أو عجل"},"amount":"800","unit":"گرم","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"بی‌استخوان، پیه و رگ گرفته.","en":"Boneless, trimmed of sinew and hard fat.","ar":"مسحّب ومنزوع الأعصاب والدهن القاسي."}},{"name":{"fa":"ماست پرچرب","en":"Full-fat yogurt","ar":"لبن زبادي كامل الدسم"},"amount":"150","unit":"گرم","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"متوسط (حدود ۱۵۰ گرم)، رنده‌شده.","en":"Medium (about 150 g), grated.","ar":"متوسطة (نحو ١٥٠ غرامًا)، مبشورة."}},{"name":{"fa":"سیر","en":"Garlic","ar":"ثوم"},"amount":"2","unit":"حبه","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"له‌شده.","en":"Crushed.","ar":"مهروس."}},{"name":{"fa":"آبلیموی تازه","en":"Fresh lemon juice","ar":"عصير ليمون طازج"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن زیتون","en":"Olive oil","ar":"زيت زيتون"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زعفران سابیده","en":"Ground saffron","ar":"زعفران مطحون"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب جوش برای دم کردن زعفران","en":"Boiling water for blooming the saffron","ar":"ماء مغلي لنقع الزعفران"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"گوشت و مرینیت","en":"Meat and marinade","ar":"اللحم والتتبيلة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"پیاز کوچک سفید","en":"Small white onions","ar":"بصل أبيض صغير"},"amount":"8","unit":"عدد","optional":false,"group":{"fa":"سبزیجات سیخ","en":"Skewer vegetables","ar":"خضار الأسياخ"},"note":{"fa":"یا ۲ پیاز متوسط که چهار قاچ و لایه‌لایه شود.","en":"Or 2 medium onions, quartered and separated into layers.","ar":"أو بصلتان متوسطتان مقطعتان أرباعًا ومفصولتان طبقات."}},{"name":{"fa":"فلفل دلمه‌ای","en":"Bell pepper","ar":"فلفل حلو"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"سبزیجات سیخ","en":"Skewer vegetables","ar":"خضار الأسياخ"},"note":{"fa":"قطعه‌های ۳ سانتی.","en":"3 cm pieces.","ar":"قطع ٣ سم."}},{"name":{"fa":"گوجه‌گیلاسی","en":"Cherry tomatoes","ar":"طماطم كرزية"},"amount":"12","unit":"عدد","optional":false,"group":{"fa":"سبزیجات سیخ","en":"Skewer vegetables","ar":"خضار الأسياخ"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"برای پخت و سرو","en":"For cooking and serving","ar":"للطهي والتقديم"},"note":{"fa":"هنگام کباب کردن.","en":"Added while grilling.","ar":"يُضاف أثناء الشوي."}},{"name":{"fa":"کره","en":"Butter","ar":"زبدة"},"amount":"30","unit":"گرم","optional":false,"group":{"fa":"برای پخت و سرو","en":"For cooking and serving","ar":"للطهي والتقديم"},"note":{"fa":"آب‌شده.","en":"Melted.","ar":"مذابة."}},{"name":{"fa":"نان لواش","en":"Lavash bread","ar":"خبز لواش"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"برای پخت و سرو","en":"For cooking and serving","ar":"للطهي والتقديم"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) گوشت را با دستمال کاغذی خشک کنید، رگ و پیه سفت را جدا کنید و به مکعب‌های حدود ۳ سانتی‌متری ببرید؛ هم‌اندازه بودن تکه‌ها مهم است.\\n۲) پیاز متوسط را رنده و سیر را له کنید.\\n۳) زعفران را با ۲ قاشق غذاخوری آب جوش دم کنید و ۵ دقیقه بگذارید.","en":"1) Pat the meat dry, trim sinew and hard fat, and cut it into cubes of about 3 cm; even size matters.\\n2) Grate the medium onion and crush the garlic.\\n3) Bloom the saffron in 2 tbsp boiling water for 5 minutes.","ar":"١) جفف اللحم بالمناديل الورقية، وانزع الأعصاب والدهن القاسي، وقطّعه مكعبات بطول ٣ سم تقريبًا؛ تساوي الحجم مهم.\\n٢) ابشر البصلة المتوسطة واهرس الثوم.\\n٣) انقع الزعفران في ملعقتين كبيرتين من الماء المغلي ٥ دقائق."},"time":15,"image":{"src":"/recipes/shish-kabab/step-01.webp","alt":"مکعب‌های گوشت روی تخته، پیاز رنده‌شده، سیر له‌شده و زعفران دم‌کرده","width":1200,"height":900}},{"n":2,"title":{"fa":"مرینیت کردن","en":"Marinate","ar":"التتبيل"},"text":{"fa":"ماست، پیاز رنده‌شده، سیر، آبلیمو، روغن زیتون، زعفران دم‌کرده و فلفل سیاه را در کاسهٔ شیشه‌ای هم بزنید. گوشت را اضافه کنید و با دست مخلوط کنید تا همهٔ تکه‌ها پوشیده شوند. نمک نزنید. روی کاسه را بپوشانید.","en":"Stir together the yogurt, grated onion, garlic, lemon juice, olive oil, saffron water and black pepper in a glass bowl. Add the meat and mix by hand until every piece is coated. Do not add salt. Cover the bowl.","ar":"اخلط اللبن والبصل المبشور والثوم وعصير الليمون وزيت الزيتون وماء الزعفران والفلفل الأسود في وعاء زجاجي. أضف اللحم وقلّبه باليد حتى تُغطّى كل القطع. لا تضف الملح. غطِّ الوعاء."},"time":10,"image":{"src":"/recipes/shish-kabab/step-02.webp","alt":"تکه‌های گوشت پوشیده با مرینیت ماست و زعفران در کاسهٔ شیشه‌ای","width":1200,"height":900}},{"n":3,"title":{"fa":"استراحت در یخچال","en":"Rest in the fridge","ar":"التبريد في الثلاجة"},"text":{"fa":"کاسه را ۱۲ ساعت (یک شب) در یخچال بگذارید و یک بار وسط کار هم بزنید. حداقل زمان ۴ ساعت است و بیشتر از ۲۴ ساعت نگه ندارید، چون ماست و آبلیمو بافت گوشت را خمیری می‌کند.","en":"Refrigerate for 12 hours (overnight), stirring once halfway. The minimum is 4 hours; do not go beyond 24 hours, as the yogurt and lemon make the texture mushy.","ar":"ضع الوعاء في الثلاجة ١٢ ساعة (ليلة كاملة) وقلّبه مرة في المنتصف. الحد الأدنى ٤ ساعات، ولا تتجاوز ٢٤ ساعة لأن اللبن والليمون يجعلان قوام اللحم عجينيًا."},"time":720,"image":{"src":"/recipes/shish-kabab/step-03.webp","alt":"کاسهٔ شیشه‌ای پوشیدهٔ گوشت مرینیت‌شده در یخچال","width":1200,"height":900}},{"n":4,"title":{"fa":"روشن کردن زغال و سیخ کشیدن","en":"Light the coals and thread the skewers","ar":"إشعال الفحم وتشكيل الأسياخ"},"text":{"fa":"زغال را روشن کنید؛ حدود ۲۵ دقیقه طول می‌کشد تا سرخ شود و رویش خاکستر بنشیند. در همین فاصله گوشت را از یخچال بیرون بیاورید، مرینیت اضافه را با دست بگیرید و تکه‌ها را یک‌درمیان با لایهٔ پیاز، فلفل دلمه‌ای و گوجه‌گیلاسی به سیخ بکشید. تکه‌ها را به هم نچسبانید؛ حدود ۲ میلی‌متر فاصله بگذارید تا گرما به همه طرف برسد.","en":"Light the charcoal; it takes about 25 minutes to glow red under a coat of ash. Meanwhile take the meat out, wipe off excess marinade by hand and thread the pieces alternately with onion layers, bell pepper and cherry tomatoes. Do not pack them tight; leave about 2 mm between pieces so heat reaches every side.","ar":"أشعل الفحم؛ يحتاج نحو ٢٥ دقيقة ليتوهج وتعلوه طبقة رماد. في هذه الأثناء أخرج اللحم وأزل التتبيلة الزائدة باليد، واشبك القطع بالتناوب مع طبقات البصل والفلفل الحلو والطماطم الكرزية. لا ترصّها؛ اترك نحو ٢ ملم بين القطع ليصل الحر إلى كل الجوانب."},"time":25,"image":{"src":"/recipes/shish-kabab/step-04.webp","alt":"سیخ کشیدن یک‌درمیان گوشت، پیاز، فلفل دلمه‌ای و گوجه کنار زغال","width":1200,"height":900}},{"n":5,"title":{"fa":"کباب کردن","en":"Grill","ar":"الشوي"},"text":{"fa":"سیخ‌ها را روی زغال با حرارت ملایم تا متوسط بگذارید (دست را در ۱۰ سانتی‌متری ۵ تا ۶ ثانیه می‌توانید نگه دارید). هر ۲ دقیقه یک چهارم دور بچرخانید؛ کل پخت ۸ تا ۱۰ دقیقه است. وسط پخت نمک را روی سیخ‌ها بپاشید. تست پختگی: لبه‌های گوشت کمی برشته و قهوه‌ای است و اگر یک تکهٔ وسطی را ببرید، آبی که بیرون می‌آید شفاف یا کم‌رنگ است نه قرمز.","en":"Set the skewers over low-to-medium coals (you can hold your hand 10 cm above for 5–6 seconds). Give them a quarter turn every 2 minutes; total cooking is 8–10 minutes. Sprinkle the salt over the skewers halfway through. Doneness test: the edges are lightly charred and brown, and when you cut a middle piece the juice runs clear or pale, not red.","ar":"ضع الأسياخ فوق فحم بحرارة منخفضة إلى متوسطة (تستطيع إبقاء يدك على ارتفاع ١٠ سم ٥–٦ ثوانٍ). أدرها ربع دورة كل دقيقتين؛ مجموع الشوي ٨–١٠ دقائق. رشّ الملح على الأسياخ في منتصف الشوي. اختبار النضج: حواف اللحم محمرة قليلًا، وعند قطع قطعة من الوسط تكون العصارة صافية أو فاتحة لا حمراء."},"time":10,"image":{"src":"/recipes/shish-kabab/step-05.webp","alt":"سیخ‌های شیش‌کباب در حال کباب شدن روی زغال خاکسترنشسته","width":1200,"height":900}},{"n":6,"title":{"fa":"کره زدن و سرو","en":"Butter and serve","ar":"الدهن بالزبدة والتقديم"},"text":{"fa":"سیخ‌ها را از روی آتش بردارید، با کرهٔ آب‌شده چرب کنید و روی نان لواش بگذارید. لواش را روی کباب‌ها تا بزنید و ۲ تا ۳ دقیقه صبر کنید تا آب گوشت به نان برسد، بعد سرو کنید.","en":"Lift the skewers off the fire, brush with melted butter and lay them on lavash. Fold the bread over the kebabs and wait 2–3 minutes so the juices soak in, then serve.","ar":"ارفع الأسياخ عن النار وادهنها بالزبدة المذابة وضعها على خبز اللواش. اطوِ الخبز فوقها وانتظر ٢–٣ دقائق لتتشرب العصارة ثم قدّمها."},"time":5,"image":{"src":"/recipes/shish-kabab/step-06.webp","alt":"چرب کردن سیخ‌های کباب با کرهٔ آب‌شده روی نان لواش","width":1200,"height":900}}],"tips":{"fa":["مکعب‌های هم‌اندازه یعنی پخت یکنواخت.","سیخ چوبی خیس‌نخورده می‌سوزد.","گوشت را ۲۰ دقیقه پیش از کباب کردن از یخچال بیرون بگذارید."],"en":["Even cubes cook evenly.","Unsoaked wooden skewers burn.","Take the meat out of the fridge 20 minutes before grilling."],"ar":["المكعبات المتساوية تنضج بالتساوي.","الأسياخ الخشبية غير المنقوعة تحترق.","أخرج اللحم من الثلاجة قبل الشوي بعشرين دقيقة."]},"cover":{"src":"/recipes/shish-kabab/cover.webp","alt":"چهار سیخ شیش‌کباب با تکه‌های گوشت، پیاز، فلفل دلمه‌ای و گوجه روی نان لواش","width":1600,"height":1200},"serving":{"src":"/recipes/shish-kabab/serving.webp","alt":"تکه‌های شیش‌کباب روی لواش با کاسهٔ برنج، ریحان، تربچه و دوغ","width":1200,"height":1500}},{"id":"sirabij","country":"IR","slugs":{"fa":"سیرابیج","en":"sirabij","ar":"سيرابيج"},"title":{"fa":"سیرابیج","en":"Sirabij (Gilani Garlic-Leaf and Egg)","ar":"سيرابيج (أوراق الثوم بالبيض على الطريقة الجيلانية)"},"summary":{"fa":"خوراک ساده و معطر گیلانی از برگ سیر تازهٔ خردشده که در روغن آرام سرخ می‌شود تا سبز زیتونی تیره شود و با تخم‌مرغ هم زده می‌شود؛ با کته سرو می‌شود.","en":"A simple, fragrant Gilani dish of chopped fresh garlic leaves slowly fried in oil until dark olive green, then scrambled with eggs; served with kateh rice.","ar":"طبق جيلاني بسيط عطري من أوراق الثوم الطازجة المفرومة تُقلى ببطء في الزيت حتى يصير لونها أخضر زيتونيًا داكنًا، ثم تُخلط بالبيض؛ تُقدَّم مع أرز الكته."},"intro":{"fa":"\xabواویج\xbb یا \xabابیج\xbb در گیلکی یعنی سرخ‌شده، و سیرابیج یعنی سیرِ سرخ‌کرده. این غذا در بهار و پاییز که برگ سیر تازه در بازارهای گیلان فراوان است درست می‌شود و جزو خانوادهٔ \xabنرگسی\xbb‌هاست: سبزی سرخ‌شده با تخم‌مرغ. برگ سیر حجم زیادی دارد ولی هنگام سرخ شدن مثل اسفناج به‌شدت جمع می‌شود، پس از حجم ظرف نترسید. راز طعمش سرخ کردن صبورانه روی حرارت ملایم است تا بوی تند سیر خام برود و شیرین شود.","en":"\\"Vavij\\" or \\"abij\\" means fried in Gilaki, so sirabij is simply fried garlic. It is made in spring and autumn when fresh garlic leaves fill Gilan\'s markets, and belongs to the \\"nargesi\\" family of fried greens with egg. Garlic leaves look like a huge pile but shrink dramatically when fried, like spinach, so don\'t be put off by the volume. The secret is patient frying on low heat until the raw garlic sharpness turns sweet.","ar":"\xabواويج\xbb أو \xabأبيج\xbb بالجيلكية تعني المقلي، فالسيرابيج هو الثوم المقلي. يُحضَّر في الربيع والخريف حين تمتلئ أسواق جيلان بأوراق الثوم الطازجة، وينتمي إلى عائلة \xabنرگسي\xbb أي الخضار المقلية بالبيض. تبدو أوراق الثوم كومة ضخمة لكنها تنكمش كثيرًا عند القلي مثل السبانخ، فلا يخيفك حجمها. السر في القلي الصبور على نار هادئة حتى تزول حدّة الثوم النيء ويحلو طعمه."},"seoTitle":{"fa":"سیرابیج گیلانی؛ طرز تهیه برگ سیر با تخم‌مرغ","en":"Sirabij Recipe (Gilani Garlic Leaves with Egg)","ar":"سيرابيج: طريقة عمل أوراق الثوم بالبيض على الطريقة الجيلانية"},"seoDescription":{"fa":"طرز تهیه سیرابیج گیلانی برای ۴ نفر: برگ سیر تازهٔ خردشده که آرام در روغن سرخ و با تخم‌مرغ و زردچوبه هم زده می‌شود؛ آسان، حدود ۸۰ دقیقه، با کته.","en":"Easy Gilani dish for 4: chopped fresh garlic leaves fried slowly until dark olive green, then scrambled with eggs. About 80 min; serve with kateh rice.","ar":"طريقة عمل سيرابيج الجيلاني لأربعة أشخاص: أوراق ثوم طازجة مفرومة تُقلى ببطء في الزيت ثم تُخلط بالبيض؛ طبق سهل يستغرق نحو ٨٠ دقيقة ويُقدَّم مع أرز الكته."},"servings":4,"prep":20,"cook":30,"rest":30,"total":80,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"برگ سیر تازه","en":"Fresh garlic leaves","ar":"أوراق ثوم طازجة"},"amount":"600","unit":"گرم","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"وزن پس از پاک کردن؛ در صورت نبود، برگ سیر فریزی.","en":"Weight after trimming; frozen garlic leaves if fresh are unavailable.","ar":"الوزن بعد التنظيف؛ أو أوراق ثوم مجمدة إن لم تتوفر الطازجة."}},{"name":{"fa":"نمک برای آب نمک","en":"Salt for the brine","ar":"ملح لماء التنظيف"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"4","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"120","unit":"میلی‌لیتر","optional":true,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"اختیاری، برای نرم کردن برگ‌های سفت.","en":"Optional, to soften tough leaves.","ar":"اختياري لتطرية الأوراق القاسية."}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"تخم‌مرغ","en":"Eggs","ar":"بيض"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"کره","en":"Butter","ar":"زبدة"},"amount":"20","unit":"گرم","optional":true,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"اختیاری، برای عطر.","en":"Optional, for aroma.","ar":"اختياري للنكهة."}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) ریشه و قسمت‌های زرد و خشک برگ‌های سیر را جدا کنید.\\n۲) برگ‌ها را زیر آب روان بشویید تا گل لای ساقه‌ها برود.\\n۳) تخم‌مرغ‌ها را در کاسه بشکنید ولی هنوز هم نزنید.","en":"1) Trim the roots and any yellow or dry parts from the garlic leaves.\\n2) Rinse under running water to wash mud from between the stalks.\\n3) Crack the eggs into a bowl but don\'t beat them yet.","ar":"١) انزع الجذور والأجزاء الصفراء واليابسة من أوراق الثوم.\\n٢) اغسلها تحت الماء الجاري لإزالة الطين بين السيقان.\\n٣) اكسر البيض في وعاء دون خفقه بعد."},"time":10,"image":{"src":"/recipes/sirabij/step-01.webp","alt":"برگ‌های سیر پاک‌شده زیر آب روان و تخم‌مرغ‌های شکسته در کاسه","width":1200,"height":900}},{"n":2,"title":{"fa":"خیساندن و آب نمک","en":"Soak and brine","ar":"النقع والتنظيف بالماء المالح"},"text":{"fa":"برگ‌ها را ۱۰ دقیقه در آب سرد خیس کنید و آبکش کنید. سپس ۱ قاشق غذاخوری نمک را در ۲ لیتر آب حل کنید و برگ‌ها را ۱۰ دقیقهٔ دیگر در آن بگذارید. آبکش کنید، یک بار با آب ساده بشویید و ۱۰ دقیقه روی پارچهٔ تمیز پهن کنید تا آبشان برود.","en":"Soak the leaves in cold water for 10 minutes and drain. Dissolve 1 tbsp salt in 2 litres of water and leave the leaves in it for another 10 minutes. Drain, rinse once in plain water and spread on a clean cloth for 10 minutes to dry.","ar":"انقع الأوراق في ماء بارد ١٠ دقائق ثم صفّها. أذب ملعقة كبيرة من الملح في لترين من الماء واترك الأوراق فيه ١٠ دقائق أخرى. صفّها واشطفها مرة بماء عادي وافردها على قماشة نظيفة ١٠ دقائق لتجف."},"time":30,"image":{"src":"/recipes/sirabij/step-02.webp","alt":"برگ‌های سیر خیس‌خورده در کاسهٔ آب نمک و پهن‌شده روی پارچه","width":1200,"height":900}},{"n":3,"title":{"fa":"خرد کردن","en":"Chop","ar":"الفرم"},"text":{"fa":"برگ‌ها را دسته کنید و با چاقوی تیز به تکه‌های ۱ تا ۲ سانتی‌متری (نصف تا یک بند انگشت) ببرید.","en":"Bunch the leaves and cut them with a sharp knife into 1–2 cm pieces (half to one finger joint).","ar":"اجمع الأوراق وقطّعها بسكين حاد قطعًا من ١ إلى ٢ سم (نصف عقلة إصبع إلى عقلة)."},"time":10,"image":{"src":"/recipes/sirabij/step-03.webp","alt":"خرد کردن دستهٔ برگ سیر با چاقو روی تخته","width":1200,"height":900}},{"n":4,"title":{"fa":"سرخ کردن برگ سیر","en":"Fry the garlic leaves","ar":"قلي أوراق الثوم"},"text":{"fa":"روغن را در تابهٔ بزرگ و پهن روی حرارت متوسط داغ کنید. برگ‌های سیر را اضافه کنید (ظرف پر می‌شود) و ۵ دقیقه مرتب هم بزنید تا پلاسیده شوند و حجمشان نصف شود. اگر برگ‌ها سفت و ساقه‌دارند، آب را اضافه کنید، درِ تابه را بگذارید و ۵ دقیقه بپزید تا آب تبخیر شود. حرارت را ملایم کنید و ۱۵ تا ۲۰ دقیقه دیگر، هر ۲ تا ۳ دقیقه یک بار، هم بزنید. نشانهٔ آماده بودن: رنگ از سبز روشن به سبز زیتونی تیره رسیده، لبه‌ها کمی برشته‌اند ولی سیاه نیستند و بوی تند سیر خام به بوی شیرین تبدیل شده است. زردچوبه، نمک و فلفل سیاه را اضافه کنید و ۱ دقیقه تفت دهید.","en":"Heat the oil in a large, wide frying pan over medium heat. Add the garlic leaves (the pan will be full) and stir constantly for 5 minutes until they wilt and halve in volume. If the leaves are tough and stalky, add the water, cover and cook 5 minutes until it evaporates. Lower the heat and cook 15–20 minutes more, stirring every 2–3 minutes. Ready when the colour has gone from bright green to dark olive green, the edges are lightly crisp but not black, and the sharp raw-garlic smell has turned sweet. Add the turmeric, salt and black pepper and fry 1 minute.","ar":"سخّن الزيت في مقلاة كبيرة عريضة على نار متوسطة. أضف أوراق الثوم (ستمتلئ المقلاة) وقلّب باستمرار ٥ دقائق حتى تذبل ويقل حجمها إلى النصف. إن كانت الأوراق قاسية ذات سيقان فأضف الماء وغطِّ واطهُ ٥ دقائق حتى يتبخر. خفّف النار واطهُ ١٥–٢٠ دقيقة أخرى مع التقليب كل ٢–٣ دقائق. تكون جاهزة حين يتحول اللون من الأخضر الفاتح إلى الأخضر الزيتوني الداكن، وتتحمص الحواف قليلًا دون أن تسودّ، وتتحول رائحة الثوم النيء الحادة إلى رائحة حلوة. أضف الكركم والملح والفلفل الأسود وقلّب دقيقة."},"time":24,"image":{"src":"/recipes/sirabij/step-04.webp","alt":"برگ‌های خردشدهٔ سیر در حال تفت خوردن در تابهٔ پهن","width":1200,"height":900}},{"n":5,"title":{"fa":"افزودن تخم‌مرغ","en":"Add the eggs","ar":"إضافة البيض"},"text":{"fa":"اگر کره دارید، در تابه آب کنید. وسط برگ‌ها چند گودی باز کنید و تخم‌مرغ‌ها را بریزید. ۱ دقیقه صبر کنید تا سفیده کمی ببندد، بعد با کفگیر آرام هم بزنید تا تخم‌مرغ تکه‌تکه با سیر مخلوط شود. ۳ تا ۵ دقیقه روی حرارت ملایم بپزید تا هیچ قسمت آبکی و شفافی از تخم‌مرغ نماند. داغ سرو کنید.","en":"If using butter, melt it in the pan. Make a few wells in the leaves and crack in the eggs. Wait 1 minute until the whites begin to set, then stir gently with a spatula so the egg mixes through in pieces. Cook 3–5 minutes on low until no runny or translucent egg remains. Serve hot.","ar":"إن استخدمت الزبدة فأذبها في المقلاة. افتح بضع حفر بين الأوراق واكسر فيها البيض. انتظر دقيقة حتى يبدأ البياض بالتماسك، ثم قلّب برفق بالملعقة ليختلط البيض قطعًا مع الثوم. اطهُ ٣–٥ دقائق على نار هادئة حتى لا يبقى بيض سائل أو شفاف. قدّمه ساخنًا."},"time":6,"image":{"src":"/recipes/sirabij/step-05.webp","alt":"تخم‌مرغ‌های شکسته در گودی‌های میان برگ‌های سیر در تابه","width":1200,"height":900}}],"tips":{"fa":["حجم زیاد برگ سیر طبیعی است؛ چهار برابر جمع می‌شود.","برگ سیر را خشک وارد روغن کنید تا آب‌پز نشود.","سیر تازه را می‌توان خردشده فریز کرد."],"en":["The large volume is normal; it shrinks about fourfold.","Add the leaves dry so they fry rather than stew.","Chopped fresh garlic leaves freeze well."],"ar":["الحجم الكبير طبيعي؛ ينكمش نحو أربعة أضعاف.","أضف الأوراق جافة لتُقلى لا لتُسلق.","يمكن تجميد أوراق الثوم المفرومة."]},"cover":{"src":"/recipes/sirabij/cover.webp","alt":"تابهٔ سیرابیج با برگ سیر سرخ‌شده و تکه‌های تخم‌مرغ کنار کته و ماهی دودی","width":1600,"height":1200},"serving":{"src":"/recipes/sirabij/serving.webp","alt":"بشقاب کته با سیرابیج، زیتون و ماهی دودی","width":1200,"height":1500}},{"id":"tabaheg","country":"IR","slugs":{"fa":"تباهگ","en":"tabaheg","ar":"تباهك"},"title":{"fa":"تباهگ","en":"Tabaheg (Baluchi Pomegranate-Cured Lamb)","ar":"تباهك (لحم ضأن بلوشي مجفف بالرمان)"},"summary":{"fa":"گوشت گوسفندِ ورقه‌شده که با نمک و پودر انار ترش خشک می‌شود، سپس در آب می‌جوشد تا نرم شود و برنج در همان آب‌گوشت معطر پخته می‌شود؛ غذای اصیل بلوچستان.","en":"Thin slices of lamb cured with salt and sour pomegranate powder and dried, then simmered until tender, with rice cooked in the fragrant broth; a classic of Baluchestan.","ar":"شرائح رقيقة من لحم الضأن تُعالج بالملح ومسحوق الرمان الحامض وتُجفف، ثم تُسلق حتى تطرى، ويُطهى الأرز في مرقها العطري؛ طبق أصيل من بلوشستان."},"intro":{"fa":"تباهگ در اصل روشی چندصدساله برای نگهداری گوشت در گرمای بلوچستان است: پس از قربانی یا ذبح، گوشت را ورقه‌ورقه می‌کردند، با نمک و پودر دانهٔ انار ترش می‌پوشاندند و یک هفته تا ده روز زیر آفتاب خشک می‌کردند. گوشت خشک‌شده ماه‌ها می‌ماند و هر بار مقداری از آن را می‌جوشاندند و با آبش پلو می‌پختند. این غذا در شهرهای ساحلی خلیج فارس هم شناخته شده است. این دستور همان روش سنتی آفتابی را دنبال می‌کند، پس گوشت را دست‌کم یک هفته پیش از روز پخت آماده کنید.","en":"Tabaheg is at heart a centuries-old way of preserving meat in the Baluchi heat: after slaughter the meat was sliced, coated in salt and ground sour pomegranate seeds, and sun-dried for one week to ten days. The dried meat kept for months; a portion was boiled whenever needed and rice was cooked in its broth. The dish is also known in the Persian Gulf coastal towns. This recipe follows the traditional sun-drying method, so start the meat at least a week before cooking day.","ar":"التباهك في الأصل طريقة عمرها قرون لحفظ اللحم في حرّ بلوشستان: بعد الذبح يُقطَّع اللحم شرائح ويُغطّى بالملح ومسحوق بذور الرمان الحامض ويُجفف تحت الشمس من أسبوع إلى عشرة أيام. يبقى اللحم المجفف شهورًا، ويُسلق منه جزء عند الحاجة ويُطهى الأرز في مرقه. يُعرف الطبق أيضًا في مدن ساحل الخليج. تتبع هذه الوصفة طريقة التجفيف الشمسي التقليدية، فابدأ تحضير اللحم قبل يوم الطهي بأسبوع على الأقل."},"seoTitle":{"fa":"تباهگ بلوچی؛ طرز تهیه گوشت خشک با انار ترش و پلو","en":"Tabaheg Recipe (Baluchi Pomegranate-Cured Lamb)","ar":"تباهك: طريقة عمل لحم الضأن البلوشي المجفف بالرمان"},"seoDescription":{"fa":"طرز تهیه تباهگ بلوچی برای ۴ نفر: ورقه‌های گوشت گوسفند با نمک و پودر انار ترش دست‌کم یک هفته زیر آفتاب خشک، سپس جوشانده و برنج در آب آن پخته می‌شود.","en":"Baluchi tabaheg for 4: lamb slices cured with salt and sour pomegranate powder, sun-dried for at least a week, then simmered; rice is cooked in the broth.","ar":"طريقة عمل تباهك لأربعة أشخاص: شرائح لحم ضأن تُعالج بالملح ومسحوق الرمان الحامض وتُجفف تحت الشمس أسبوعًا على الأقل، ثم تُسلق ويُطهى الأرز في مرقها."},"servings":4,"prep":25,"cook":105,"rest":10110,"total":10240,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"گوشت ران گوسفند بدون استخوان","en":"Boneless lamb leg","ar":"فخذ ضأن بلا عظم"},"amount":"800","unit":"گرم","optional":false,"group":{"fa":"گوشت تباهگ","en":"Tabaheg meat","ar":"لحم التباهك"},"note":{"fa":"کم‌چربی.","en":"Lean.","ar":"قليل الدهن."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"گوشت تباهگ","en":"Tabaheg meat","ar":"لحم التباهك"},"note":{"fa":"برای پوشاندن گوشت.","en":"For curing the meat.","ar":"لتمليح اللحم."}},{"name":{"fa":"پودر انار ترش","en":"Sour pomegranate-seed powder","ar":"مسحوق بذور الرمان الحامض"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"گوشت تباهگ","en":"Tabaheg meat","ar":"لحم التباهك"},"note":{"fa":"دانهٔ انار خشک آسیاب‌شده.","en":"Ground dried pomegranate seeds (anardana).","ar":"بذور رمان مجففة مطحونة."}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"1.5","unit":"لیتر","optional":false,"group":{"fa":"گوشت تباهگ","en":"Tabaheg meat","ar":"لحم التباهك"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"گوشت تباهگ","en":"Tabaheg meat","ar":"لحم التباهك"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"1","unit":"قاشق غذاخوری","optional":true,"group":{"fa":"گوشت تباهگ","en":"Tabaheg meat","ar":"لحم التباهك"},"note":{"fa":"اختیاری، برای تفت دادن گوشت.","en":"Optional, for frying the meat.","ar":"اختياري لتحمير اللحم."}},{"name":{"fa":"برنج ایرانی","en":"Iranian rice","ar":"أرز إيراني"},"amount":"2","unit":"پیمانه","optional":false,"group":{"fa":"پلو","en":"Rice","ar":"الأرز"},"note":{"fa":"پیمانهٔ ۲۴۰ میلی‌لیتری.","en":"240 ml cups.","ar":"كوب ٢٤٠ مل."}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"150","unit":"گرم","optional":false,"group":{"fa":"پلو","en":"Rice","ar":"الأرز"},"note":{"fa":"یک عدد متوسط، نگینی.","en":"1 medium, diced.","ar":"حبة متوسطة مقطعة مكعبات."}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"4","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"پلو","en":"Rice","ar":"الأرز"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"0","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"پلو","en":"Rice","ar":"الأرز"},"note":{"fa":"پس از چشیدن آب‌گوشت؛ ممکن است لازم نباشد.","en":"After tasting the broth; may not be needed.","ar":"بعد تذوق المرق؛ قد لا يلزم."}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) چربی و پی گوشت را جدا کنید.\\n۲) گوشت را در کیسه بپیچید و ۳۰ دقیقه در فریزر بگذارید تا سفت شود و راحت ورقه شود (زمان استراحت).\\n۳) اگر پودر انار ندارید، دانهٔ انار خشک را آسیاب کنید.","en":"1) Trim fat and sinew from the meat.\\n2) Wrap the meat and put it in the freezer for 30 minutes to firm up for easier slicing (rest time).\\n3) If you have no pomegranate powder, grind dried pomegranate seeds.","ar":"١) انزع الدهن والأعصاب من اللحم.\\n٢) لفّ اللحم وضعه في المجمد ٣٠ دقيقة ليتماسك ويسهل تقطيعه (وقت راحة).\\n٣) إن لم يتوفر مسحوق الرمان فاطحن بذور الرمان المجففة."},"time":40,"image":{"src":"/recipes/tabaheg/step-01.webp","alt":"ران برهٔ پاک‌شده روی تخته و کاسهٔ کوچک پودر انار قرمز تیره","width":1200,"height":900}},{"n":2,"title":{"fa":"ورقه کردن و نمک‌سود","en":"Slice and cure","ar":"التقطيع والتمليح"},"text":{"fa":"گوشت را در جهت مخالف رگه‌ها به ورقه‌های ۵ میلی‌متری ببرید. نمک و پودر انار را مخلوط کنید و هر ورقه را از دو طرف کامل به آن آغشته کنید؛ سطح گوشت باید یکدست قرمز تیره شود و هیچ بخشی بدون ادویه نماند.","en":"Slice the meat across the grain into 5 mm slices. Mix the salt and pomegranate powder and coat each slice fully on both sides; the surface should be evenly dark red with no bare patches.","ar":"قطّع اللحم عكس الألياف شرائح بسماكة ٥ مم. اخلط الملح ومسحوق الرمان وغطِّ كل شريحة به من الجانبين تمامًا؛ يجب أن يصبح سطحها أحمر داكنًا متجانسًا دون أي جزء مكشوف."},"time":15,"image":{"src":"/recipes/tabaheg/step-02.webp","alt":"ورقه‌های نازک گوشت بره آغشته به نمک و پودر انار","width":1200,"height":900}},{"n":3,"title":{"fa":"خشک کردن زیر آفتاب","en":"Sun-dry","ar":"التجفيف تحت الشمس"},"text":{"fa":"ورقه‌ها را با یک پارچهٔ توری نازک و تمیز بپوشانید یا در آن بپیچید تا گردوغبار و مگس به گوشت نرسد، و روی بند یا طناب در جایی بیاویزید که آفتاب مستقیم به آن بتابد و هوا خشک باشد. یک هفته بگذارید خشک شود؛ اگر هنوز کاملاً خشک نشده، تا ۱۰ روز ادامه دهید. نشانهٔ آماده بودن: گوشت کاملاً خشک است و با فشار انگشت رطوبتی نمی‌دهد.","en":"Cover the slices with, or wrap them in, a thin clean mesh cloth to keep dust and flies off, and hang them on a line where direct sun reaches them and the air is dry. Leave for one week to dry; if not fully dry yet, continue up to 10 days. Ready when the meat is completely dry and releases no moisture when pressed.","ar":"غطِّ الشرائح بقماش شبكي رقيق نظيف أو لفّها به لحمايتها من الغبار والذباب، وعلّقها على حبل في مكان تصله الشمس المباشرة وهواؤه جاف. اتركها أسبوعًا لتجف؛ وإن لم تجف تمامًا فاستمر حتى ١٠ أيام. تكون جاهزة حين يجف اللحم تمامًا ولا يُخرج رطوبة عند الضغط."},"time":10080,"image":{"src":"/recipes/tabaheg/step-03.webp","alt":"ورقه‌های گوشت نمک‌سود با انار آویزان روی طناب زیر پارچهٔ توری در آفتاب","width":1200,"height":900}},{"n":4,"title":{"fa":"جوشاندن گوشت","en":"Simmer the meat","ar":"سلق اللحم"},"text":{"fa":"ورقه‌های خشک را با ۱٫۵ لیتر آب و فلفل سیاه در قابلمه بریزید و روی حرارت زیاد به جوش بیاورید. کف را بگیرید، حرارت را ملایم کنید و با درِ نیمه‌باز ۵۰ دقیقه بجوشانید تا گوشت با چنگال راحت تکه شود. نمک اضافه نکنید؛ گوشت خودش شور است. هم‌زمان، برنج را ۲ بار بشویید و در آب سرد خیس کنید (جدا شمرده نشده).","en":"Put the dried slices in a pot with 1.5 litres of water and the black pepper and bring to the boil on high heat. Skim, lower the heat and simmer, lid ajar, for 50 minutes until the meat pulls apart easily with a fork. Don\'t add salt; the meat is already salty. Meanwhile, rinse the rice twice and soak it in cold water (not counted separately).","ar":"ضع الشرائح المجففة في قدر مع ١٫٥ لتر ماء والفلفل الأسود واتركها تغلي على نار عالية. أزل الرغوة، وخفّف النار واتركها تغلي بهدوء والغطاء مفتوح جزئيًا ٥٠ دقيقة حتى يتفتت اللحم بالشوكة بسهولة. لا تضف ملحًا؛ فاللحم مالح أصلًا. في الأثناء اغسل الأرز مرتين وانقعه في ماء بارد (لا يُحسب منفصلًا)."},"time":50,"image":{"src":"/recipes/tabaheg/step-04.webp","alt":"ورقه‌های گوشت خشک در آب‌گوشت قرمز در حال جوشیدن در قابلمه","width":1200,"height":900}},{"n":5,"title":{"fa":"جدا کردن گوشت و پیاز داغ","en":"Separate the meat and fry the onion","ar":"فصل اللحم وتحمير البصل"},"text":{"fa":"گوشت را با کفگیر بیرون بیاورید و آب‌گوشت را صاف کنید؛ باید حدود ۱ لیتر باشد. اگر می‌خواهید، گوشت را با ۱ قاشق روغن ۲ دقیقه روی حرارت متوسط تفت دهید (برخی بلوچ‌ها تفت نمی‌دهند تا طعم اصلی بماند). در قابلمهٔ پلو، ۴ قاشق روغن را روی حرارت متوسط داغ کنید و پیاز را ۸ دقیقه تفت دهید تا کاملاً طلایی شود.","en":"Lift out the meat and strain the broth; you should have about 1 litre. If you like, fry the meat in 1 tbsp oil for 2 minutes on medium heat (some Baluchi cooks skip this to keep the original taste). In the rice pot, heat 4 tbsp oil on medium heat and fry the onion for 8 minutes until fully golden.","ar":"أخرج اللحم وصفِّ المرق؛ يجب أن يكون نحو لتر. إن شئت فحمّر اللحم بملعقة زيت دقيقتين على نار متوسطة (بعض الطهاة البلوش لا يحمّرونه للحفاظ على الطعم الأصلي). في قدر الأرز سخّن ٤ ملاعق زيت على نار متوسطة وحمّر البصل ٨ دقائق حتى يصبح ذهبيًا تمامًا."},"time":10,"image":{"src":"/recipes/tabaheg/step-05.webp","alt":"پیاز داغ طلایی در قابلمه و تکه‌های گوشت پخته در بشقاب","width":1200,"height":900}},{"n":6,"title":{"fa":"پختن برنج در آب‌گوشت","en":"Cook the rice in the broth","ar":"طهي الأرز في المرق"},"text":{"fa":"۷۵۰ میلی‌لیتر آب‌گوشت را روی پیاز بریزید و به جوش بیاورید. آب را بچشید و فقط اگر کم‌نمک بود، نمک بزنید. برنج آبکشیده و گوشت را اضافه کنید و یک بار آرام هم بزنید. روی حرارت متوسط بدون در ۱۵ دقیقه بپزید تا آب کشیده شود و روی برنج سوراخ‌های بخار پیدا شود.","en":"Pour 750 ml of the broth over the onion and bring to the boil. Taste and add salt only if it lacks it. Add the drained rice and the meat and stir once gently. Cook uncovered on medium heat for 15 minutes until the liquid is absorbed and steam holes appear on the surface.","ar":"اسكب ٧٥٠ مل من المرق فوق البصل واتركه يغلي. تذوّقه ولا تضف الملح إلا إذا نقص. أضف الأرز المصفى واللحم وقلّب مرة برفق. اطهُه دون غطاء على نار متوسطة ١٥ دقيقة حتى يُمتص السائل وتظهر ثقوب البخار على السطح."},"time":15,"image":{"src":"/recipes/tabaheg/step-06.webp","alt":"برنج در حال کشیدن آب‌گوشت قرمز با سوراخ‌های بخار در قابلمه","width":1200,"height":900}},{"n":7,"title":{"fa":"دم کشیدن","en":"Steam","ar":"التدميس"},"text":{"fa":"درِ قابلمه را با دم‌کنی یا پارچهٔ تمیز بپوشانید، حرارت را خیلی ملایم کنید و ۳۰ دقیقه دم بگذارید تا دانه‌ها کاملاً نرم و جدا شوند.","en":"Cover the lid with a cloth, turn the heat to very low and steam for 30 minutes until the grains are fully tender and separate.","ar":"غطِّ الغطاء بقماشة نظيفة، وخفّف النار جدًا واتركه يتدمس ٣٠ دقيقة حتى تنضج الحبات تمامًا وتنفصل."},"time":30,"image":{"src":"/recipes/tabaheg/step-07.webp","alt":"قابلمهٔ پلوی تباهگ با در پارچه‌پیچ روی شعلهٔ خیلی ملایم","width":1200,"height":900}}],"tips":{"fa":["نسبت برابر نمک و پودر انار عطر بهتری می‌دهد.","آب‌گوشت اضافه برای آش یا سوپ عالی است.","گوشت خشک‌شده را می‌توان ماه‌ها در جای خشک نگه داشت."],"en":["An equal salt-to-pomegranate ratio gives the best aroma.","Leftover broth is great for soup or ash.","Dried tabaheg keeps for months in a dry place."],"ar":["النسبة المتساوية من الملح والرمان تعطي أفضل نكهة.","المرق المتبقي ممتاز للحساء.","يُحفظ التباهك المجفف شهورًا في مكان جاف."]},"cover":{"src":"/recipes/tabaheg/cover.webp","alt":"دیس پلوی تباهگ با تکه‌های گوشت بره نمک‌سود با انار و پیاز طلایی","width":1600,"height":1200},"serving":{"src":"/recipes/tabaheg/serving.webp","alt":"بشقاب پلوی تباهگ با تکه‌های گوشت نمک‌سود و کاسهٔ ماست کنار آن","width":1200,"height":1500}},{"id":"dmpkht-mash","country":"IR","slugs":{"fa":"دمپخت-ماش","en":"dampokht-mash","ar":"دمبخت-الماش"},"title":{"fa":"دم‌پخت ماش","en":"Mung bean dampokht (one-pot rice with mung beans)","ar":"دمبخت الماش (أرز مطهو مع فاصولياء الماش)"},"summary":{"fa":"برنج و ماش نیم‌پز که با پیازداغ و زردچوبه در یک قابلمه، بدون آبکش، دم می‌کشد.","en":"Rice and part-cooked mung beans cooked together with fried onion and turmeric in one pot, without draining.","ar":"أرز وماش نصف مطهو يُطهيان معًا مع البصل المقلي والكركم في قدر واحدة دون تصفية."},"intro":{"fa":"دم‌پخت ماش غذایی ساده، گیاهی و ارزان است که در شهرهای مختلف ایران با روش‌های گوناگون پخته می‌شود. نکتهٔ اصلی این است که ماش فقط نیم‌پز شود، چون بقیهٔ پختش همراه برنج است.","en":"Mung bean dampokht is a simple, inexpensive vegetarian dish cooked in many ways across Iran. The key is to only half-cook the mung beans, because they finish cooking with the rice.","ar":"دمبخت الماش طبق نباتي بسيط وزهيد يُطهى بطرق مختلفة في مدن إيران. والأهم أن يُطهى الماش نصف طهي فقط لأنه يكمل نضجه مع الأرز."},"seoTitle":{"fa":"دم‌پخت ماش؛ طرز تهیه آسان و گیاهی در یک قابلمه","en":"Mung Bean Dampokht Recipe (One-Pot Persian Rice)","ar":"دمبخت الماش: طريقة عمل أرز إيراني سهل مع الماش"},"seoDescription":{"fa":"طرز تهیه دم‌پخت ماش برای ۴ نفر: برنج و ماش نیم‌پز با پیازداغ و زردچوبه که در یک قابلمه و بدون آبکش دم می‌کشد؛ آسان و گیاهی، حدود ۲.۵ ساعت با خیساندن.","en":"Easy vegan Persian one-pot rice for 4: rice and part-cooked mung beans with fried onion and turmeric, cooked without draining. About 2.5 h incl. soaking.","ar":"طريقة عمل دمبخت الماش لأربعة أشخاص: أرز وماش نصف مطهو مع البصل المقلي والكركم في قدر واحدة دون تصفية؛ طبق نباتي سهل يستغرق نحو ساعتين ونصف مع النقع."},"servings":4,"prep":15,"cook":73,"rest":60,"total":148,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"برنج ایرانی دانه‌بلند","en":"Persian long-grain rice","ar":"أرز إيراني طويل الحبة"},"amount":"2","unit":"پیمانه","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"حدود ۴۰۰ گرم","en":"About 400 g","ar":"نحو ٤٠٠ غرام"}},{"name":{"fa":"ماش","en":"Mung beans","ar":"ماش"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"حدود ۲۰۰ گرم","en":"About 200 g","ar":"نحو ٢٠٠ غرام"}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"متوسط","en":"Medium","ar":"متوسطة"}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای خیساندن برنج","en":"Salt for soaking the rice","ar":"ملح لنقع الأرز"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"با آب خیساندن دور ریخته می‌شود.","en":"Drained away with the soaking water.","ar":"يُصرف مع ماء النقع."}},{"name":{"fa":"نمک برای پخت","en":"Salt for cooking","ar":"ملح للطهي"},"amount":"1.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"به ذائقه؛ از کم شروع کنید.","en":"To taste; start low.","ar":"حسب الذوق؛ ابدأ بالقليل."}},{"name":{"fa":"آب سرد برای پخت ماش","en":"Cold water for the mung beans","ar":"ماء بارد لطهي الماش"},"amount":"2","unit":"پیمانه","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب جوش برای دم‌پخت","en":"Boiling water for the rice","ar":"ماء مغلي للأرز"},"amount":"3","unit":"پیمانه","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"معیار: یک بند انگشت روی مواد","en":"Guide: one knuckle above the ingredients","ar":"المعيار: عقلة إصبع فوق المكونات"}}],"steps":[{"n":1,"title":{"fa":"پاک کردن و خیساندن ماش و برنج","en":"Pick over and soak the mung beans and rice","ar":"تنقية الماش والأرز ونقعهما"},"text":{"fa":"۱) ماش را در سینی پهن کنید و سنگ‌ریزه و دانه‌های خراب را جدا کنید. چند بار بشویید و دست‌کم ۱ ساعت (بهتر از شب قبل) در آب خیس کنید؛ اگر طولانی خیس می‌کنید چند بار آبش را عوض کنید.\\n۲) برنج را ۳ تا ۴ بار بشویید و با آب و ۱ قاشق غذاخوری نمک ۳۰ تا ۶۰ دقیقه خیس کنید.","en":"1) Spread the mung beans on a tray and remove any stones or bad beans. Rinse several times and soak in water for at least 1 hour (overnight is better), changing the water a few times if soaking long.\\n2) Rinse the rice 3–4 times and soak 30–60 minutes in water with 1 tbsp salt.","ar":"١) افرد الماش على صينية وأزل الحصى والحبات التالفة. اغسله عدة مرات وانقعه في الماء ساعة على الأقل (والأفضل من الليلة السابقة)، مع تغيير الماء مرات إن طال النقع.\\n٢) اغسل الأرز ٣–٤ مرات وانقعه ٣٠–٦٠ دقيقة في ماء مع ملعقة كبيرة من الملح."},"time":5,"image":{"src":"/recipes/dmpkht-mash/step-01.webp","alt":"سینی ماش سبز در حال پاک کردن کنار کاسهٔ برنج خیس‌خورده","width":1200,"height":900}},{"n":2,"title":{"fa":"خرد کردن پیاز","en":"Chop the onions","ar":"فرم البصل"},"text":{"fa":"۱) پیازها را پوست بگیرید و نگینی ریز خرد کنید.","en":"1) Peel the onions and dice them finely.","ar":"١) قشّر البصل وافرمه مكعبات صغيرة."},"time":10,"image":{"src":"/recipes/dmpkht-mash/step-02.webp","alt":"پیاز نگینی ریز خردشده روی تختهٔ چوبی کنار چاقو","width":1200,"height":900}},{"n":3,"title":{"fa":"نیم‌پز کردن ماش","en":"Part-cook the mung beans","ar":"طهي الماش نصف طهي"},"text":{"fa":"۱) آب ماش را خالی کنید، ماش را با ۲ پیمانه آب سرد در قابلمه بریزید و روی حرارت متوسط بگذارید.\\n۲) ۱۵ تا ۲۰ دقیقه بپزید تا نیم‌نرم شود ولی دانه‌ها باز و له نشوند. بعد آبکش کنید.","en":"1) Drain the mung beans, put them in a pot with 2 cups cold water over medium heat.\\n2) Cook 15–20 minutes until half-soft but not split or mushy. Then drain.","ar":"١) صفِّ الماش وضعه في قدر مع كوبين من الماء البارد على نار متوسطة.\\n٢) اطهه ١٥–٢٠ دقيقة حتى يلين نصف ليونة دون أن يتفتح أو يتهرس. ثم صفِّه."},"time":20,"image":{"src":"/recipes/dmpkht-mash/step-03.webp","alt":"دانه‌های سالم ماش در حال جوشیدن آرام در قابلمهٔ کوچک","width":1200,"height":900}},{"n":4,"title":{"fa":"پیازداغ و تفت ماش","en":"Fry the onion and toss the mung beans","ar":"قلي البصل وتقليب الماش"},"text":{"fa":"۱) هم‌زمان با پخت ماش، ۳ قاشق روغن را در قابلمهٔ نچسب اصلی گرم کنید و پیاز را ۸ تا ۱۰ دقیقه تفت دهید تا طلایی شود.\\n۲) زردچوبه را اضافه کنید و ۳۰ ثانیه هم بزنید.\\n۳) ماش آبکش‌شده را اضافه کنید و ۲ تا ۳ دقیقه آرام هم بزنید تا طعم بگیرد و پوستش موقع پخت جدا نشود.","en":"1) While the mung beans cook, heat 3 tbsp oil in the main non-stick pot and fry the onion 8–10 minutes until golden.\\n2) Add the turmeric and stir 30 seconds.\\n3) Add the drained mung beans and stir gently 2–3 minutes so they take on flavour and their skins do not come off later.","ar":"١) أثناء طهي الماش سخّن ٣ ملاعق زيت في القدر غير اللاصقة الرئيسية واقلِ البصل ٨–١٠ دقائق حتى يذهبّ.\\n٢) أضف الكركم وقلّب ٣٠ ثانية.\\n٣) أضف الماش المصفّى وقلّبه بلطف ٢–٣ دقائق ليكتسب النكهة ولا ينفصل قشره لاحقًا."},"time":13,"image":{"src":"/recipes/dmpkht-mash/step-04.webp","alt":"هم زدن پیاز داغ طلایی با زردچوبه و ماش در قابلمهٔ نچسب","width":1200,"height":900}},{"n":5,"title":{"fa":"افزودن برنج و آب","en":"Add the rice and water","ar":"إضافة الأرز والماء"},"text":{"fa":"۱) آب برنج را کامل خالی کنید و برنج را روی ماش بریزید و آرام مخلوط کنید.\\n۲) آب جوش بریزید تا روی سطح صاف مواد یک بند انگشت آب باشد (حدود ۳ تا ۳٫۵ پیمانه). ۱٫۵ قاشق چای‌خوری نمک بزنید، بچشید و اگر لازم بود بیشتر کنید.\\n۳) بدون در، روی حرارت متوسط رو به زیاد ۸ تا ۱۰ دقیقه بجوشانید تا آب کشیده شود و روی برنج سوراخ‌های کوچک دیده شود. در نگذارید، چون برنج خمیری می‌شود.","en":"1) Drain the rice well, add it to the mung beans and mix gently.\\n2) Pour in boiling water until it sits one knuckle above the levelled ingredients (about 3–3.5 cups). Add 1.5 tsp salt, taste the water and add more if needed.\\n3) Boil uncovered over medium-high heat 8–10 minutes until the water is absorbed and small holes appear on the surface. Do not cover yet or the rice turns mushy.","ar":"١) صفِّ الأرز جيدًا وأضفه إلى الماش واخلط بلطف.\\n٢) اسكب الماء المغلي حتى يعلو المكونات المسواة بعقلة إصبع (نحو ٣–٣٫٥ أكواب). أضف ملعقة ونصف صغيرة من الملح وتذوق الماء وزد إن لزم.\\n٣) اغلِه دون غطاء على نار متوسطة إلى عالية ٨–١٠ دقائق حتى يتشرب الماء وتظهر ثقوب صغيرة على السطح. لا تغطِّه بعد وإلا تعجّن الأرز."},"time":10,"image":{"src":"/recipes/dmpkht-mash/step-05.webp","alt":"برنج و ماش در حال جوشیدن در قابلمهٔ بی‌در با سوراخ‌های کوچک بخار روی سطح","width":1200,"height":900}},{"n":6,"title":{"fa":"دم کشیدن","en":"Steam","ar":"الطهي على البخار"},"text":{"fa":"۱) با دستهٔ قاشق چوبی چند سوراخ بزنید. در را با دم‌کنی بپوشانید و حرارت را خیلی کم کنید.\\n۲) ۳۵ تا ۴۰ دقیقه دم بگذارید. اگر ته قابلمه خشک شد، ۲ قاشق آب جوش از کنار بریزید. سپس آرام در دیس بکشید.","en":"1) Poke a few holes with a wooden spoon handle. Cover with a cloth-wrapped lid and turn the heat very low.\\n2) Steam 35–40 minutes. If the base looks dry, add 2 tbsp boiling water down the side. Then gently spoon onto a platter.","ar":"١) اثقب بضعة ثقوب بمقبض ملعقة خشبية. غطِّ القدر بغطاء ملفوف بقماش واخفض النار جدًا.\\n٢) اتركه ٣٥–٤٠ دقيقة. إن جفّ القاع أضف ملعقتين من الماء المغلي من الجانب. ثم اغرفه بلطف إلى طبق."},"time":40,"image":{"src":"/recipes/dmpkht-mash/step-06.webp","alt":"دیس دم‌پخت ماش با برنج زردرنگ و دانه‌های سبز ماش","width":1200,"height":900}}],"tips":{"fa":["آب را زیاد نریزید؛ معیار یک بند انگشت روی مواد است.","پیازداغ عطر غذا را می‌سازد.","تفت دادن ماش با پیاز جلوی جدا شدن پوستش را می‌گیرد (کجارو).","خیساندن طولانی و عوض کردن آب، نفخ ماش را کم می‌کند (کجارو)."],"en":["Do not add too much water; one knuckle above the ingredients is the guide.","The fried onion gives the dish its aroma.","Tossing the mung beans with the onion stops their skins coming off (Kojaro).","Long soaking with water changes reduces bloating from mung beans (Kojaro)."],"ar":["لا تكثر الماء؛ المعيار عقلة إصبع فوق المكونات.","البصل المقلي يمنح الطبق عطره.","تقليب الماش مع البصل يمنع انفصال قشره.","النقع الطويل مع تغيير الماء يقلل الانتفاخ."]},"cover":{"src":"/recipes/dmpkht-mash/cover.webp","alt":"قابلمهٔ دم‌پخت ماش با برنج زرد و دانه‌های سبز ماش کنار کاسهٔ ماست","width":1600,"height":1200},"serving":{"src":"/recipes/dmpkht-mash/serving.webp","alt":"بشقاب دم‌پخت ماش با ماست و سبزی تازه","width":1200,"height":1500}},{"id":"khwrsht-lwbya-qrmz","country":"IR","slugs":{"fa":"خورشت-لوبیا-قرمز","en":"khoresh-loobia-ghermez","ar":"مرق-الفاصولياء-الحمراء"},"title":{"fa":"خورشت لوبیا قرمز","en":"Red kidney bean stew (khoresh)","ar":"مرق الفاصولياء الحمراء"},"summary":{"fa":"خورشتی ساده و مقوی از گوشت گوسفند و لوبیا قرمز در سس رب گوجه که آرام روی حرارت ملایم جا می‌افتد.","en":"A simple, hearty stew of lamb and red kidney beans in a tomato-paste sauce, slowly simmered until rich.","ar":"مرق بسيط ومغذٍّ من لحم الضأن والفاصولياء الحمراء في صلصة معجون الطماطم، يُطهى ببطء على نار هادئة."},"intro":{"fa":"خورش یا خوراک لوبیا با گوشت در بسیاری از نقاط ایران پخته می‌شود و در آذربایجان، به‌ویژه ارومیه، غذایی سنتی است. لوبیا از شب قبل خیس می‌خورد و جدا نیم‌پز می‌شود تا هم‌زمان با گوشت نرم شود و له نشود.","en":"Bean stew with meat is cooked across Iran and is a traditional dish in Azerbaijan, especially Urmia. The beans are soaked overnight and part-cooked separately so they soften together with the meat without turning mushy.","ar":"يُطهى مرق الفاصولياء باللحم في مناطق كثيرة من إيران، وهو طبق تقليدي في أذربيجان ولا سيما أرومية. تُنقع الفاصولياء من الليلة السابقة وتُسلق وحدها جزئيًا لتنضج مع اللحم دون أن تتهرّس."},"seoTitle":{"fa":"خورشت لوبیا قرمز؛ طرز تهیه آسان با گوشت گوسفند","en":"Red Kidney Bean Stew Recipe (Khoresh Loobia Ghermez)","ar":"مرق الفاصولياء الحمراء الإيراني: طريقة عمل سهلة باللحم"},"seoDescription":{"fa":"طرز تهیه خورشت لوبیا قرمز برای ۴ نفر: گوشت گوسفند و لوبیا قرمز در سس رب گوجه که آرام جا می‌افتد؛ آسان، لوبیا از شب قبل خیس می‌خورد، با برنج یا نان.","en":"Easy Persian stew for 4: lamb and red kidney beans slowly simmered in a tomato-paste sauce. Beans soak overnight; about 2 h 15 min active. Serve with rice.","ar":"طريقة عمل مرق الفاصولياء الحمراء لأربعة أشخاص: لحم ضأن وفاصولياء حمراء في صلصة معجون الطماطم تُطهى ببطء؛ سهل، تُنقع الفاصولياء ليلة، ويُقدَّم مع الأرز."},"servings":4,"prep":20,"cook":115,"rest":490,"total":625,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"لوبیا قرمز خشک","en":"Dried red kidney beans","ar":"فاصولياء حمراء مجففة"},"amount":"2","unit":"پیمانه","optional":false,"group":{"fa":"لوبیا","en":"Beans","ar":"الفاصولياء"},"note":{"fa":"حدود ۴۰۰ گرم؛ یا ۲ قوطی لوبیای کنسروی آبکش‌شده","en":"About 400 g; or 2 cans of drained canned beans","ar":"نحو ٤٠٠ غرام؛ أو علبتان من الفاصولياء المعلبة المصفاة"}},{"name":{"fa":"آب برای پخت لوبیا","en":"Water for cooking the beans","ar":"ماء لسلق الفاصولياء"},"amount":"4","unit":"پیمانه","optional":false,"group":{"fa":"لوبیا","en":"Beans","ar":"الفاصولياء"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"گوشت گوسفند خورشتی","en":"Lamb stewing meat","ar":"لحم ضأن للمرق"},"amount":"400","unit":"گرم","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"مکعب‌های ۳ سانتی؛ گوساله هم می‌شود","en":"3 cm cubes; beef also works","ar":"مكعبات ٣ سم؛ ويصلح لحم العجل"}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"متوسط","en":"Medium","ar":"متوسطة"}},{"name":{"fa":"رب گوجه‌فرنگی","en":"Tomato paste","ar":"معجون الطماطم"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب جوش برای خورشت","en":"Boiling water for the stew","ar":"ماء مغلي للمرق"},"amount":"3","unit":"پیمانه","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"آخر پخت","en":"At the end of cooking","ar":"في آخر الطهي"}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"دارچین","en":"Cinnamon","ar":"قرفة"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":true,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آبلیمو","en":"Lemon juice","ar":"عصير ليمون"},"amount":"1","unit":"قاشق غذاخوری","optional":true,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"پاک کردن و خیساندن لوبیا (شب قبل)","en":"Sort and soak the beans (night before)","ar":"تنقية الفاصولياء ونقعها (الليلة السابقة)"},"text":{"fa":"۱) لوبیا را روی سینی پهن کنید و سنگ‌ریزه و دانه‌های خراب را جدا کنید. ۲ تا ۳ بار با آب سرد بشویید.\\n۲) در کاسه‌ای با آب فراوان دست‌کم ۸ ساعت خیس کنید و در این مدت ۲ بار آبش را عوض کنید.","en":"1) Spread the beans on a tray and pick out any grit or bad beans. Rinse 2–3 times in cold water.\\n2) Soak in plenty of water for at least 8 hours, changing the water twice.","ar":"١) افرد الفاصولياء على صينية وأزل الحصى والحبات التالفة. اغسلها ٢–٣ مرات بالماء البارد.\\n٢) انقعها في ماء وفير ٨ ساعات على الأقل وغيّر الماء مرتين خلالها."},"time":10,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-01.webp","alt":"لوبیا قرمز خیس‌خورده در کاسهٔ شیشه‌ای آب و ظرف کوچک سنگ‌ریزه‌های جداشده","width":1200,"height":900}},{"n":2,"title":{"fa":"نیم‌پز کردن لوبیا","en":"Part-cook the beans","ar":"سلق الفاصولياء جزئيًا"},"text":{"fa":"۱) آب لوبیا را دور بریزید. لوبیا را در قابلمهٔ جدا بریزید و ۴ پیمانه آب سرد رویش بریزید.\\n۲) روی حرارت زیاد بگذارید تا جوش بیاید، بعد حرارت را کم کنید و با در نیمه‌باز ۴۰ تا ۴۵ دقیقه بپزید تا لوبیا نیم‌نرم شود. در این مرحله نمک نزنید. اگر آبش کم شد آب جوش اضافه کنید.\\n۳) در همین فاصله مراحل ۳ تا ۵ را انجام دهید.","en":"1) Drain the beans, put them in a separate pot and cover with 4 cups cold water.\\n2) Bring to the boil on high heat, then lower and cook half-covered 40–45 minutes until half-tender. Do not salt yet. Top up with boiling water if needed.\\n3) Meanwhile, do steps 3 to 5.","ar":"١) صفِّ الفاصولياء وضعها في قدر منفصلة واسكب فوقها ٤ أكواب ماء بارد.\\n٢) اغلها على نار عالية ثم اخفض النار واطهها نصف مغطاة ٤٠–٤٥ دقيقة حتى تلين نصف ليونة. لا تضف الملح الآن، وأضف ماءً مغليًا إن قلّ الماء.\\n٣) في هذه الأثناء نفّذ الخطوات من ٣ إلى ٥."},"time":45,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-02.webp","alt":"لوبیا قرمز در حال جوشیدن آرام در قابلمهٔ نیمه‌سرپوشیده روی شعلهٔ کم","width":1200,"height":900}},{"n":3,"title":{"fa":"خرد کردن پیاز و گوشت","en":"Chop the onion and meat","ar":"تقطيع البصل واللحم"},"text":{"fa":"۱) پیازها را پوست بگیرید و نگینی ریز خرد کنید.\\n۲) چربی و پی اضافی گوشت را جدا کنید و گوشت را مکعب‌های ۳ سانتی ببرید.","en":"1) Peel the onions and chop finely.\\n2) Trim excess fat and sinew from the meat and cut into 3 cm cubes.","ar":"١) قشّر البصل وقطّعه مكعبات صغيرة.\\n٢) أزل الدهن والعروق الزائدة من اللحم وقطّعه مكعبات ٣ سم."},"time":10,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-03.webp","alt":"پیاز ریز خردشده و مکعب‌های گوشت روی تختهٔ چوبی کنار چاقو","width":1200,"height":900}},{"n":4,"title":{"fa":"پیازداغ و تفت گوشت","en":"Fry the onion and brown the meat","ar":"قلي البصل وتحمير اللحم"},"text":{"fa":"۱) روغن را در قابلمهٔ خورشت روی حرارت متوسط گرم کنید. پیاز را ۱۰ تا ۱۲ دقیقه تفت دهید تا طلایی شود.\\n۲) گوشت و زردچوبه را اضافه کنید و ۸ تا ۱۰ دقیقه هم بزنید تا رنگ گوشت از هر طرف تغییر کند.","en":"1) Heat the oil in the stew pot over medium heat. Fry the onion 10–12 minutes until golden.\\n2) Add the meat and turmeric and stir 8–10 minutes until the meat has changed colour on all sides.","ar":"١) سخّن الزيت في قدر المرق على نار متوسطة. اقلِ البصل ١٠–١٢ دقيقة حتى يذهبّ.\\n٢) أضف اللحم والكركم وقلّب ٨–١٠ دقائق حتى يتغير لون اللحم من كل الجهات."},"time":22,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-04.webp","alt":"مکعب‌های گوشت در حال تفت با پیاز طلایی و زردچوبه در قابلمه","width":1200,"height":900}},{"n":5,"title":{"fa":"تفت رب و پخت گوشت","en":"Fry the paste and simmer the meat","ar":"قلي المعجون وطهي اللحم"},"text":{"fa":"۱) رب گوجه را اضافه کنید و ۲ تا ۳ دقیقه تفت دهید تا رنگش تیره‌تر و بوی خامی‌اش گرفته شود.\\n۲) ۳ پیمانه آب جوش بریزید، بگذارید جوش بیاید، حرارت را کم کنید و با در بسته حدود ۶۰ دقیقه بپزید تا گوشت تقریباً نرم شود. هر ۱۵ دقیقه یک بار هم بزنید.","en":"1) Add the tomato paste and fry 2–3 minutes until it darkens and loses its raw smell.\\n2) Pour in 3 cups boiling water, bring back to the boil, lower the heat and simmer covered about 60 minutes until the meat is nearly tender. Stir every 15 minutes.","ar":"١) أضف معجون الطماطم وقلّبه ٢–٣ دقائق حتى يغمق لونه وتذهب رائحته النيئة.\\n٢) اسكب ٣ أكواب من الماء المغلي، واتركه يغلي ثم اخفض النار واطهه مغطًى نحو ٦٠ دقيقة حتى يكاد اللحم ينضج. قلّب كل ١٥ دقيقة."},"time":63,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-05.webp","alt":"گوشت در حال پخت در سس قرمز رب گوجه زیر درِ نیمه‌باز قابلمه","width":1200,"height":900}},{"n":6,"title":{"fa":"افزودن لوبیا","en":"Add the beans","ar":"إضافة الفاصولياء"},"text":{"fa":"۱) لوبیای نیم‌پز را آبکش کنید و به خورشت اضافه کنید.\\n۲) با در نیمه‌باز ۲۰ تا ۲۵ دقیقه روی حرارت ملایم بپزید تا لوبیا کاملاً نرم و خورشت غلیظ شود. اگر خیلی غلیظ شد نصف پیمانه آب جوش اضافه کنید.","en":"1) Drain the part-cooked beans and add them to the stew.\\n2) Simmer half-covered on low heat 20–25 minutes until the beans are fully tender and the stew thickens. Add \xbd cup boiling water if it gets too thick.","ar":"١) صفِّ الفاصولياء نصف المسلوقة وأضفها إلى المرق.\\n٢) اطهه نصف مغطًى على نار هادئة ٢٠–٢٥ دقيقة حتى تنضج الفاصولياء تمامًا ويثخن المرق. أضف نصف كوب ماء مغلي إن ثخن كثيرًا."},"time":25,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-06.webp","alt":"هم زدن لوبیا قرمز در خورشت غلیظ گوشت و گوجه با قاشق چوبی","width":1200,"height":900}},{"n":7,"title":{"fa":"تنظیم مزه و استراحت","en":"Season and rest","ar":"ضبط النكهة والإراحة"},"text":{"fa":"۱) نمک، فلفل سیاه و در صورت تمایل دارچین و آبلیمو را اضافه کنید و ۵ دقیقه دیگر بپزید. بچشید و مزه را تنظیم کنید.\\n۲) حرارت را خاموش کنید و ۱۰ دقیقه با در بسته بگذارید جا بیفتد.","en":"1) Add salt, black pepper and, if you like, cinnamon and lemon juice; cook 5 more minutes. Taste and adjust.\\n2) Turn off the heat and leave covered 10 minutes to settle.","ar":"١) أضف الملح والفلفل الأسود، والقرفة وعصير الليمون إن شئت، واطهه ٥ دقائق أخرى. تذوّق واضبط النكهة.\\n٢) أطفئ النار واتركه مغطًى ١٠ دقائق ليستقر."},"time":5,"image":{"src":"/recipes/khwrsht-lwbya-qrmz/step-07.webp","alt":"خورشت لوبیا قرمز آماده با سس براق در کاسهٔ سرامیکی کنار برنج سفید","width":1200,"height":900}}],"tips":{"fa":["لوبیا را جدا بپزید و بعد اضافه کنید تا له نشود.","رب را خوب تفت دهید تا بوی خامی آن گرفته شود.","به لوبیا در حین پخت اولیه نمک نزنید؛ نمک را آخر کار اضافه کنید (باشگاه خبرنگاران جوان).","اگر وقت ندارید، لوبیای کنسروی آبکش‌شده را در مرحلهٔ ۶ اضافه کنید و ۱۵ دقیقه بپزید (ایران‌کوک)."],"en":["Cook the beans separately and add later so they do not turn mushy.","Fry the tomato paste well to remove its raw taste.","Do not salt the beans during the first cooking; add salt at the end (YJC).","Short on time: add drained canned beans at step 6 and cook 15 minutes (Irancook)."],"ar":["اسلق الفاصولياء وحدها وأضفها لاحقًا كي لا تتهرّس.","اقلِ معجون الطماطم جيدًا لتذهب نكهته النيئة.","لا تملّح الفاصولياء أثناء السلق الأول، وأضف الملح في النهاية.","إن ضاق الوقت فأضف الفاصولياء المعلبة المصفاة في الخطوة ٦ واطهها ١٥ دقيقة."]},"cover":{"src":"/recipes/khwrsht-lwbya-qrmz/cover.webp","alt":"کاسهٔ خورشت لوبیا قرمز با گوشت در سس گوجهٔ براق کنار بشقاب برنج سفید و سبزی","width":1600,"height":1200},"serving":{"src":"/recipes/khwrsht-lwbya-qrmz/serving.webp","alt":"خورشت لوبیا قرمز روی برنج سفید در بشقاب با سبزی تازه و پیاز","width":1200,"height":1500}},{"id":"mrgh-lymwyy","country":"IR","slugs":{"fa":"مرغ-لیمویی","en":"morgh-limoo","ar":"دجاج-بالليمون"},"title":{"fa":"مرغ لیمویی","en":"Persian lemon chicken","ar":"دجاج بالليمون على الطريقة الإيرانية"},"summary":{"fa":"مرغ نرم و آبدار که با پیاز، سیر، زردچوبه و کمی زعفران پخته می‌شود و آبلیموی تازه در دو مرحله به آن طعم ترش‌ملایم می‌دهد.","en":"Tender chicken simmered with onion, garlic, turmeric and a little saffron, with fresh lemon juice added in two stages for a gentle sourness.","ar":"دجاج طريّ يُطهى مع البصل والثوم والكركم وقليل من الزعفران، ويُضاف إليه عصير الليمون الطازج على مرحلتين ليمنحه حموضة لطيفة."},"intro":{"fa":"مرغ لیمویی از خوراک‌های خانگی رایج ایرانی است و شکل نزدیک به \xabمرغ زعفرانی\xbb دارد: پیاز طلایی، تفت کوتاه مرغ، کمی آب و حرارت ملایم. در منابع ایرانی آبلیمو معمولاً در پایان پخت اضافه می‌شود تا عطرش بماند و تلخ نشود؛ در این دستور نیمی از آن را وسط کار و نیم دیگر را آخر کار می‌ریزیم.","en":"Lemon chicken is a common Iranian home-style dish, close to \\"saffron chicken\\": golden onion, a short browning of the chicken, a little water and gentle heat. Iranian sources usually add lemon juice near the end so its aroma stays fresh and it does not turn bitter; here half goes in midway and half at the end.","ar":"الدجاج بالليمون من الأطباق المنزلية الشائعة في إيران، وهو قريب من \xabالدجاج بالزعفران\xbb: بصل ذهبي، وتحمير قصير للدجاج، وقليل من الماء، ونار هادئة. وتضيف المصادر الإيرانية عصير الليمون عادةً قرب نهاية الطهي ليبقى عطره ولا يصير مرًّا؛ وهنا يُضاف نصفه في منتصف الطهي ونصفه في آخره."},"seoTitle":{"fa":"مرغ لیمویی؛ طرز تهیه آسان با آبلیمو و زعفران","en":"Persian Lemon Chicken Recipe (Morgh Limoo)","ar":"دجاج بالليمون على الطريقة الإيرانية: طريقة عمل سهلة"},"seoDescription":{"fa":"طرز تهیه مرغ لیمویی برای ۴ نفر: ران مرغ بی‌استخوان با پیاز، سیر، زردچوبه و کمی زعفران که آبلیموی تازه در دو مرحله به آن اضافه می‌شود؛ آسان، حدود ۶۵ دقیقه.","en":"Easy Persian lemon chicken for 4: boneless thighs simmered with onion, garlic, turmeric and saffron, fresh lemon juice added in two stages. About 65 min.","ar":"طريقة عمل الدجاج بالليمون على الطريقة الإيرانية لأربعة أشخاص: أفخاذ دجاج مع البصل والثوم والكركم والزعفران وعصير ليمون طازج على مرحلتين؛ سهل، نحو ٦٥ دقيقة."},"servings":4,"prep":15,"cook":49,"rest":0,"total":64,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"ران مرغ بی‌استخوان","en":"Boneless chicken thigh","ar":"أفخاذ دجاج منزوعة العظم"},"amount":"600","unit":"گرم","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"یا سینهٔ مرغ؛ سینه زودتر می‌پزد و ممکن است خشک شود.","en":"Or chicken breast; breast cooks faster and can dry out.","ar":"أو صدر دجاج؛ الصدر ينضج أسرع وقد يجف."}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"متوسط (حدود ۱۵۰ گرم)، نگینی ریز","en":"Medium (about 150 g), finely diced","ar":"متوسطة (نحو ١٥٠ غرامًا)، مقطعة مكعبات صغيرة"}},{"name":{"fa":"سیر","en":"Garlic","ar":"ثوم"},"amount":"3","unit":"حبه","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"له یا ریز خردشده","en":"Crushed or finely chopped","ar":"مهروس أو مفروم ناعمًا"}},{"name":{"fa":"آبلیموی تازه","en":"Fresh lemon juice","ar":"عصير ليمون طازج"},"amount":"4","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"حدود ۲ لیموترش؛ در دو نوبت مصرف می‌شود.","en":"About 2 lemons; used in two stages.","ar":"من نحو ليمونتين؛ يُستعمل على دفعتين."}},{"name":{"fa":"آب جوش","en":"Boiling water","ar":"ماء مغلي"},"amount":"120","unit":"میلی‌لیتر","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"نصف پیمانه","en":"Half a cup","ar":"نصف كوب"}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زعفران دم‌کرده","en":"Brewed saffron","ar":"زعفران منقوع"},"amount":"2","unit":"قاشق غذاخوری","optional":true,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"⅛ قاشق چای‌خوری زعفران سابیده با ۲ قاشق غذاخوری آب داغ","en":"⅛ tsp ground saffron steeped in 2 tbsp hot water","ar":"⅛ ملعقة صغيرة زعفران مطحون منقوع في ملعقتين كبيرتين ماء ساخن"}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"به ذائقه تنظیم کنید.","en":"Adjust to taste.","ar":"عدّله حسب الذوق."}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"تازه آسیاب‌شده","en":"Freshly ground","ar":"مطحون طازجًا"}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مواد","en":"Prep the ingredients","ar":"تحضير المكونات"},"text":{"fa":"۱) زعفران سابیده را در یک فنجان کوچک بریزید، ۲ قاشق غذاخوری آب داغ رویش بریزید، درش را بگذارید و ۱۰ دقیقه کنار بگذارید.\\n۲) دست‌ها را بشویید. چربی و پوست اضافهٔ مرغ را جدا کنید، مرغ را به تکه‌های ۴ تا ۵ سانتی هم‌اندازه ببرید و با دستمال کاغذی خشک کنید. بعد دست‌ها، چاقو و تخته را با آب گرم و مایع بشویید.\\n۳) پیاز را پوست بگیرید و نگینی ریز خرد کنید. سیر را پوست بگیرید و له کنید.\\n۴) لیموها را بشویید، نصف کنید و آب بگیرید؛ هسته‌ها را جدا کنید. ۴ قاشق غذاخوری آبلیمو را در دو کاسهٔ کوچک (هر کدام ۲ قاشق) تقسیم کنید.","en":"1) Put the ground saffron in a small cup, pour 2 tbsp hot water over it, cover and set aside for 10 minutes.\\n2) Wash your hands. Trim excess fat and skin from the chicken, cut it into even 4–5 cm pieces and pat dry with paper towels. Then wash hands, knife and board with hot soapy water.\\n3) Peel and finely dice the onion. Peel and crush the garlic.\\n4) Wash, halve and juice the lemons; remove the seeds. Divide the 4 tbsp juice between two small bowls (2 tbsp each).","ar":"١) ضع الزعفران المطحون في فنجان صغير، واسكب فوقه ملعقتين كبيرتين من الماء الساخن، وغطّه واتركه ١٠ دقائق.\\n٢) اغسل يديك. أزل الدهن والجلد الزائدين من الدجاج، وقطّعه قطعًا متساوية بطول ٤–٥ سم، وجففه بمناديل ورقية. ثم اغسل يديك والسكين واللوح بالماء الساخن والصابون.\\n٣) قشّر البصل وقطّعه مكعبات صغيرة. قشّر الثوم واهرسه.\\n٤) اغسل الليمون واقطعه نصفين واعصره وأزل البذور. قسّم الملاعق الأربع من العصير في وعاءين صغيرين (ملعقتان في كل منهما)."},"time":15,"image":{"src":"/recipes/mrgh-lymwyy/step-01.webp","alt":"تکه‌های مرغ خام، پیاز خردشده، سیر له‌شده، لیموی نصف‌شده، آب زعفران و زردچوبه روی تخته","width":1200,"height":900}},{"n":2,"title":{"fa":"تفت دادن پیاز","en":"Saut\xe9 the onion","ar":"تشويح البصل"},"text":{"fa":"۱) تابهٔ درب‌دار یا قابلمهٔ پهن را روی حرارت متوسط بگذارید و ۲ قاشق غذاخوری روغن بریزید.\\n۲) پیاز را اضافه کنید و ۶ تا ۸ دقیقه هر یک دقیقه هم بزنید تا نرم و طلایی روشن شود؛ اگر لبه‌ها زود تیره شد حرارت را کمی کم کنید.","en":"1) Set a lidded frying pan or wide pot over medium heat and add 2 tbsp oil.\\n2) Add the onion and cook 6–8 minutes, stirring every minute, until soft and light golden; lower the heat a little if the edges darken fast.","ar":"١) ضع مقلاة ذات غطاء أو قدرًا عريضة على نار متوسطة وأضف ملعقتين كبيرتين من الزيت.\\n٢) أضف البصل واطهه ٦–٨ دقائق مع التقليب كل دقيقة حتى يلين ويصير ذهبيًا فاتحًا؛ اخفض النار قليلًا إن اسودّت الأطراف بسرعة."},"time":8,"image":{"src":"/recipes/mrgh-lymwyy/step-02.webp","alt":"پیاز خردشدهٔ نرم و طلایی در روغن داخل تابه با قاشق چوبی","width":1200,"height":900}},{"n":3,"title":{"fa":"تفت دادن مرغ","en":"Brown the chicken","ar":"تحمير الدجاج"},"text":{"fa":"۱) تکه‌های مرغ را در یک لایه در تابه بچینید و زردچوبه را رویشان بپاشید.\\n۲) ۸ تا ۱۰ دقیقه تفت دهید و هر ۲ دقیقه تکه‌ها را برگردانید تا همهٔ طرف‌ها سفید و کمی طلایی شوند. مرغ در این مرحله هنوز کامل نپخته است.","en":"1) Lay the chicken pieces in the pan in a single layer and sprinkle with the turmeric.\\n2) Cook 8–10 minutes, turning every 2 minutes, until all sides are white and lightly golden. The chicken is not cooked through yet.","ar":"١) رتّب قطع الدجاج في المقلاة في طبقة واحدة ورشّ فوقها الكركم.\\n٢) حمّرها ٨–١٠ دقائق مع قلبها كل دقيقتين حتى تبيضّ جميع جوانبها وتتحمّر قليلًا. لم ينضج الدجاج كليًا بعد."},"time":10,"image":{"src":"/recipes/mrgh-lymwyy/step-03.webp","alt":"تکه‌های مرغ زرد با زردچوبه و کمی طلایی میان پیاز در تابه","width":1200,"height":900}},{"n":4,"title":{"fa":"سیر، زعفران و نیمی از آبلیمو","en":"Garlic, saffron and half the lemon juice","ar":"الثوم والزعفران ونصف عصير الليمون"},"text":{"fa":"۱) سیر را اضافه کنید و فقط ۳۰ ثانیه هم بزنید تا بویش بلند شود؛ نگذارید قهوه‌ای شود.\\n۲) زعفران دم‌کرده، کاسهٔ اول آبلیمو (۲ قاشق) و نمک را اضافه کنید و یک بار هم بزنید.","en":"1) Add the garlic and stir for only 30 seconds until fragrant; do not let it brown.\\n2) Add the brewed saffron, the first bowl of lemon juice (2 tbsp) and the salt, and stir once.","ar":"١) أضف الثوم وقلّبه ٣٠ ثانية فقط حتى تفوح رائحته؛ لا تتركه يتحمّر.\\n٢) أضف الزعفران المنقوع والوعاء الأول من عصير الليمون (ملعقتان) والملح، وقلّب مرة واحدة."},"time":1,"image":{"src":"/recipes/mrgh-lymwyy/step-04.webp","alt":"هم زدن آب زعفران و آبلیمو با مرغ و سیر له‌شده در تابه","width":1200,"height":900}},{"n":5,"title":{"fa":"پخت با درِ بسته","en":"Simmer covered","ar":"الطهي والغطاء مغلق"},"text":{"fa":"۱) نصف پیمانه (۱۲۰ میلی‌لیتر) آب جوش را روی مرغ بریزید، صبر کنید یک جوش بزند و حرارت را کم کنید.\\n۲) در تابه را بگذارید و ۲۵ تا ۳۰ دقیقه بپزید. وسط کار یک بار تکه‌ها را برگردانید و اگر آب تمام شده بود ۲ تا ۳ قاشق آب جوش اضافه کنید.\\n۳) برای اطمینان، کلفت‌ترین تکه را نصف کنید: داخلش نباید صورتی باشد و آبش باید شفاف باشد (دمای مرکز حدود ۷۴ درجهٔ سانتی‌گراد).","en":"1) Pour \xbd cup (120 ml) boiling water over the chicken, let it come to a bubble, then turn the heat to low.\\n2) Cover and cook 25–30 minutes. Turn the pieces once halfway and add 2–3 tbsp boiling water if the liquid has run dry.\\n3) To check, cut the thickest piece in half: it should not be pink inside and the juices should run clear (about 74\xb0C in the centre).","ar":"١) اسكب نصف كوب (١٢٠ مل) من الماء المغلي فوق الدجاج، واتركه يغلي غليانًا خفيفًا ثم اخفض النار.\\n٢) غطِّ المقلاة واطهه ٢٥–٣٠ دقيقة. اقلب القطع مرة في المنتصف وأضف ٢–٣ ملاعق من الماء المغلي إن جفّ السائل.\\n٣) للتأكد، اقطع أسمك قطعة نصفين: يجب ألا يكون داخلها ورديًا وأن تكون عصارتها صافية (نحو ٧٤ درجة مئوية في الوسط)."},"time":25,"image":{"src":"/recipes/mrgh-lymwyy/step-05.webp","alt":"مرغ در حال جوشیدن آرام در سس زعفرانی رقیق زیر درِ نیمه‌باز تابه","width":1200,"height":900}},{"n":6,"title":{"fa":"آبلیموی دوم و غلیظ کردن سس","en":"Second lemon juice and reduce","ar":"العصير الثاني وتكثيف الصلصة"},"text":{"fa":"۱) در را بردارید، کاسهٔ دوم آبلیمو و فلفل سیاه را اضافه کنید.\\n۲) ۳ دقیقه بدون در بپزید تا سس کمی غلیظ شود و تکه‌ها براق شوند. نمک را بچشید و اگر لازم بود کمی اضافه کنید.\\n۳) حرارت را خاموش کنید و ۲ دقیقه صبر کنید، بعد سرو کنید.","en":"1) Remove the lid and add the second bowl of lemon juice and the black pepper.\\n2) Cook uncovered for 3 minutes until the sauce thickens slightly and the pieces look glossy. Taste and add a little salt if needed.\\n3) Turn off the heat, wait 2 minutes, then serve.","ar":"١) ارفع الغطاء وأضف الوعاء الثاني من عصير الليمون والفلفل الأسود.\\n٢) اطهه ٣ دقائق دون غطاء حتى تتكاثف الصلصة قليلًا وتلمع القطع. تذوّق وأضف قليلًا من الملح إن لزم.\\n٣) أطفئ النار وانتظر دقيقتين ثم قدّمه."},"time":5,"image":{"src":"/recipes/mrgh-lymwyy/step-06.webp","alt":"مرغ لیمویی آماده با سس غلیظ و براق طلایی در تابه و لیموی نصف‌شده کنارش","width":1200,"height":900}}],"tips":{"fa":["آبلیمو را دو مرحله‌ای بریزید؛ نیمه دوم را آخر کار اضافه کنید تا عطرش بماند.","حرارت ملایم مانع خشک شدن مرغ می‌شود.","سیر را نسوزانید؛ سیر سوخته تلخ است.","اگر پوست لیمو رنده می‌کنید فقط قسمت زرد را بگیرید؛ قسمت سفید تلخ است."],"en":["Add the lemon juice in two stages; the second half at the end keeps its aroma.","Gentle heat keeps the chicken from drying out.","Do not burn the garlic; burnt garlic is bitter.","If you add lemon zest, grate only the yellow part; the white pith is bitter."],"ar":["أضف عصير الليمون على مرحلتين؛ النصف الثاني في النهاية يحفظ عطره.","النار الهادئة تمنع جفاف الدجاج.","لا تحرق الثوم؛ فالثوم المحروق مرّ.","إن أضفت برش الليمون فخذ الجزء الأصفر فقط؛ فاللب الأبيض مرّ."]},"cover":{"src":"/recipes/mrgh-lymwyy/cover.webp","alt":"ظرف مرغ لیمویی با تکه‌های مرغ زعفرانی در سس لیمو، پیاز نرم و برش لیمو کنار پلو","width":1600,"height":1200},"serving":{"src":"/recipes/mrgh-lymwyy/serving.webp","alt":"بشقاب مرغ لیمویی روی برنج سفید با برش لیمو، سبزی خوردن و نان سنگک","width":1200,"height":1500}},{"id":"mrgh-masty","country":"IR","slugs":{"fa":"مرغ-ماستی","en":"morgh-masti","ar":"دجاج-باللبن-والزعفران"},"title":{"fa":"مرغ ماستی","en":"Yogurt-saffron chicken","ar":"دجاج باللبن والزعفران"},"summary":{"fa":"تکه‌های مرغ که چند ساعت در ماست، پیاز، سیر و زعفران خوابیده‌اند و روی بستری از پیاز با حرارت ملایم می‌پزند تا نرم و خوش‌عطر شوند.","en":"Chicken pieces marinated for hours in yogurt, onion, garlic and saffron, then cooked gently on a bed of onions until tender and fragrant.","ar":"قطع دجاج متبّلة لساعات باللبن والبصل والثوم والزعفران، تُطهى بهدوء على فرشة من البصل حتى تطرى وتفوح."},"intro":{"fa":"مرغ ماستی غذایی خانگی و ساده است: ماست گوشت مرغ را نرم می‌کند و زعفران به آن رنگ و عطر می‌دهد. مرغ روی لایه‌ای از پیاز و با حرارت کم می‌پزد تا ماست نبُرد و سس غلیظی بسازد.","en":"Yogurt chicken is a simple home dish: yogurt tenderises the chicken and saffron gives colour and aroma. It cooks on a layer of onion over low heat so the yogurt does not split and forms a thick sauce.","ar":"الدجاج باللبن طبق منزلي بسيط: يطري اللبن لحم الدجاج ويمنحه الزعفران لونًا ورائحة. يُطهى على طبقة من البصل بنار هادئة كي لا يتخثر اللبن وتتكوّن صلصة كثيفة."},"seoTitle":{"fa":"مرغ ماستی زعفرانی؛ طرز تهیه آسان روی بستر پیاز","en":"Yogurt-Saffron Chicken Recipe (Persian Morgh Masti)","ar":"دجاج باللبن والزعفران: طريقة عمل إيرانية سهلة"},"seoDescription":{"fa":"طرز تهیه مرغ ماستی برای ۴ نفر: مرغ که دست‌کم ۲ ساعت در ماست، پیاز، سیر و زعفران می‌خوابد و روی بستر پیاز با حرارت ملایم می‌پزد؛ آسان، ۳ ساعت و ۴۵ دقیقه.","en":"Easy Persian chicken for 4: marinated at least 2 h in yogurt, onion, garlic and saffron, then cooked gently on a bed of onions. About 3 h 45 min.","ar":"طريقة عمل الدجاج باللبن والزعفران لأربعة أشخاص: قطع دجاج تُتبَّل ساعتين على الأقل باللبن والبصل والثوم والزعفران وتُطهى بهدوء على فرشة بصل؛ سهل."},"servings":4,"prep":30,"cook":55,"rest":140,"total":225,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"مرغ تکه‌شده با استخوان","en":"Bone-in chicken pieces","ar":"قطع دجاج بالعظم"},"amount":"800","unit":"گرم","optional":false,"group":{"fa":"مرغ","en":"Chicken","ar":"الدجاج"},"note":{"fa":"ران و سینه؛ ران آبدارتر می‌ماند","en":"Thighs and breast; thighs stay juicier","ar":"أفخاذ وصدر؛ الأفخاذ تبقى أطرى"}},{"name":{"fa":"ماست پرچرب","en":"Full-fat yogurt","ar":"لبن كامل الدسم"},"amount":"1.5","unit":"پیمانه","optional":false,"group":{"fa":"مایهٔ ماستی","en":"Yogurt marinade","ar":"تتبيلة اللبن"},"note":{"fa":"ماست چکیده بهتر است","en":"Strained yogurt is best","ar":"المصفّى أفضل"}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"بزرگ؛ نصف رنده برای مایه، نصف خلالی برای کف قابلمه","en":"Large; half grated for the marinade, half sliced for the pot base","ar":"كبيرة؛ نصفها مبشور للتتبيلة ونصفها شرائح لقاع القدر"}},{"name":{"fa":"سیر","en":"Garlic","ar":"ثوم"},"amount":"3","unit":"حبه","optional":false,"group":{"fa":"مایهٔ ماستی","en":"Yogurt marinade","ar":"تتبيلة اللبن"},"note":{"fa":"له‌شده","en":"Crushed","ar":"مهروس"}},{"name":{"fa":"زعفران دم‌کرده","en":"Brewed saffron","ar":"زعفران منقوع"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مایهٔ ماستی","en":"Yogurt marinade","ar":"تتبيلة اللبن"},"note":{"fa":"\xbc قاشق چای‌خوری زعفران سابیده با ۳ قاشق آب داغ؛ ۲ قاشق برای مایه، ۱ قاشق برای آخر پخت","en":"\xbc tsp ground saffron in 3 tbsp hot water; 2 tbsp for the marinade, 1 for the end","ar":"\xbc ملعقة صغيرة زعفران مطحون في ٣ ملاعق ماء ساخن؛ ملعقتان للتتبيلة وواحدة للنهاية"}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"۱ قاشق برای مایه، ۱ قاشق برای کف قابلمه","en":"1 tbsp marinade, 1 tbsp pot base","ar":"ملعقة للتتبيلة وملعقة لقاع القدر"}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده‌سازی مرغ و پیاز","en":"Prep the chicken and onion","ar":"تحضير الدجاج والبصل"},"text":{"fa":"۱) زعفران سابیده را با ۳ قاشق آب داغ دم کنید.\\n۲) چربی و پوست اضافی مرغ را جدا کنید، تکه‌ها را با دستمال کاغذی کاملاً خشک کنید و روی قسمت‌های ضخیم با چاقو چند برش سطحی بزنید. بعد دست‌ها و تخته را با آب گرم و صابون بشویید.\\n۳) پیاز را پوست بگیرید؛ نصفش را رنده کنید و آبش را با دست بگیرید، نصف دیگر را خلالی نازک خرد کنید. سیر را له کنید.","en":"1) Steep the ground saffron in 3 tbsp hot water.\\n2) Trim excess fat and skin, pat the pieces completely dry with paper towels and make a few shallow cuts on the thick parts. Then wash your hands and board with hot soapy water.\\n3) Peel the onion; grate half and squeeze out its juice by hand, slice the other half thinly. Crush the garlic.","ar":"١) انقع الزعفران المطحون في ٣ ملاعق ماء ساخن.\\n٢) أزل الدهن والجلد الزائد، وجفف القطع جيدًا بمناديل ورقية واصنع بضعة شقوق سطحية في الأجزاء السميكة. ثم اغسل يديك واللوح بالماء الساخن والصابون.\\n٣) قشّر البصلة؛ ابشر نصفها واعصر ماءها باليد، وقطّع النصف الآخر شرائح رفيعة. اهرس الثوم."},"time":15,"image":{"src":"/recipes/mrgh-masty/step-01.webp","alt":"تکه‌های مرغ برش‌خورده روی تخته با پیاز رنده‌شده، خلال پیاز، سیر له‌شده و آب زعفران","width":1200,"height":900}},{"n":2,"title":{"fa":"خواباندن در ماست","en":"Marinate in yogurt","ar":"التتبيل باللبن"},"text":{"fa":"۱) در کاسهٔ بزرگ ماست، پیاز رنده‌شده، سیر، ۲ قاشق زعفران، ۱ قاشق روغن، زردچوبه، نمک و فلفل را هم بزنید تا یکدست و زرد شود.\\n۲) مرغ را داخل مایه بگذارید و کاملاً آغشته کنید. روی کاسه را بپوشانید و دست‌کم ۲ ساعت و حداکثر ۸ ساعت در یخچال بگذارید.\\n۳) ۱۵ دقیقه پیش از پخت، کاسه را از یخچال بیرون بگذارید.","en":"1) In a large bowl mix the yogurt, grated onion, garlic, 2 tbsp saffron, 1 tbsp oil, turmeric, salt and pepper until smooth and yellow.\\n2) Add the chicken and coat well. Cover and refrigerate at least 2 hours and up to 8 hours.\\n3) Take the bowl out of the fridge 15 minutes before cooking.","ar":"١) في وعاء كبير اخلط اللبن والبصل المبشور والثوم وملعقتين من الزعفران وملعقة زيت والكركم والملح والفلفل حتى يتجانس ويصفرّ.\\n٢) ضع الدجاج في الخليط وغطّه جيدًا. غطِّ الوعاء وضعه في الثلاجة ساعتين على الأقل و٨ ساعات على الأكثر.\\n٣) أخرج الوعاء من الثلاجة قبل الطهي بـ١٥ دقيقة."},"time":10,"image":{"src":"/recipes/mrgh-masty/step-02.webp","alt":"تکه‌های مرغ آغشته به مایهٔ زرد ماست و زعفران در کاسهٔ شیشه‌ای","width":1200,"height":900}},{"n":3,"title":{"fa":"چیدن در قابلمه","en":"Arrange in the pot","ar":"الترتيب في القدر"},"text":{"fa":"۱) ۱ قاشق روغن را کف قابلمهٔ نچسب بریزید و خلال‌های پیاز را یکدست کف آن پهن کنید.\\n۲) تکه‌های مرغ را با مایه‌اش در یک لایه روی پیازها بچینید و زیاد روی هم نگذارید.","en":"1) Put 1 tbsp oil in a non-stick pot and spread the sliced onion evenly over the base.\\n2) Lay the chicken with its marinade in one layer over the onions, without stacking too much.","ar":"١) ضع ملعقة زيت في قدر غير لاصقة وافرد شرائح البصل بالتساوي في القاع.\\n٢) رتّب قطع الدجاج مع تتبيلتها في طبقة واحدة فوق البصل دون تكديس."},"time":5,"image":{"src":"/recipes/mrgh-masty/step-03.webp","alt":"مرغ آغشته به ماست در یک لایه روی خلال پیاز در قابلمهٔ نچسب","width":1200,"height":900}},{"n":4,"title":{"fa":"پخت آرام با در بسته","en":"Cook slowly, covered","ar":"الطهي الهادئ مغطًى"},"text":{"fa":"۱) در قابلمه را بگذارید و روی حرارت ملایم ۴۰ دقیقه بپزید. در این مدت مرغ را جابه‌جا نکنید؛ مرغ و پیاز خودشان آب می‌اندازند.\\n۲) بعد از ۴۰ دقیقه تکه‌ها را با انبر برگردانید.","en":"1) Cover and cook on low heat for 40 minutes without moving the chicken; the chicken and onion release their own liquid.\\n2) After 40 minutes turn the pieces with tongs.","ar":"١) غطِّ القدر واطهه على نار هادئة ٤٠ دقيقة دون تحريك الدجاج؛ فالدجاج والبصل يُخرجان سائلهما.\\n٢) بعد ٤٠ دقيقة اقلب القطع بالملقط."},"time":40,"image":{"src":"/recipes/mrgh-masty/step-04.webp","alt":"مرغ در حال پخت آرام در سس زرد ماستی با انبر روی لبهٔ قابلمه","width":1200,"height":900}},{"n":5,"title":{"fa":"غلیظ کردن سس و زعفران آخر","en":"Thicken the sauce and finish with saffron","ar":"تكثيف الصلصة وإضافة الزعفران"},"text":{"fa":"۱) در را بردارید و ۱۰ تا ۱۵ دقیقه دیگر روی حرارت ملایم بپزید تا سس غلیظ شود. حرارت را زیاد نکنید تا ماست نبُرد.\\n۲) در ۵ دقیقهٔ آخر ۱ قاشق زعفران باقی‌مانده را روی مرغ بریزید.\\n۳) ضخیم‌ترین تکه را از کنار استخوان ببرید: گوشت نباید صورتی باشد و آبش باید شفاف باشد (با دماسنج ۷۴ درجه).","en":"1) Uncover and cook 10–15 minutes more on low heat until the sauce thickens. Do not raise the heat or the yogurt may split.\\n2) In the last 5 minutes pour the remaining 1 tbsp saffron over the chicken.\\n3) Cut the thickest piece next to the bone: the meat must not be pink and the juices should run clear (74\xb0C on a thermometer).","ar":"١) ارفع الغطاء واطهه ١٠–١٥ دقيقة أخرى على نار هادئة حتى تثخن الصلصة. لا ترفع النار كي لا يتخثر اللبن.\\n٢) في آخر ٥ دقائق اسكب ملعقة الزعفران الباقية فوق الدجاج.\\n٣) اقطع أسمك قطعة بجوار العظم: يجب ألا يكون اللحم ورديًا وأن يكون عصيره صافيًا (٧٤ درجة بميزان الحرارة)."},"time":15,"image":{"src":"/recipes/mrgh-masty/step-05.webp","alt":"ریختن آب زعفران روی تکه‌های مرغ طلایی در سس غلیظ ماست در قابلمهٔ بی‌در","width":1200,"height":900}},{"n":6,"title":{"fa":"استراحت و سرو","en":"Rest and serve","ar":"الإراحة والتقديم"},"text":{"fa":"۱) حرارت را خاموش کنید و ۵ دقیقه بگذارید بماند تا سس یکدست شود.\\n۲) مرغ را با پیاز و سس در دیس بکشید.","en":"1) Turn off the heat and leave 5 minutes so the sauce settles.\\n2) Serve the chicken with the onions and sauce on a platter.","ar":"١) أطفئ النار واتركه ٥ دقائق لتستقر الصلصة.\\n٢) قدّم الدجاج مع البصل والصلصة في طبق."},"time":5,"image":{"src":"/recipes/mrgh-masty/step-06.webp","alt":"مرغ ماستی با سس پیاز در دیس کنار کاسهٔ برنج و سالاد شیرازی","width":1200,"height":900}}],"tips":{"fa":["مرغ را پیش از خواباندن کاملاً خشک کنید تا مایه آبکی نشود.","حرارت زیاد ماست را می‌بُرد؛ کل پخت روی شعلهٔ ملایم باشد.","شب قبل خواباندن طعم بهتری می‌دهد، ولی بیشتر از ۸ ساعت نگه ندارید (دلگرم).","ماست چکیده یا پرچرب بهتر است؛ ماست رقیق سس را آبکی می‌کند."],"en":["Dry the chicken well before marinating so the marinade does not get watery.","High heat splits yogurt; keep the whole cook on low.","Marinating the night before gives more flavour, but do not exceed 8 hours (Delgarm).","Strained or full-fat yogurt works best; thin yogurt makes a runny sauce."],"ar":["جفف الدجاج جيدًا قبل التتبيل كي لا تصبح التتبيلة مائية.","النار العالية تخثّر اللبن؛ اطهه كله على نار هادئة.","التتبيل من الليلة السابقة يعطي نكهة أفضل، لكن لا تتجاوز ٨ ساعات.","اللبن المصفّى أو الكامل الدسم أفضل؛ فالرقيق يجعل الصلصة سائلة."]},"cover":{"src":"/recipes/mrgh-masty/cover.webp","alt":"تکه‌های مرغ ماستی در سس غلیظ زعفرانی با پیاز نرم در ظرف سرامیکی کم‌عمق","width":1600,"height":1200},"serving":{"src":"/recipes/mrgh-masty/serving.webp","alt":"بشقاب مرغ ماستی با برنج سفید و کاسهٔ کوچک سالاد شیرازی","width":1200,"height":1500}},{"id":"plw-shwyd-w-mrgh","country":"IR","slugs":{"fa":"شوید-پلو-با-مرغ","en":"shevid-polo-ba-morgh","ar":"أرز-بالشبت-مع-الدجاج"},"title":{"fa":"پلو شوید و مرغ","en":"Dill rice with chicken (shevid polo)","ar":"أرز بالشبت مع الدجاج"},"summary":{"fa":"برنج آبکش ایرانی که با شوید تازه و تکه‌های مرغ پخته لایه‌لایه دم می‌کشد و با زعفران معطر می‌شود.","en":"Persian drained-and-steamed rice layered with fresh dill and cooked chicken, finished with saffron.","ar":"أرز إيراني مصفّى ومطهو على البخار في طبقات مع الشبت الطازج وقطع الدجاج المطبوخ، مع لمسة زعفران."},"intro":{"fa":"شوید پلو با مرغ از پلوهای خانگی و مجلسی ایران است. راز آن شوید تازه‌ای است که کاملاً خشک شده و برنجی که کمی زنده‌تر از همیشه آبکش می‌شود تا دانه‌دانه بماند. در این نسخه مرغ پخته لای برنج دم می‌کشد.","en":"Dill rice with chicken is a Persian pilaf for both everyday and guests. The secret is fresh dill that has been dried well and rice drained a little firmer than usual so it stays fluffy. Here the cooked chicken steams between the rice layers.","ar":"الأرز بالشبت مع الدجاج من أطباق الأرز الإيرانية اليومية والاحتفالية. وسرّه شبت طازج جُفف جيدًا وأرز يُصفّى أقسى قليلًا من المعتاد ليبقى مفلفلًا. وفي هذه النسخة يُطهى الدجاج على البخار بين طبقات الأرز."},"seoTitle":{"fa":"شوید پلو با مرغ؛ طرز تهیه با زعفران و شوید تازه","en":"Shevid Polo ba Morgh Recipe (Persian Dill Rice with Chicken)","ar":"أرز بالشبت مع الدجاج: طريقة عمل الأرز الإيراني بالزعفران"},"seoDescription":{"fa":"طرز تهیه شوید پلو با مرغ برای ۴ نفر: برنج آبکش ایرانی که با شوید تازه و مرغ پخته لایه‌لایه دم می‌کشد و با زعفران معطر می‌شود؛ حدود ۴ ساعت با خیساندن.","en":"Persian dill rice with chicken for 4: steamed rice layered with fresh dill and cooked chicken, finished with saffron. About 4 h incl. soaking the rice.","ar":"طريقة عمل أرز بالشبت مع الدجاج لأربعة أشخاص: أرز إيراني مصفّى يُطهى على البخار في طبقات مع الشبت الطازج وقطع الدجاج المطبوخ ولمسة زعفران؛ نحو ٤ ساعات."},"servings":4,"prep":30,"cook":95,"rest":125,"total":250,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"برنج ایرانی دانه‌بلند","en":"Persian long-grain rice","ar":"أرز إيراني طويل الحبة"},"amount":"3","unit":"پیمانه","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"حدود ۶۰۰ گرم","en":"About 600 g","ar":"نحو ٦٠٠ غرام"}},{"name":{"fa":"نمک برای خیساندن و جوشاندن","en":"Salt for soaking and boiling","ar":"ملح للنقع والسلق"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"بیشتر آن با آب دور ریخته می‌شود.","en":"Most of it is drained away.","ar":"يُصرف معظمه مع الماء."}},{"name":{"fa":"آب برای جوشاندن برنج","en":"Water for boiling the rice","ar":"ماء لسلق الأرز"},"amount":"3","unit":"لیتر","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شوید تازه","en":"Fresh dill","ar":"شبت طازج"},"amount":"2","unit":"پیمانه","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"ریز خردشده، حدود ۱۰۰ تا ۱۲۰ گرم","en":"Finely chopped, about 100–120 g","ar":"مفروم ناعمًا، نحو ١٠٠–١٢٠ غرامًا"}},{"name":{"fa":"ران یا ساق مرغ با استخوان","en":"Bone-in chicken thighs or drumsticks","ar":"أفخاذ أو سيقان دجاج بالعظم"},"amount":"500","unit":"گرم","optional":false,"group":{"fa":"مرغ","en":"Chicken","ar":"الدجاج"},"note":{"fa":"بدون پوست","en":"Skinless","ar":"منزوعة الجلد"}},{"name":{"fa":"پیاز","en":"Onion","ar":"بصل"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"مرغ","en":"Chicken","ar":"الدجاج"},"note":{"fa":"متوسط، خلالی","en":"Medium, sliced","ar":"متوسطة، شرائح"}},{"name":{"fa":"آب جوش برای مرغ","en":"Boiling water for the chicken","ar":"ماء مغلي للدجاج"},"amount":"1.5","unit":"پیمانه","optional":false,"group":{"fa":"مرغ","en":"Chicken","ar":"الدجاج"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک برای مرغ","en":"Salt for the chicken","ar":"ملح للدجاج"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زعفران دم‌کرده","en":"Brewed saffron","ar":"زعفران منقوع"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"\xbc قاشق چای‌خوری زعفران سابیده با ۳ قاشق آب داغ","en":"\xbc tsp ground saffron in 3 tbsp hot water","ar":"\xbc ملعقة صغيرة زعفران مطحون في ٣ ملاعق ماء ساخن"}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"۱٫۵ قاشق برای مرغ، ۱٫۵ قاشق برای کف قابلمه","en":"1.5 tbsp for the chicken, 1.5 for the pot base","ar":"ملعقة ونصف للدجاج وملعقة ونصف لقاع القدر"}}],"steps":[{"n":1,"title":{"fa":"شستن و خیساندن برنج","en":"Wash and soak the rice","ar":"غسل الأرز ونقعه"},"text":{"fa":"۱) برنج را ۳ تا ۴ بار با آب سرد بشویید تا آبش تقریباً شفاف شود.\\n۲) روی برنج آب و ۱ قاشق غذاخوری نمک بریزید و ۲ ساعت بگذارید خیس بخورد.","en":"1) Rinse the rice 3–4 times in cold water until nearly clear.\\n2) Cover with water plus 1 tbsp salt and soak for 2 hours.","ar":"١) اغسل الأرز ٣–٤ مرات بالماء البارد حتى يصفو الماء تقريبًا.\\n٢) غطّه بالماء مع ملعقة كبيرة من الملح وانقعه ساعتين."},"time":5,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-01.webp","alt":"برنج دانه‌بلند خیس‌خورده در آب نمک داخل کاسهٔ شیشه‌ای بزرگ","width":1200,"height":900}},{"n":2,"title":{"fa":"آماده کردن شوید، پیاز، مرغ و زعفران","en":"Prep the dill, onion, chicken and saffron","ar":"تحضير الشبت والبصل والدجاج والزعفران"},"text":{"fa":"۱) شوید را در کاسهٔ آب سرد بشویید، آبکش کنید و روی حوله پهن کنید تا کاملاً خشک شود. ساقه‌های سفت را جدا کنید و برگ‌ها را ریز خرد کنید.\\n۲) پیاز را پوست بگیرید و خلالی نازک خرد کنید.\\n۳) پوست و چربی اضافی مرغ را جدا کنید و با دستمال کاغذی خشک کنید. بعد دست و تخته را با آب گرم و صابون بشویید.\\n۴) زعفران سابیده را با ۳ قاشق آب داغ دم کنید.","en":"1) Wash the dill in a bowl of cold water, drain and spread on a towel until completely dry. Remove tough stalks and chop the fronds finely.\\n2) Peel the onion and slice thinly.\\n3) Remove skin and excess fat from the chicken and pat dry with paper towels. Then wash hands and board with hot soapy water.\\n4) Steep the ground saffron in 3 tbsp hot water.","ar":"١) اغسل الشبت في وعاء ماء بارد وصفّه وافرده على منشفة حتى يجف تمامًا. أزل السيقان القاسية وافرم الأوراق ناعمًا.\\n٢) قشّر البصلة وقطّعها شرائح رفيعة.\\n٣) أزل الجلد والدهن الزائد من الدجاج وجففه بمناديل ورقية. ثم اغسل يديك واللوح بالماء الساخن والصابون.\\n٤) انقع الزعفران المطحون في ٣ ملاعق ماء ساخن."},"time":15,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-02.webp","alt":"شوید ریز خردشده روی حوله، خلال پیاز و ران مرغ بی‌پوست روی تخته و آب زعفران","width":1200,"height":900}},{"n":3,"title":{"fa":"پختن مرغ","en":"Cook the chicken","ar":"طهي الدجاج"},"text":{"fa":"۱) ۱٫۵ قاشق روغن را در قابلمه روی حرارت متوسط گرم کنید و پیاز را ۵ تا ۷ دقیقه تفت دهید تا طلایی شود.\\n۲) مرغ و زردچوبه را اضافه کنید و ۵ دقیقه تفت دهید تا رنگ مرغ عوض شود.\\n۳) ۱٫۵ پیمانه آب جوش و \xbd قاشق چای‌خوری نمک بریزید، در را بگذارید و روی حرارت ملایم ۳۵ تا ۴۰ دقیقه بپزید تا مرغ کاملاً پخته شود (کنار استخوان صورتی نباشد؛ با دماسنج ۷۴ درجه). نصف پیمانه از آب مرغ را نگه دارید.\\n۴) در ۱۵ دقیقهٔ آخر پخت مرغ، مرحلهٔ ۴ را شروع کنید.","en":"1) Heat 1.5 tbsp oil in a pot over medium heat and fry the onion 5–7 minutes until golden.\\n2) Add the chicken and turmeric and saut\xe9 5 minutes until the chicken changes colour.\\n3) Add 1.5 cups boiling water and \xbd tsp salt, cover and simmer on low 35–40 minutes until fully cooked (no pink by the bone; 74\xb0C on a thermometer). Keep \xbd cup of the stock.\\n4) In the last 15 minutes of the chicken, start step 4.","ar":"١) سخّن ملعقة ونصفًا من الزيت في قدر على نار متوسطة واقلِ البصل ٥–٧ دقائق حتى يذهبّ.\\n٢) أضف الدجاج والكركم وقلّبه ٥ دقائق حتى يتغير لونه.\\n٣) أضف كوبًا ونصف كوب من الماء المغلي ونصف ملعقة صغيرة ملح، وغطِّ القدر واطهه على نار هادئة ٣٥–٤٠ دقيقة حتى ينضج تمامًا (لا لون وردي بجوار العظم؛ ٧٤ درجة بميزان الحرارة). احتفظ بنصف كوب من المرق.\\n٤) في آخر ١٥ دقيقة من طهي الدجاج ابدأ الخطوة ٤."},"time":50,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-03.webp","alt":"ران مرغ در حال پخت با پیاز طلایی و زردچوبه در قابلمهٔ نیمه‌سرپوشیده","width":1200,"height":900}},{"n":4,"title":{"fa":"آبکش کردن برنج","en":"Parboil and drain the rice","ar":"سلق الأرز وتصفيته"},"text":{"fa":"۱) ۳ لیتر آب را با ۱ قاشق غذاخوری نمک در قابلمهٔ بزرگ به جوش تند برسانید.\\n۲) آب برنج خیس‌خورده را خالی کنید و برنج را در آب جوش بریزید. ۷ تا ۸ دقیقه بجوشانید تا دور دانه نرم و مغزش کمی سفت باشد؛ کمی زنده‌تر از پلوی معمولی.\\n۳) برنج را آبکش کنید و یک لیوان آب ولرم رویش بریزید.","en":"1) Bring 3 litres of water with 1 tbsp salt to a rolling boil in a large pot.\\n2) Drain the soaked rice and add it to the boiling water. Boil 7–8 minutes until soft outside with a slightly firm centre — a little firmer than for plain polo.\\n3) Drain in a colander and pour a glass of lukewarm water over it.","ar":"١) اغلِ ٣ لترات من الماء مع ملعقة كبيرة من الملح غليانًا شديدًا في قدر كبيرة.\\n٢) صفِّ الأرز المنقوع وأضفه إلى الماء المغلي. اسلقه ٧–٨ دقائق حتى يلين الخارج ويبقى القلب متماسكًا قليلًا، أقسى قليلًا من الأرز العادي.\\n٣) صفِّه في مصفاة واسكب فوقه كوبًا من الماء الفاتر."},"time":15,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-04.webp","alt":"برنج نیم‌پز دانه‌بلند در آبکش روی سینک","width":1200,"height":900}},{"n":5,"title":{"fa":"لایه‌چینی برنج، شوید و مرغ","en":"Layer rice, dill and chicken","ar":"ترتيب طبقات الأرز والشبت والدجاج"},"text":{"fa":"۱) ۱٫۵ قاشق روغن و ۲ قاشق آب را کف قابلمهٔ نچسب بریزید.\\n۲) یک لایه برنج بریزید و رویش کمی شوید بپاشید. تکه‌های مرغ را روی لایهٔ دوم بچینید و همین‌طور برنج و شوید را لایه‌لایه و هرمی بریزید؛ لایهٔ آخر برنج باشد. برنج را فشار ندهید.\\n۳) ۲ قاشق زعفران و ۳ قاشق آب مرغ را روی برنج بپاشید.","en":"1) Put 1.5 tbsp oil and 2 tbsp water in the base of a non-stick pot.\\n2) Spread a layer of rice and sprinkle some dill over it. Place the chicken pieces on the second layer and keep layering rice and dill in a mound, finishing with rice. Do not press the rice.\\n3) Drizzle 2 tbsp saffron and 3 tbsp chicken stock over the rice.","ar":"١) ضع ملعقة ونصفًا من الزيت وملعقتي ماء في قاع قدر غير لاصقة.\\n٢) افرد طبقة من الأرز ورشّ فوقها قليلًا من الشبت. ضع قطع الدجاج على الطبقة الثانية وتابع ترتيب الأرز والشبت على شكل هرم، وانتهِ بالأرز. لا تضغط الأرز.\\n٣) رشّ ملعقتين من الزعفران و٣ ملاعق من مرق الدجاج فوق الأرز."},"time":10,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-05.webp","alt":"لایه‌های برنج سفید و شوید در قابلمه با تکه‌های مرغ میان لایه‌ها و آب زعفران رویشان","width":1200,"height":900}},{"n":6,"title":{"fa":"دم کشیدن","en":"Steam","ar":"الطهي على البخار"},"text":{"fa":"۱) با دستهٔ قاشق چوبی چند سوراخ تا نزدیک کف بزنید.\\n۲) قابلمه را ۵ تا ۷ دقیقه روی حرارت متوسط بگذارید تا بخار کند. بعد در را با دم‌کنی بپوشانید، حرارت را خیلی کم کنید و ۳۵ تا ۴۰ دقیقه دم بگذارید.","en":"1) Poke a few holes almost to the base with the handle of a wooden spoon.\\n2) Keep on medium heat 5–7 minutes until steaming. Then cover with a lid wrapped in a lid cover, turn to very low and steam 35–40 minutes.","ar":"١) اثقب بضعة ثقوب حتى قرب القاع بمقبض ملعقة خشبية.\\n٢) اتركها على نار متوسطة ٥–٧ دقائق حتى يتصاعد البخار. ثم غطّها بغطاء ملفوف بقماش واخفض النار جدًا واتركها ٣٥–٤٠ دقيقة."},"time":45,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-06.webp","alt":"قابلمه با درِ پوشیده در دم‌کنی روی شعلهٔ کم و بخار از لبه","width":1200,"height":900}},{"n":7,"title":{"fa":"استراحت و کشیدن","en":"Rest and serve","ar":"الإراحة والتقديم"},"text":{"fa":"۱) قابلمه را ۵ دقیقه با در بسته از روی حرارت بردارید.\\n۲) پلو را با کفگیر آرام در دیس بکشید، مرغ را لابه‌لا بگذارید و ۱ قاشق زعفران باقی‌مانده را روی چند کفگیر برنج بریزید و روی پلو بپاشید. ته‌دیگ را جدا سرو کنید.","en":"1) Take the pot off the heat and leave covered 5 minutes.\\n2) Gently spoon the rice onto a platter with the chicken among it; mix the remaining 1 tbsp saffron into a few spoonfuls of rice and scatter on top. Serve the crust separately.","ar":"١) ارفع القدر عن النار واتركها مغطاة ٥ دقائق.\\n٢) اغرف الأرز بلطف إلى طبق مع الدجاج بينه، واخلط ملعقة الزعفران الباقية ببضع مغارف من الأرز ورشّها فوقه. قدّم القشرة منفصلة."},"time":5,"image":{"src":"/recipes/plw-shwyd-w-mrgh/step-07.webp","alt":"دیس پلو شوید با برنج زعفرانی رویش و تکه‌های مرغ لابه‌لا و ته‌دیگ طلایی کنارش","width":1200,"height":900}}],"tips":{"fa":["شوید را بعد از شستن کاملاً خشک کنید تا پلو خمیری نشود (خوش‌کده).","شوید را خیلی له نکنید و برنج را با حداقل فشار مخلوط کنید.","آب مرغ کم و معطر کافی است؛ زیادش برنج را خیس می‌کند.","ران و ساق مرغ از سینه آبدارتر می‌ماند (خوش‌کده)."],"en":["Dry the dill completely after washing so the rice does not turn mushy (Khoshkadeh).","Do not crush the dill and mix the rice with minimal pressure.","A little fragrant stock is enough; too much makes the rice soggy.","Thighs and drumsticks stay juicier than breast (Khoshkadeh)."],"ar":["جفف الشبت تمامًا بعد غسله كي لا يتعجّن الأرز.","لا تهرس الشبت واخلط الأرز بأقل ضغط.","قليل من المرق العطري يكفي؛ فالكثير يبلل الأرز.","الأفخاذ والسيقان تبقى أطرى من الصدر."]},"cover":{"src":"/recipes/plw-shwyd-w-mrgh/cover.webp","alt":"دیس پلو شوید و مرغ با برنج زعفرانی و تکه‌های مرغ لابه‌لای برنج و ته‌دیگ طلایی کنارش","width":1600,"height":1200},"serving":{"src":"/recipes/plw-shwyd-w-mrgh/serving.webp","alt":"بشقاب پلو شوید و مرغ با کاسهٔ ماست و خیار","width":1200,"height":1500}},{"id":"thchyn-kdw","country":"IR","slugs":{"fa":"ته-چین-کدو","en":"tahchin-kadoo","ar":"تهتشين-الكوسا"},"title":{"fa":"ته‌چین کدو","en":"Zucchini tahchin","ar":"تهتشين الكوسا"},"summary":{"fa":"ته‌چین گیاهی با برنج زعفرانی ماستی و لایه‌ای از کدو سبز طلایی که روی شعلهٔ ملایم دم می‌کشد و قالبی برگردانده می‌شود.","en":"A vegetarian tahchin of saffron-yogurt rice with a layer of golden zucchini, steamed on low heat and turned out whole.","ar":"تهتشين نباتي من أرز بالزعفران واللبن مع طبقة من الكوسا الذهبية، يُطهى على البخار بنار هادئة ويُقلب قالبًا كاملًا."},"intro":{"fa":"ته‌چین کدو شکل گیاهی ته‌چین است: برنج نیم‌پز با ماست، زعفران و تخم‌مرغ مخلوط می‌شود، کدوی سرخ‌شده لای آن قرار می‌گیرد و ته‌دیگی ترد و طلایی می‌سازد. منابع ایرانی این غذا را بیشتر با نام \xabته‌چین سبزیجات\xbb یا \xabته‌چین کدو سبز\xbb آورده‌اند.","en":"Zucchini tahchin is a vegetarian take on tahchin: parboiled rice is mixed with yogurt, saffron and egg, fried zucchini goes in the middle, and the bottom becomes a crisp golden crust. Iranian sources mostly call it \\"vegetable tahchin\\" or \\"green-zucchini tahchin\\".","ar":"تهتشين الكوسا صيغة نباتية من التهتشين: يُخلط الأرز نصف المسلوق باللبن والزعفران والبيض، وتوضع الكوسا المقلية في وسطه، فتتكوّن قشرة ذهبية مقرمشة في القاع. وتسميه المصادر الإيرانية غالبًا \xabتهتشين الخضار\xbb أو \xabتهتشين الكوسا الخضراء\xbb."},"seoTitle":{"fa":"ته‌چین کدو؛ طرز تهیه ته‌چین گیاهی با کدو سبز","en":"Zucchini Tahchin Recipe (Persian Saffron Rice Cake)","ar":"تهتشين الكوسا: طريقة عمل الأرز الإيراني بالزعفران والكوسا"},"seoDescription":{"fa":"طرز تهیه ته‌چین کدو برای ۴ نفر: برنج زعفرانی با ماست و لایهٔ کدو سبز طلایی که روی شعلهٔ ملایم دم می‌کشد و قالبی برگردانده می‌شود؛ حدود ۴ ساعت با خیساندن.","en":"Vegetarian zucchini tahchin for 4: saffron-yogurt rice layered with golden zucchini, steamed on low heat and turned out whole. About 4 h incl. soaking.","ar":"طريقة عمل تهتشين الكوسا لأربعة أشخاص: أرز بالزعفران واللبن مع طبقة من الكوسا الذهبية يُطهى على نار هادئة ويُقلب قالبًا كاملًا؛ نحو ٤ ساعات مع نقع الأرز."},"servings":4,"prep":35,"cook":80,"rest":125,"total":240,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"برنج ایرانی دانه‌بلند","en":"Persian long-grain rice","ar":"أرز إيراني طويل الحبة"},"amount":"3","unit":"پیمانه","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"حدود ۶۰۰ گرم","en":"About 600 g","ar":"نحو ٦٠٠ غرام"}},{"name":{"fa":"نمک برای خیساندن و جوشاندن","en":"Salt for soaking and boiling","ar":"ملح للنقع والسلق"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"بیشتر آن با آب دور ریخته می‌شود.","en":"Most of it is drained away.","ar":"يُصرف معظمه مع الماء."}},{"name":{"fa":"کدو سبز","en":"Zucchini","ar":"كوسا"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"متوسط (حدود ۶۰۰ گرم)","en":"Medium (about 600 g)","ar":"متوسطة (نحو ٦٠٠ غرام)"}},{"name":{"fa":"ماست چکیده","en":"Strained yogurt","ar":"لبن مصفّى"},"amount":"250","unit":"گرم","optional":false,"group":{"fa":"مایهٔ ته‌چین","en":"Tahchin mixture","ar":"خليط التهتشين"},"note":{"fa":"حدود ۱ پیمانه؛ ماست پرچرب بهتر است.","en":"About 1 cup; full-fat is best.","ar":"نحو كوب؛ الكامل الدسم أفضل."}},{"name":{"fa":"تخم‌مرغ","en":"Egg","ar":"بيض"},"amount":"1","unit":"عدد","optional":true,"group":{"fa":"مایهٔ ته‌چین","en":"Tahchin mixture","ar":"خليط التهتشين"},"note":{"fa":"یا فقط زرده؛ بدون آن هم می‌شود.","en":"Or just the yolk; can be left out.","ar":"أو الصفار فقط؛ ويمكن الاستغناء عنه."}},{"name":{"fa":"زعفران دم‌کرده","en":"Brewed saffron","ar":"زعفران منقوع"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مایهٔ ته‌چین","en":"Tahchin mixture","ar":"خليط التهتشين"},"note":{"fa":"\xbc قاشق چای‌خوری زعفران سابیده با ۳ قاشق غذاخوری آب داغ","en":"\xbc tsp ground saffron in 3 tbsp hot water","ar":"\xbc ملعقة صغيرة زعفران مطحون في ٣ ملاعق كبيرة ماء ساخن"}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"6","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مواد اصلی","en":"Main ingredients","ar":"المكونات الأساسية"},"note":{"fa":"۲ قاشق برای کدو، ۲ قاشق برای مایه، ۲ قاشق برای کف قابلمه","en":"2 tbsp for zucchini, 2 for the mixture, 2 for the pot base","ar":"ملعقتان للكوسا وملعقتان للخليط وملعقتان لقاع القدر"}},{"name":{"fa":"زردچوبه","en":"Turmeric","ar":"كركم"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"0.75","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ادویه و چاشنی","en":"Spices and seasoning","ar":"التوابل والمنكهات"},"note":{"fa":"برای کدو و مایهٔ ماست","en":"For the zucchini and yogurt mixture","ar":"للكوسا وخليط اللبن"}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"2.5","unit":"لیتر","optional":false,"group":{"fa":"برنج","en":"Rice","ar":"الأرز"},"note":{"fa":"برای جوشاندن برنج","en":"For boiling the rice","ar":"لسلق الأرز"}}],"steps":[{"n":1,"title":{"fa":"خیساندن برنج و آماده‌سازی","en":"Soak the rice and prep","ar":"نقع الأرز والتحضير"},"text":{"fa":"۱) برنج را در کاسه بریزید و ۳ تا ۴ بار با آب سرد بشویید تا آبش تقریباً شفاف شود. روی آن آب و ۱ قاشق غذاخوری نمک بریزید و ۲ ساعت کنار بگذارید.\\n۲) زعفران سابیده را با ۳ قاشق آب داغ دم کنید و درش را بگذارید.\\n۳) کدوها را بشویید، سر و ته را ببرید و حلقه‌های نیم سانتی بزنید. کمی نمک بپاشید، ۱۰ دقیقه بگذارید آب بیندازد و با دستمال کاملاً خشک کنید.","en":"1) Rinse the rice 3–4 times in cold water until nearly clear. Cover with water plus 1 tbsp salt and leave for 2 hours.\\n2) Steep the ground saffron in 3 tbsp hot water and cover.\\n3) Wash the zucchini, trim the ends and slice into 0.5 cm rounds. Sprinkle with a little salt, leave 10 minutes to release water, then pat completely dry.","ar":"١) اغسل الأرز ٣–٤ مرات بالماء البارد حتى يصفو تقريبًا. غطّه بالماء مع ملعقة كبيرة من الملح واتركه ساعتين.\\n٢) انقع الزعفران المطحون في ٣ ملاعق ماء ساخن وغطّه.\\n٣) اغسل الكوسا واقطع طرفيها وقطّعها حلقات بسماكة نصف سنتيمتر. رشّ قليلًا من الملح واتركها ١٠ دقائق لتخرج ماءها ثم جففها جيدًا."},"time":20,"image":{"src":"/recipes/thchyn-kdw/step-01.webp","alt":"برنج خیس‌خورده در کاسه، فنجان آب زعفران و حلقه‌های کدو روی دستمال کاغذی","width":1200,"height":900}},{"n":2,"title":{"fa":"سرخ کردن کدو","en":"Fry the zucchini","ar":"قلي الكوسا"},"text":{"fa":"۱) ۲ قاشق روغن را در تابه روی حرارت متوسط گرم کنید.\\n۲) حلقه‌های کدو را در یک لایه بچینید و هر طرف ۲ تا ۳ دقیقه سرخ کنید تا کمی طلایی شود؛ اگر جا نشد در دو نوبت. آخر کار زردچوبه بپاشید و کدو را روی دستمال کاغذی بگذارید.","en":"1) Heat 2 tbsp oil in a frying pan over medium heat.\\n2) Fry the rounds in one layer, 2–3 minutes per side until lightly golden; do two batches if needed. Sprinkle with turmeric at the end and drain on paper towels.","ar":"١) سخّن ملعقتين من الزيت في مقلاة على نار متوسطة.\\n٢) اقلِ الحلقات في طبقة واحدة ٢–٣ دقائق لكل جانب حتى تتحمّر قليلًا، على دفعتين إن لزم. رشّ الكركم في الآخر وضعها على مناديل ورقية."},"time":10,"image":{"src":"/recipes/thchyn-kdw/step-02.webp","alt":"حلقه‌های کدوی طلایی در حال سرخ شدن در تابه و چند حلقه روی دستمال کاغذی","width":1200,"height":900}},{"n":3,"title":{"fa":"نیم‌پز کردن برنج","en":"Parboil the rice","ar":"سلق الأرز جزئيًا"},"text":{"fa":"۱) ۲٫۵ لیتر آب را با ۱ قاشق غذاخوری نمک در قابلمهٔ بزرگ به جوش تند برسانید.\\n۲) آب برنج خیس‌خورده را خالی کنید، برنج را در آب جوش بریزید و ۴ تا ۵ دقیقه بجوشانید تا دور دانه نرم و مغزش هنوز سفت باشد.\\n۳) برنج را آبکش کنید و یک لیوان آب ولرم رویش بریزید.","en":"1) Bring 2.5 litres of water with 1 tbsp salt to a rolling boil in a large pot.\\n2) Drain the soaked rice, add it to the boiling water and boil 4–5 minutes until the outside is soft but the centre still firm.\\n3) Drain in a colander and pour a glass of lukewarm water over it.","ar":"١) اغلِ ٢٫٥ لتر من الماء مع ملعقة كبيرة من الملح غليانًا شديدًا في قدر كبيرة.\\n٢) صفِّ الأرز المنقوع وأضفه إلى الماء المغلي واسلقه ٤–٥ دقائق حتى يلين الخارج ويبقى قلب الحبة متماسكًا.\\n٣) صفِّه في مصفاة واسكب فوقه كوبًا من الماء الفاتر."},"time":15,"image":{"src":"/recipes/thchyn-kdw/step-03.webp","alt":"برنج نیم‌پز دانه‌بلند در آبکش فلزی با بخار","width":1200,"height":900}},{"n":4,"title":{"fa":"مخلوط ماست و زعفران","en":"Mix the yogurt-saffron base","ar":"خلط اللبن بالزعفران"},"text":{"fa":"۱) در کاسهٔ بزرگ ماست چکیده، زعفران دم‌کرده، ۲ قاشق روغن، تخم‌مرغ (اگر استفاده می‌کنید) و \xbd قاشق چای‌خوری نمک را هم بزنید تا یکدست شود.\\n۲) دوسوم برنج را با کفگیر و آرام به این مخلوط اضافه کنید و فقط تا زرد شدن یکدست هم بزنید تا دانه‌ها نشکنند. یک‌سوم برنج را ساده نگه دارید.","en":"1) In a large bowl whisk the strained yogurt, saffron water, 2 tbsp oil, the egg (if using) and \xbd tsp salt until smooth.\\n2) Gently fold two-thirds of the rice into the mixture just until evenly yellow so the grains do not break. Keep one-third plain.","ar":"١) في وعاء كبير اخفق اللبن المصفّى والزعفران المنقوع وملعقتي الزيت والبيضة (إن استعملتها) ونصف ملعقة صغيرة من الملح حتى يتجانس.\\n٢) أضف ثلثي الأرز بلطف بالمغرفة وقلّب فقط حتى يصفرّ بالتساوي كي لا تتكسر الحبات. أبقِ الثلث الآخر أبيض."},"time":8,"image":{"src":"/recipes/thchyn-kdw/step-04.webp","alt":"برنج آغشته به مخلوط زرد ماست و زعفران در کاسه کنار برنج سفید ساده","width":1200,"height":900}},{"n":5,"title":{"fa":"چیدن لایه‌ها","en":"Layer the pot","ar":"ترتيب الطبقات"},"text":{"fa":"۱) کف و دیوارهٔ قابلمهٔ نچسب را با ۲ قاشق روغن چرب کنید.\\n۲) نصف برنج زعفرانی را کف قابلمه بریزید و با پشت کفگیر آرام فشار دهید.\\n۳) حلقه‌های کدو را روی آن بچینید و ۱ سانتی‌متر از دیوارهٔ قابلمه فاصله بگذارید. بقیهٔ برنج زعفرانی و بعد برنج ساده را رویش بریزید و صاف کنید.","en":"1) Grease the base and sides of a non-stick pot with 2 tbsp oil.\\n2) Spread half the saffron rice over the base and press gently with the back of the spatula.\\n3) Arrange the zucchini on top, leaving 1 cm clear from the pot wall. Cover with the rest of the saffron rice, then the plain rice, and level.","ar":"١) ادهن قاع القدر غير اللاصقة وجوانبها بملعقتين من الزيت.\\n٢) افرد نصف الأرز بالزعفران في القاع واضغطه بلطف بظهر المغرفة.\\n٣) رتّب حلقات الكوسا فوقه مع ترك ١ سم عن جدار القدر. غطِّها ببقية الأرز بالزعفران ثم بالأرز الأبيض وسوِّ السطح."},"time":5,"image":{"src":"/recipes/thchyn-kdw/step-05.webp","alt":"لایهٔ برنج زعفرانی کف قابلمه با حلقه‌های کدوی طلایی چیده‌شده رویش","width":1200,"height":900}},{"n":6,"title":{"fa":"دم کشیدن","en":"Steam","ar":"الطهي على البخار"},"text":{"fa":"۱) با دستهٔ قاشق چوبی ۳ سوراخ تا نزدیک کف بزنید. درِ قابلمه را با دم‌کنی یا حوله بپوشانید.\\n۲) قابلمه را ۵ تا ۷ دقیقه روی حرارت متوسط بگذارید تا بخار کند، بعد حرارت را خیلی کم کنید و ۴۵ تا ۵۰ دقیقه دم بگذارید.\\n۳) اگر بوی سوختگی آمد فوراً خاموش کنید.","en":"1) Poke 3 holes almost to the base with the handle of a wooden spoon. Cover the lid with a lid cover or tea towel.\\n2) Keep on medium heat 5–7 minutes until steaming, then turn to very low and steam 45–50 minutes.\\n3) If you smell burning, turn off the heat at once.","ar":"١) اثقب ٣ ثقوب حتى قرب القاع بمقبض ملعقة خشبية. غطِّ الغطاء بغطاء قماشي أو منشفة.\\n٢) اتركها على نار متوسطة ٥–٧ دقائق حتى يتصاعد البخار، ثم اخفض النار جدًا واطهها ٤٥–٥٠ دقيقة.\\n٣) إن شممت رائحة احتراق فأطفئ النار فورًا."},"time":55,"image":{"src":"/recipes/thchyn-kdw/step-06.webp","alt":"قابلمه با درِ پوشیده در دم‌کنی روی شعلهٔ کم و کمی بخار","width":1200,"height":900}},{"n":7,"title":{"fa":"استراحت و برگرداندن","en":"Rest and turn out","ar":"الإراحة والقلب"},"text":{"fa":"۱) قابلمه را از روی حرارت بردارید و ۵ دقیقه با در بسته بگذارید بماند.\\n۲) دیس بزرگ را روی قابلمه بگذارید، با دستکش آشپزخانه هر دو را محکم بگیرید و یک‌باره برگردانید.","en":"1) Take the pot off the heat and leave covered for 5 minutes.\\n2) Place a large platter over the pot, hold both firmly with oven gloves and flip in one motion.","ar":"١) ارفع القدر عن النار واتركها مغطاة ٥ دقائق.\\n٢) ضع طبقًا كبيرًا فوق القدر، وأمسكهما جيدًا بقفازات الفرن واقلبهما دفعة واحدة."},"time":5,"image":{"src":"/recipes/thchyn-kdw/step-07.webp","alt":"ته‌چین کدو برگردانده در دیس گرد با برشی که برنج زرد و لایهٔ کدو را نشان می‌دهد","width":1200,"height":900}}],"tips":{"fa":["کدو را کاملاً خشک کنید و بعد تفت دهید تا ته‌چین آب نیندازد.","فشار ملایم کف قابلمه ته‌دیگ یکدست می‌سازد.","برنج را کمی زنده‌تر از پلوی معمولی آبکش کنید و آرام مخلوط کنید (اکالا).","کدو را به دیوارهٔ قابلمه نچسبانید تا ته‌چین راحت برگردد."],"en":["Dry the zucchini completely before frying so the tahchin does not get watery.","Gentle pressing on the base gives an even crust.","Drain the rice a bit firmer than for normal polo and fold gently (Okala).","Keep the zucchini off the pot wall so the tahchin releases cleanly."],"ar":["جفف الكوسا تمامًا قبل القلي كي لا يصير التهتشين مائيًا.","الضغط الخفيف على القاع يعطي قشرة متساوية.","صفِّ الأرز أقسى قليلًا من الأرز العادي واخلطه بلطف.","أبعد الكوسا عن جدار القدر ليسهل قلب التهتشين."]},"cover":{"src":"/recipes/thchyn-kdw/cover.webp","alt":"ته‌چین کدو برگردانده در دیس گرد با ته‌دیگ طلایی و برشی که لایهٔ کدو و برنج زعفرانی را نشان می‌دهد","width":1600,"height":1200},"serving":{"src":"/recipes/thchyn-kdw/serving.webp","alt":"برش ته‌چین کدو در بشقاب با کاسهٔ ماست و خیار و سالاد شیرازی","width":1200,"height":1500}},{"id":"dolma","country":"IQ","slugs":{"fa":"دلمه-عراقی","en":"iraqi-dolma","ar":"دولمة-عراقية"},"title":{"fa":"دلمهٔ عراقی","en":"Iraqi Dolma (Mixed Stuffed Vegetables)","ar":"دولمة عراقية (خضار محشية مشكلة)"},"summary":{"fa":"برگ مو، پیاز، بادمجان، کدو و فلفل که با برنج، گوشت چرخ‌کرده، سبزی، رب انار و تمر هندی پر می‌شوند و همه با هم در یک قابلمه، روی دنده‌های بره، آرام می‌پزند و در پایان برگردانده می‌شوند.","en":"Vine leaves, onions, aubergines, courgettes and peppers stuffed with rice, minced meat, herbs, pomegranate molasses and tamarind, cooked together slowly in one pot over lamb ribs and turned out at the end.","ar":"ورق عنب وبصل وباذنجان وكوسا وفلفل تُحشى بالرز واللحم المفروم والخضرة ودبس الرمان والتمر الهندي، وتُطبخ معًا ببطء في قدر واحد فوق أضلاع الغنم ثم تُقلب عند التقديم."},"intro":{"fa":"دولمه در سراسر عراق، از بصره تا اربیل، غذای مهمانی و جمعه‌های خانوادگی است. ویژگی نسخهٔ عراقی، ترکیب ترش‌وشیرین مایه با تمر هندی، رب انار، لیمو و کمی شکر، و چیدن انواع سبزیجات در یک قابلمه است. در این دستور گوشت چرخ‌کرده و دنده اختیاری است؛ سومریه نسخهٔ بی‌گوشت را هم می‌دهد.","en":"Dolma is a dish for guests and family Fridays across Iraq, from Basra to Erbil. The Iraqi version is marked by a sweet-sour filling of tamarind, pomegranate molasses, lemon and a little sugar, and by packing many vegetables into one pot. Here the minced meat and ribs are optional; Alsumaria also gives a meatless version.","ar":"الدولمة طبق الضيافة وأيام الجمعة العائلية في أنحاء العراق من البصرة إلى أربيل. يميز النسخة العراقية طعم الحشوة الحامض الحلو من التمر الهندي ودبس الرمان والليمون وقليل من السكر، ورصّ أنواع الخضار في قدر واحد. اللحم المفروم والأضلاع هنا اختيارية، وتقدم السومرية نسخة بلا لحم أيضًا."},"seoTitle":{"fa":"دلمه عراقی؛ طرز تهیه دلمه مخلوط برگ مو و سبزیجات","en":"Iraqi Dolma Recipe (Mixed Stuffed Vegetables)","ar":"دولمة عراقية: طريقة عمل الدولمة العراقية المشكلة"},"seoDescription":{"fa":"طرز تهیه دلمه عراقی برای ۶ نفر: برگ مو، پیاز، بادمجان، کدو و فلفل پر از برنج، گوشت، سبزی، رب انار و تمر هندی، پخته روی دنده بره؛ حدود ۳ ساعت.","en":"Iraqi dolma for 6: vine leaves, onions, aubergines, courgettes and peppers stuffed with rice, meat, herbs, tamarind and pomegranate molasses. About 3 h.","ar":"طريقة عمل الدولمة العراقية لستة أشخاص: ورق عنب وبصل وباذنجان وكوسا وفلفل محشوة بالرز واللحم والخضرة ودبس الرمان والتمر الهندي فوق أضلاع الغنم؛ نحو ٣ ساعات."},"servings":6,"prep":95,"cook":80,"rest":10,"total":185,"oven":null,"difficulty":{"fa":"سخت","en":"Hard","ar":"صعب"},"showNutrition":false,"ingredients":[{"name":{"fa":"برنج دانه‌کوتاه یا عنبر","en":"Short-grain or amber rice","ar":"رز قصير الحبة أو عنبر"},"amount":"2","unit":"پیمانه","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"شسته و آب‌کشیده.","en":"Washed and drained.","ar":"مغسول ومصفى."}},{"name":{"fa":"گوشت چرخ‌کردهٔ گوسفند یا گوساله (حلال)","en":"Minced lamb or beef (halal)","ar":"لحم غنم أو عجل مفروم (حلال)"},"amount":"300","unit":"گرم","optional":true,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"اختیاری؛ برای نسخهٔ گیاهی حذف کنید.","en":"Optional; leave out for a vegetarian version.","ar":"اختياري؛ يُحذف للنسخة النباتية."}},{"name":{"fa":"پیاز ریز‌خردشده","en":"Finely chopped onion","ar":"بصل مفروم ناعمًا"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"گوجه‌فرنگی ریز‌خردشده","en":"Finely chopped tomato","ar":"طماطم مفرومة ناعمًا"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"جعفری ریز‌خردشده","en":"Chopped parsley","ar":"بقدونس مفروم"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شوید و نعناع تازهٔ خردشده","en":"Chopped fresh dill and mint","ar":"شبنت ونعناع طازج مفروم"},"amount":"0.5","unit":"پیمانه","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"سیر رنده‌شده","en":"Grated garlic","ar":"ثوم مبشور"},"amount":"4","unit":"حبه","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"رب گوجه‌فرنگی","en":"Tomato paste","ar":"معجون الطماطم"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"رب انار","en":"Pomegranate molasses","ar":"دبس الرمان"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"تمر هندی","en":"Tamarind pulp","ar":"تمر هندي"},"amount":"30","unit":"گرم","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"در ۱۲۰ میلی‌لیتر آب داغ خیس و صاف‌شده.","en":"Soaked in 120 ml hot water and strained.","ar":"منقوع في ١٢٠ مل ماء ساخن ومصفى."}},{"name":{"fa":"لیمو عمانی کوبیده (نومی بصره)","en":"Ground dried lime (noomi Basra)","ar":"نومي بصرة مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"ادویهٔ دلمه یا بهارات","en":"Dolma spice or baharat","ar":"بهارات الدولمة"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شکر","en":"Sugar","ar":"سكر"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"60","unit":"میلی‌لیتر","optional":false,"group":{"fa":"مایهٔ دلمه","en":"Filling","ar":"الحشوة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"برگ موی تازه یا آب‌نمکی","en":"Fresh or brined vine leaves","ar":"ورق عنب طازج أو مملح"},"amount":"250","unit":"گرم","optional":false,"group":{"fa":"سبزیجات برای پر کردن","en":"Vegetables to stuff","ar":"الخضار للحشو"},"note":{"fa":"حدود ۴۰ برگ؛ برگ چغندر هم می‌شود.","en":"About 40 leaves; chard leaves also work.","ar":"نحو ٤٠ ورقة؛ يصلح ورق السلق أيضًا."}},{"name":{"fa":"پیاز متوسط","en":"Medium onions","ar":"بصل متوسط"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"سبزیجات برای پر کردن","en":"Vegetables to stuff","ar":"الخضار للحشو"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"بادمجان کوچک","en":"Small aubergines","ar":"باذنجان صغير"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"سبزیجات برای پر کردن","en":"Vegetables to stuff","ar":"الخضار للحشو"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"کدو سبز کوچک","en":"Small courgettes","ar":"كوسا صغيرة"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"سبزیجات برای پر کردن","en":"Vegetables to stuff","ar":"الخضار للحشو"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل دلمه‌ای سبز","en":"Green bell peppers","ar":"فلفل أخضر"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"سبزیجات برای پر کردن","en":"Vegetables to stuff","ar":"الخضار للحشو"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"گوجه‌فرنگی سفت","en":"Firm tomatoes","ar":"طماطم صلبة"},"amount":"3","unit":"عدد","optional":true,"group":{"fa":"سبزیجات برای پر کردن","en":"Vegetables to stuff","ar":"الخضار للحشو"},"note":{"fa":"اختیاری، برای لایهٔ آخر.","en":"Optional, for the top layer.","ar":"اختيارية للطبقة الأخيرة."}},{"name":{"fa":"دنده یا راستهٔ استخوان‌دار گوسفند (حلال)","en":"Lamb ribs or chops (halal)","ar":"أضلاع أو كستليتة غنم (حلال)"},"amount":"500","unit":"گرم","optional":true,"group":{"fa":"کف قابلمه","en":"Pot base","ar":"قاع القدر"},"note":{"fa":"اختیاری.","en":"Optional.","ar":"اختياري."}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"کف قابلمه","en":"Pot base","ar":"قاع القدر"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب جوش","en":"Boiling water","ar":"ماء مغلي"},"amount":"750","unit":"میلی‌لیتر","optional":false,"group":{"fa":"آب پخت","en":"Cooking liquid","ar":"سائل الطبخ"},"note":{"fa":"به اندازه‌ای که حدود ۱ سانتی‌متر روی دلمه‌ها را بپوشاند.","en":"Enough to cover the dolma by about 1 cm.","ar":"بقدر ما يغطي الدولمة بنحو ١ سم."}},{"name":{"fa":"رب گوجه‌فرنگی","en":"Tomato paste","ar":"معجون الطماطم"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"آب پخت","en":"Cooking liquid","ar":"سائل الطبخ"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب لیمو ترش تازه","en":"Fresh lemon juice","ar":"عصير ليمون طازج"},"amount":"60","unit":"میلی‌لیتر","optional":false,"group":{"fa":"آب پخت","en":"Cooking liquid","ar":"سائل الطبخ"},"note":{"fa":"حدود ۲ لیمو.","en":"About 2 lemons.","ar":"نحو ليمونتين."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"آب پخت","en":"Cooking liquid","ar":"سائل الطبخ"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده کردن مایه","en":"Make the filling","ar":"تحضير الحشوة"},"text":{"fa":"۱) تمر هندی را در ۱۲۰ میلی‌لیتر آب داغ بخیسانید.\\n۲) در کاسهٔ بزرگ برنج، گوشت (اگر استفاده می‌کنید)، پیاز، گوجه، سبزی‌ها و سیر را بریزید.\\n۳) تمر هندی را با دست فشار دهید، صاف کنید و آبش را به کاسه بریزید.\\n۴) رب گوجه، رب انار، لیمو عمانی، ادویه، فلفل، نمک، شکر و روغن را اضافه کنید و با دست خوب مخلوط کنید تا یکدست شود.","en":"1) Soak the tamarind in 120 ml hot water.\\n2) In a large bowl put the rice, meat (if using), onion, tomato, herbs and garlic.\\n3) Squeeze the tamarind, strain it and add the liquid to the bowl.\\n4) Add the tomato paste, pomegranate molasses, dried lime, spices, pepper, salt, sugar and oil and mix well by hand until even.","ar":"١) انقع التمر الهندي في ١٢٠ مل ماء ساخن.\\n٢) ضع في وعاء كبير الرز واللحم (إن استُخدم) والبصل والطماطم والخضرة والثوم.\\n٣) اعصر التمر الهندي وصفّه وأضف سائله إلى الوعاء.\\n٤) أضف معجون الطماطم ودبس الرمان والنومي بصرة والبهارات والفلفل والملح والسكر والزيت واخلط باليد جيدًا حتى يتجانس."},"time":15,"image":{"src":"/recipes/dolma/step-01.webp","alt":"کاسهٔ مایهٔ دلمهٔ عراقی با برنج، گوشت، سبزی و رب انار","width":1200,"height":900}},{"n":2,"title":{"fa":"نرم کردن برگ مو و پیاز","en":"Soften the leaves and onions","ar":"تطرية ورق العنب والبصل"},"text":{"fa":"۱) در قابلمهٔ متوسط آب را روی حرارت زیاد به جوش بیاورید.\\n۲) برگ‌ها را ۲ تا ۳ دقیقه در آب جوش بگذارید تا رنگشان تیره و نرم شود؛ آبکش کنید.\\n۳) پیازها را پوست بگیرید، یک برش طولی تا مرکز بزنید و ۵ دقیقه در همان آب بجوشانید تا لایه‌ها نرم شوند؛ لایه‌ها را با احتیاط جدا کنید.","en":"1) Bring water to a boil in a medium pot over high heat.\\n2) Drop in the leaves for 2–3 minutes until darker and soft; drain.\\n3) Peel the onions, make one lengthwise cut to the centre and boil 5 minutes in the same water until the layers soften; gently peel the layers apart.","ar":"١) اغلِ الماء في قدر متوسط على نار عالية.\\n٢) ضع الأوراق في الماء المغلي ٢ إلى ٣ دقائق حتى يغمق لونها وتطرى؛ صفّها.\\n٣) قشّر البصل واشقه شقًا طوليًا حتى الوسط واسلقه ٥ دقائق في الماء نفسه حتى تطرى طبقاته، ثم افصلها بحذر."},"time":10,"image":{"src":"/recipes/dolma/step-02.webp","alt":"برگ مو در آب جوش و لایه‌های پیاز جداشده برای دلمهٔ عراقی","width":1200,"height":900}},{"n":3,"title":{"fa":"خالی کردن سبزیجات","en":"Hollow the vegetables","ar":"حفر الخضار"},"text":{"fa":"۱) سر کدو و بادمجان را ببرید و نگه دارید؛ با قاشق یا ابزار مخصوص، داخلشان را خالی کنید تا دیواره حدود نیم سانتی‌متر بماند.\\n۲) کلاهک فلفل‌ها را ببرید و دانه‌ها را دربیاورید.\\n۳) اگر گوجه دارید، سرش را ببرید و داخلش را با قاشق خالی کنید؛ مغز گوجه را خرد کنید و به مایه اضافه کنید.\\n۴) داخل سبزیجات را کمی نمک بزنید.","en":"1) Cut the tops off the courgettes and aubergines and keep them; scoop out the inside with a spoon or corer, leaving walls about \xbd cm thick.\\n2) Cut the caps off the peppers and remove the seeds.\\n3) If using tomatoes, cut off the tops and scoop out the flesh; chop it and add to the filling.\\n4) Lightly salt the insides.","ar":"١) اقطع رؤوس الكوسا والباذنجان واحتفظ بها؛ احفرها بملعقة أو محفرة مع ترك جدار بسمك نصف سم تقريبًا.\\n٢) اقطع رؤوس الفلفل وأزل البذور.\\n٣) إن استخدمت الطماطم فاقطع رؤوسها وأفرغها بملعقة، وافرم لبها وأضفه إلى الحشوة.\\n٤) رش قليلًا من الملح داخل الخضار."},"time":25,"image":{"src":"/recipes/dolma/step-03.webp","alt":"کدو، بادمجان، فلفل و گوجهٔ خالی‌شده با کلاهک‌ها برای دلمهٔ عراقی","width":1200,"height":900}},{"n":4,"title":{"fa":"پر کردن و پیچیدن","en":"Stuff and roll","ar":"الحشو واللف"},"text":{"fa":"۱) سبزیجات را فقط تا سه‌چهارم پر کنید (برنج باد می‌کند) و کلاهکشان را بگذارید.\\n۲) برگ مو را با سمت رگه‌دار رو به بالا پهن کنید، ۱ قاشق غذاخوری مایه نزدیک دم بگذارید، دو طرف را تا کنید و محکم لوله کنید.\\n۳) در هر لایهٔ پیاز کمی مایه بگذارید و دوباره به شکل پیاز بپیچید.","en":"1) Fill the vegetables only three-quarters full (the rice swells) and put their tops back on.\\n2) Lay a vine leaf vein side up, put 1 tbsp filling near the stem, fold in both sides and roll tightly.\\n3) Put a little filling in each onion layer and roll it back into an onion shape.","ar":"١) احشُ الخضار حتى ثلاثة أرباعها فقط (لأن الرز ينتفخ) وأعد رؤوسها.\\n٢) افرد ورقة العنب والعروق إلى الأعلى، وضع ملعقة كبيرة من الحشوة قرب العنق، واثنِ الجانبين ولفها بإحكام.\\n٣) ضع قليلًا من الحشوة في كل طبقة بصل وأعد لفها على شكل بصلة."},"time":40,"image":{"src":"/recipes/dolma/step-04.webp","alt":"دست‌هایی که برگ مو را با مایهٔ دلمهٔ عراقی لوله می‌کنند","width":1200,"height":900}},{"n":5,"title":{"fa":"تفت دنده‌ها","en":"Brown the ribs","ar":"تحمير الأضلاع"},"text":{"fa":"۱) روغن را در قابلمهٔ بزرگ و پهن (حدود ۲۶ سانتی‌متر، ۶ لیتری) روی حرارت متوسط داغ کنید.\\n۲) دنده‌ها را با کمی نمک و فلفل بگذارید و هر طرف ۴ تا ۵ دقیقه سرخ کنید تا رنگشان برگردد. بدون گوشت: این مرحله را رد کنید و کف قابلمه را با چند برش سیب‌زمینی یا گوجه بپوشانید.","en":"1) Heat the oil in a large wide pot (about 26 cm, 6 L) over medium heat.\\n2) Add the ribs with a little salt and pepper and brown 4–5 minutes per side. Meatless: skip this and line the base with a few potato or tomato slices.","ar":"١) سخّن الزيت في قدر كبير عريض (نحو ٢٦ سم، ٦ لترات) على نار متوسطة.\\n٢) ضع الأضلاع مع قليل من الملح والفلفل وحمّرها ٤ إلى ٥ دقائق لكل جهة. بلا لحم: تخطَّ هذه الخطوة وغطِّ القاع بشرائح بطاطا أو طماطم."},"time":10,"image":{"src":"/recipes/dolma/step-05.webp","alt":"دنده‌های بره در حال سرخ شدن در کف قابلمه برای دلمهٔ عراقی","width":1200,"height":900}},{"n":6,"title":{"fa":"چیدن در قابلمه","en":"Pack the pot","ar":"رص القدر"},"text":{"fa":"۱) قابلمه را از روی حرارت بردارید.\\n۲) اول پیازها را روی دنده‌ها بچینید، سپس بادمجان، کدو و فلفل، بعد برگ‌های پیچیده و در آخر گوجه‌ها.\\n۳) محکم و بدون فاصله بچینید تا در پخت باز نشوند.","en":"1) Take the pot off the heat.\\n2) Arrange the onions over the ribs first, then the aubergines, courgettes and peppers, then the rolled leaves and finally the tomatoes.\\n3) Pack snugly with no gaps so nothing opens while cooking.","ar":"١) ارفع القدر عن النار.\\n٢) رصّ البصل أولًا فوق الأضلاع، ثم الباذنجان والكوسا والفلفل، ثم ورق العنب الملفوف، وأخيرًا الطماطم.\\n٣) رصّها بإحكام دون فراغات حتى لا تنفتح أثناء الطبخ."},"time":10,"image":{"src":"/recipes/dolma/step-06.webp","alt":"قابلمهٔ پر از پیاز، بادمجان، فلفل و برگ موی پیچیدهٔ دلمهٔ عراقی","width":1200,"height":900}},{"n":7,"title":{"fa":"افزودن آب و جوش آمدن","en":"Add liquid and bring to a boil","ar":"إضافة الماء والغليان"},"text":{"fa":"۱) رب گوجه، آب لیمو و نمک را در آب جوش حل کنید و آرام کنار قابلمه بریزید تا حدود ۱ سانتی‌متر روی دلمه‌ها را بپوشاند.\\n۲) یک بشقاب مقاوم به حرارت را وارونه روی دلمه‌ها بگذارید تا ثابت بمانند.\\n۳) قابلمه را روی حرارت زیاد بگذارید تا به جوش بیاید.","en":"1) Stir the tomato paste, lemon juice and salt into the boiling water and pour it gently down the side of the pot until the dolma is covered by about 1 cm.\\n2) Put a heatproof plate upside down on top to hold everything in place.\\n3) Bring to a boil over high heat.","ar":"١) ذوّب معجون الطماطم وعصير الليمون والملح في الماء المغلي واسكبه برفق على جانب القدر حتى يغطي الدولمة بنحو ١ سم.\\n٢) ضع صحنًا مقاومًا للحرارة مقلوبًا فوقها لتثبيتها.\\n٣) ارفع النار إلى عالية حتى يغلي."},"time":10,"image":{"src":"/recipes/dolma/step-07.webp","alt":"ریختن آب گوجه و لیمو روی دلمهٔ عراقی و بشقاب وارونه روی آن","width":1200,"height":900}},{"n":8,"title":{"fa":"پخت آرام","en":"Simmer","ar":"الطهي على نار هادئة"},"text":{"fa":"۱) وقتی جوش آمد، در قابلمه را بگذارید و حرارت را کم کنید.\\n۲) حدود ۵۰ دقیقه بپزید تا آب تقریباً جذب شود.\\n۳) نشانهٔ پخت: برنج داخل یک برگ کاملاً نرم است و سبزیجات با چاقو به‌راحتی سوراخ می‌شوند. اگر آب زود تمام شد و برنج هنوز سفت بود، ۱۲۰ میلی‌لیتر آب جوش اضافه کنید.","en":"1) Once boiling, cover and turn the heat to low.\\n2) Cook about 50 minutes until the liquid is almost absorbed.\\n3) Done when the rice inside a leaf is fully soft and a knife slides easily into the vegetables. If the liquid runs out while the rice is still firm, add 120 ml boiling water.","ar":"١) عند الغليان غطِّ القدر واخفض النار.\\n٢) اطبخ نحو ٥٠ دقيقة حتى يُمتص الماء تقريبًا.\\n٣) تنضج حين يصبح الرز داخل ورقة طريًا تمامًا وتدخل السكين في الخضار بسهولة. إن نفد الماء والرز ما زال قاسيًا فأضف ١٢٠ مل ماء مغلي."},"time":50,"image":{"src":"/recipes/dolma/step-08.webp","alt":"قابلمهٔ دربستهٔ دلمهٔ عراقی روی شعلهٔ کم","width":1200,"height":900}},{"n":9,"title":{"fa":"استراحت","en":"Rest","ar":"الراحة"},"text":{"fa":"قابلمه را خاموش کنید و ۱۰ دقیقه با در بسته بگذارید بماند تا دلمه‌ها جا بیفتند و هنگام برگرداندن از هم نپاشند (زمان استراحت).","en":"Turn off the heat and leave covered for 10 minutes so the dolma settles and holds together when turned out (rest time).","ar":"أطفئ النار واترك القدر مغطى ١٠ دقائق لتتماسك الدولمة ولا تتفكك عند القلب (وقت الراحة)."},"time":10,"image":{"src":"/recipes/dolma/step-09.webp","alt":"قابلمهٔ دلمهٔ عراقی خاموش و دربسته در حال استراحت","width":1200,"height":900}},{"n":10,"title":{"fa":"برگرداندن و سرو","en":"Turn out and serve","ar":"القلب والتقديم"},"text":{"fa":"۱) بشقاب داخل قابلمه را بردارید.\\n۲) سینی گردی بزرگ‌تر از دهانهٔ قابلمه روی آن بگذارید، با دستکش آشپزخانه هر دو را محکم بگیرید و با یک حرکت برگردانید.\\n۳) قابلمه را آرام بالا بکشید و داغ سرو کنید.","en":"1) Remove the plate from the pot.\\n2) Put a round tray larger than the pot over it, hold both firmly with oven gloves and flip in one movement.\\n3) Lift the pot off slowly and serve hot.","ar":"١) ارفع الصحن من داخل القدر.\\n٢) ضع صينية مستديرة أكبر من فوهة القدر فوقه، وأمسك الاثنين بقفازات المطبخ واقلبهما بحركة واحدة.\\n٣) ارفع القدر ببطء وقدّمها ساخنة."},"time":5,"image":{"src":"/recipes/dolma/step-10.webp","alt":"دلمهٔ عراقی برگردانده‌شده در سینی گرد با سبزیجات پرشده و دنده","width":1200,"height":900}}],"tips":{"fa":["ترشی مایه را پیش از پر کردن بچشید؛ باید کمی تندتر از دلخواه باشد چون برنج آن را ملایم می‌کند.","اگر فقط برگ مو دارید، همین مایه برای حدود ۷۰ برگ کافی است.","برگ‌های پاره را کف قابلمه بچینید تا دلمه نچسبد."],"en":["Taste the filling before stuffing; it should be a bit sharper than you like, as the rice mellows it.","With vine leaves only, this filling makes about 70 rolls.","Line the base with torn leaves to stop sticking."],"ar":["تذوّق الحشوة قبل الحشو؛ يجب أن تكون أحمض قليلًا مما تحب لأن الرز يلطّفها.","إن استخدمت ورق العنب فقط فالحشوة تكفي نحو ٧٠ لفة.","ضع الأوراق الممزقة في القاع لمنع الالتصاق."]},"cover":{"src":"/recipes/dolma/cover.webp","alt":"دلمهٔ عراقی برگردانده در سینی گرد با پیاز، بادمجان، فلفل و برگ موی پرشده","width":1600,"height":1200},"serving":{"src":"/recipes/dolma/serving.webp","alt":"بشقاب دلمهٔ عراقی مخلوط با کاسهٔ ماست کنار آن","width":1200,"height":1500}},{"id":"kahi-gaimar","country":"IQ","slugs":{"fa":"کاهی-با-قیمر","en":"kahi-gaimar","ar":"كاهي-وقيمر"},"title":{"fa":"کاهی با قیمر","en":"Kahi with Gaimar (Iraqi Layered Pastry with Clotted Cream)","ar":"كاهي وقيمر"},"summary":{"fa":"نان شیرینی لایه‌لایه و ترد که از خمیر بسیار نازک و کره ساخته می‌شود، داغ از فر شیره می‌خورد و با قیمر (سرشیر غلیظ عراقی) صبحانه‌ای جشنی می‌سازد.","en":"A flaky, crisp layered pastry made from paper-thin dough and butter, soaked in syrup straight from the oven and eaten with gaimar (thick Iraqi clotted cream) for a festive breakfast.","ar":"فطيرة مورقة مقرمشة من عجين رقيق جدًا وزبدة، تُسقى بالشيرة فور خروجها من الفرن وتؤكل مع القيمر العراقي في فطور احتفالي."},"intro":{"fa":"کاهی و قیمر صبحانهٔ جمعه و صبح عید در سراسر عراق است. در حدیثه (انبار) شب عید قیمر در بازار تمام می‌شود و در تکریت مردم پس از نماز عید دسته‌جمعی کاهی و قیمر می‌خورند یا به رستوران‌های ویژهٔ آن می‌روند. قیمر را معمولاً آماده می‌خرند؛ این دستور ساختن خود کاهی را آموزش می‌دهد.","en":"Kahi and gaimar is the Friday and Eid-morning breakfast across Iraq. In Haditha (Anbar) gaimar sells out on Eid eve, and in Tikrit people share kahi and gaimar after the Eid prayer or head to specialist restaurants. Gaimar is usually bought ready; this recipe teaches the kahi itself.","ar":"الكاهي والقيمر فطور الجمعة وصباح العيد في أنحاء العراق. في حديثة (الأنبار) ينفد القيمر من الأسواق ليلة العيد، وفي تكريت يتناول الناس الكاهي والقيمر جماعيًا بعد صلاة العيد أو في مطاعم مختصة. يُشترى القيمر جاهزًا عادة، وهذه الوصفة لصنع الكاهي نفسه."},"seoTitle":{"fa":"کاهی با قیمر؛ طرز تهیه نان شیرینی لایه‌لایه عراقی","en":"Kahi with Gaimar Recipe (Iraqi Layered Pastry)","ar":"كاهي وقيمر: طريقة عمل الكاهي العراقي بالشيرة"},"seoDescription":{"fa":"طرز تهیه کاهی با قیمر برای ۶ نفر: خمیر بسیار نازک و کره، لایه‌لایه و ترد در فر، با شیرهٔ سرد و قیمر برای صبحانه؛ حدود ۲.۵ ساعت با استراحت خمیر.","en":"Kahi with gaimar for 6: paper-thin buttered dough baked flaky and crisp, soaked in cold syrup and served with clotted cream. About 2.5 h incl. dough rests.","ar":"طريقة عمل الكاهي والقيمر لستة أشخاص: عجين رقيق جدًا بالزبدة يُخبز مورقًا مقرمشًا، ويُسقى بالشيرة الباردة ويُقدم مع القيمر للفطور؛ نحو ساعتين ونصف."},"servings":6,"prep":50,"cook":12,"rest":75,"total":137,"oven":200,"difficulty":{"fa":"سخت","en":"Hard","ar":"صعب"},"showNutrition":false,"ingredients":[{"name":{"fa":"آرد سفید","en":"All-purpose flour","ar":"طحين أبيض"},"amount":"4.5","unit":"پیمانه","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"حدود ۵۸۰ گرم، الک‌شده.","en":"About 580 g, sifted.","ar":"نحو ٥٨٠ غرامًا منخولًا."}},{"name":{"fa":"آب ولرم","en":"Warm water","ar":"ماء دافئ"},"amount":"1.5","unit":"پیمانه","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"بسته به آرد کمی کم یا زیاد.","en":"A little more or less depending on the flour.","ar":"أقل أو أكثر قليلًا حسب الطحين."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع یا روغن حیوانی آب‌شده","en":"Oil or melted ghee","ar":"زيت أو سمن مذوب"},"amount":"0.5","unit":"پیمانه","optional":false,"group":{"fa":"چربی لایه‌ها","en":"Fat for layering","ar":"دهن الطبقات"},"note":{"fa":"برای چرب کردن چانه‌ها و سطح کار.","en":"For coating the dough balls and the work surface.","ar":"لدهن الكرات وسطح العمل."}},{"name":{"fa":"کرهٔ آب‌شده","en":"Melted butter","ar":"زبدة مذوبة"},"amount":"100","unit":"گرم","optional":false,"group":{"fa":"چربی لایه‌ها","en":"Fat for layering","ar":"دهن الطبقات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شکر","en":"Sugar","ar":"سكر"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"شیره","en":"Syrup","ar":"الشيرة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"1","unit":"پیمانه","optional":false,"group":{"fa":"شیره","en":"Syrup","ar":"الشيرة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"چوب دارچین","en":"Cinnamon stick","ar":"عود قرفة"},"amount":"1","unit":"عدد","optional":true,"group":{"fa":"شیره","en":"Syrup","ar":"الشيرة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"قیمر عراقی یا سرشیر غلیظ پاستوریزه","en":"Iraqi gaimar or thick pasteurised clotted cream","ar":"قيمر عراقي أو قشطة كثيفة مبسترة"},"amount":"250","unit":"گرم","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"خمیر کردن","en":"Make the dough","ar":"العجن"},"text":{"fa":"۱) آرد را الک کنید و با نمک در کاسهٔ بزرگ مخلوط کنید.\\n۲) آب ولرم را کم‌کم اضافه کنید و هم بزنید.\\n۳) روی سطح کار ۱۰ دقیقه ورز دهید تا خمیر صاف، کشسان و غیرچسبناک شود؛ وقتی بکشید باید مثل لاستیک کش بیاید.","en":"1) Sift the flour and mix with the salt in a large bowl.\\n2) Add the warm water gradually, stirring.\\n3) Knead on the counter for 10 minutes until smooth, elastic and not sticky; it should stretch like rubber.","ar":"١) انخل الطحين واخلطه مع الملح في وعاء كبير.\\n٢) أضف الماء الدافئ تدريجيًا مع التحريك.\\n٣) اعجن على سطح العمل ١٠ دقائق حتى تصبح العجينة ناعمة مطاطية لا تلتصق."},"time":12,"image":{"src":"/recipes/kahi-gaimar/step-01.webp","alt":"ورز دادن خمیر صاف و کشسان کاهی روی سطح کار","width":1200,"height":900}},{"n":2,"title":{"fa":"استراحت اول","en":"First rest","ar":"الراحة الأولى"},"text":{"fa":"روی خمیر را بپوشانید و ۱۵ دقیقه بگذارید استراحت کند (زمان استراحت).","en":"Cover the dough and rest 15 minutes (rest time).","ar":"غطِّ العجينة واتركها ترتاح ١٥ دقيقة (وقت الراحة)."},"time":15,"image":{"src":"/recipes/kahi-gaimar/step-02.webp","alt":"گلولهٔ خمیر کاهی زیر پارچه","width":1200,"height":900}},{"n":3,"title":{"fa":"چانه گرفتن","en":"Divide the dough","ar":"التقطيع"},"text":{"fa":"۱) خمیر را لوله کنید و به ۷ قسمت مساوی ببرید.\\n۲) هر تکه را گرد کنید و در سینی چرب‌شده بگذارید.\\n۳) روی همه را با روغن کاملاً چرب کنید.","en":"1) Roll the dough into a log and cut into 7 equal pieces.\\n2) Round each piece and set on an oiled tray.\\n3) Coat them all well with the oil.","ar":"١) لفّ العجينة على شكل رول وقطّعها ٧ قطع متساوية.\\n٢) كوّر كل قطعة وضعها في صينية مدهونة.\\n٣) ادهن الكرات كلها بالزيت جيدًا."},"time":5,"image":{"src":"/recipes/kahi-gaimar/step-03.webp","alt":"هفت چانهٔ چرب کاهی در سینی","width":1200,"height":900}},{"n":4,"title":{"fa":"استراحت دوم","en":"Second rest","ar":"الراحة الثانية"},"text":{"fa":"روی سینی را بپوشانید و ۳۰ دقیقه بگذارید چانه‌ها نرم شوند تا راحت نازک شوند (زمان استراحت).","en":"Cover the tray and rest 30 minutes so the balls relax and stretch easily (rest time).","ar":"غطِّ الصينية واتركها ٣٠ دقيقة لترتخي الكرات وتنفرد بسهولة (وقت الراحة)."},"time":30,"image":{"src":"/recipes/kahi-gaimar/step-04.webp","alt":"سینی پوشیدهٔ چانه‌های کاهی","width":1200,"height":900}},{"n":5,"title":{"fa":"درست کردن شیره","en":"Make the syrup","ar":"تحضير الشيرة"},"text":{"fa":"هم‌زمان با استراحت دوم (جدا شمرده نشده):\\n۱) شکر، آب و دارچین را در قابلمهٔ کوچک روی حرارت متوسط بگذارید و هم بزنید تا شکر حل شود.\\n۲) از زمان جوش ۵ دقیقه بجوشانید؛ شیره باید رقیق مثل آب بماند.\\n۳) دارچین را بردارید و بگذارید کاملاً سرد شود.","en":"During the second rest (not counted separately):\\n1) Put the sugar, water and cinnamon in a small pot over medium heat and stir until the sugar dissolves.\\n2) Boil 5 minutes; the syrup should stay thin, like water.\\n3) Remove the cinnamon and let it cool completely.","ar":"أثناء الراحة الثانية (لا يُحسب منفصلًا):\\n١) ضع السكر والماء والقرفة في قدر صغير على نار متوسطة وحرّك حتى يذوب السكر.\\n٢) اتركه يغلي ٥ دقائق، ويجب أن تبقى الشيرة خفيفة كالماء.\\n٣) أخرج القرفة واتركها تبرد تمامًا."},"time":10,"image":{"src":"/recipes/kahi-gaimar/step-05.webp","alt":"قابلمهٔ کوچک شیرهٔ رقیق و شفاف کاهی با چوب دارچین","width":1200,"height":900}},{"n":6,"title":{"fa":"نازک کردن و تا زدن","en":"Stretch and fold","ar":"الفرد والطي"},"text":{"fa":"۱) سطح کار و دست‌ها را چرب کنید.\\n۲) یک چانه را با کف دست و انگشت‌ها از وسط به بیرون پهن کنید تا آن‌قدر نازک شود که پشتش پیدا باشد (حدود ۴۰ سانتی‌متر). پارگی کوچک اشکالی ندارد.\\n۳) ۱ قاشق غذاخوری کرهٔ آب‌شده رویش بمالید.\\n۴) دو طرف را روی هم تا کنید تا مستطیل شود، بعد دو سر دیگر را تا کنید تا مربعی حدود ۱۲ سانتی‌متری بسازید.\\n۵) در سینی چرب بگذارید و با بقیهٔ چانه‌ها تکرار کنید.","en":"1) Oil the counter and your hands.\\n2) Spread one ball from the centre outward with your palms and fingers until thin enough to see through (about 40 cm). Small tears are fine.\\n3) Brush with 1 tablespoon melted butter.\\n4) Fold two sides over to make a rectangle, then fold the ends to make a square of about 12 cm.\\n5) Place on an oiled tray and repeat with the rest.","ar":"١) ادهن سطح العمل ويديك.\\n٢) افرد كرة من الوسط إلى الخارج بالكفين والأصابع حتى ترق ويظهر ما تحتها (نحو ٤٠ سم)، ولا بأس بالثقوب الصغيرة.\\n٣) ادهنها بملعقة كبيرة من الزبدة المذوبة.\\n٤) اطوِ الطرفين لتصبح مستطيلًا ثم اطوِ الطرفين الآخرين لتصبح مربعًا بنحو ١٢ سم.\\n٥) ضعها في صينية مدهونة وكرر مع الباقي."},"time":25,"image":{"src":"/recipes/kahi-gaimar/step-06.webp","alt":"خمیر بسیار نازک کاهی روی سطح چرب که به شکل مربع تا می‌شود","width":1200,"height":900}},{"n":7,"title":{"fa":"استراحت سوم","en":"Third rest","ar":"الراحة الثالثة"},"text":{"fa":"مربع‌ها را ۱۵ دقیقه در سینی چرب بگذارید (زمان استراحت).","en":"Rest the squares on the oiled tray for 15 minutes (rest time).","ar":"اترك المربعات في الصينية المدهونة ١٥ دقيقة (وقت الراحة)."},"time":15,"image":{"src":"/recipes/kahi-gaimar/step-07.webp","alt":"مربع‌های تاشدهٔ کاهی در سینی چرب","width":1200,"height":900}},{"n":8,"title":{"fa":"پهن کردن و آماده‌سازی فر","en":"Press out and heat the oven","ar":"الضغط وتسخين الفرن"},"text":{"fa":"۱) فر را روی ۲۰۰ درجه با حرارت پایین (المنت زیر) روشن کنید.\\n۲) هر مربع را با فشار سبک و سریع انگشت‌ها از دو طرف کمی بزرگ‌تر کنید (حدود ۱۵ سانتی‌متر).\\n۳) در سینی فر با کاغذ روغنی بچینید و ۱۵ دقیقه بگذارید بماند تا فر داغ شود.","en":"1) Heat the oven to 200\xb0C with bottom heat.\\n2) Press each square lightly and quickly from both sides with your fingers to enlarge it a little (about 15 cm).\\n3) Place on a baking tray lined with paper and leave 15 minutes while the oven heats.","ar":"١) سخّن الفرن على ٢٠٠ درجة من الأسفل.\\n٢) اضغط كل مربع بالأصابع ضغطًا خفيفًا وسريعًا من الجهتين ليكبر قليلًا (نحو ١٥ سم).\\n٣) ضعها في صينية فرن مبطنة بورق الزبدة واتركها ١٥ دقيقة حتى يسخن الفرن."},"time":20,"image":{"src":"/recipes/kahi-gaimar/step-08.webp","alt":"مربع‌های پهن‌شدهٔ کاهی در سینی فر با کاغذ روغنی","width":1200,"height":900}},{"n":9,"title":{"fa":"پخت","en":"Bake","ar":"الخبز"},"text":{"fa":"۱) سینی را در طبقهٔ پایین فر بگذارید و ۱۰ تا ۱۲ دقیقه بپزید.\\n۲) نشانهٔ پخت: لایه‌ها پف کرده‌اند، زیر کاهی طلایی‌قهوه‌ای و رویش طلایی روشن است.","en":"1) Bake on the lower rack for 10–12 minutes.\\n2) Done when the layers have puffed, the underside is golden brown and the top light golden.","ar":"١) اخبزها على الرف السفلي ١٠ إلى ١٢ دقيقة.\\n٢) تنضج حين تنتفخ الطبقات ويصبح القاع ذهبيًا بنيًا والوجه ذهبيًا فاتحًا."},"time":12,"image":{"src":"/recipes/kahi-gaimar/step-09.webp","alt":"مربع‌های طلایی و پف‌کردهٔ کاهی در فر","width":1200,"height":900}},{"n":10,"title":{"fa":"شیره زدن و سرو","en":"Syrup and serve","ar":"السقي والتقديم"},"text":{"fa":"۱) بلافاصله پس از بیرون آوردن، شیرهٔ سرد را روی کاهی داغ بریزید (صدای جلز می‌دهد).\\n۲) فوراً با قیمر سرو کنید.","en":"1) Right out of the oven, pour the cold syrup over the hot kahi (it sizzles).\\n2) Serve at once with gaimar.","ar":"١) فور خروجه من الفرن اسكب الشيرة الباردة على الكاهي الساخن (يُسمع صوت النشيش).\\n٢) قدّمه فورًا مع القيمر."},"time":3,"image":{"src":"/recipes/kahi-gaimar/step-10.webp","alt":"ریختن شیره روی کاهی داغ کنار کاسهٔ قیمر","width":1200,"height":900}}],"tips":{"fa":["یکی از دو طرف باید داغ و دیگری سرد باشد: شیرهٔ سرد روی کاهی داغ، تا ترد بماند. وبلاگ مطبخ ام مرمر شیرهٔ داغ روی کاهی داغ می‌ریزد؛ نتیجه نرم‌تر است.","هرچه خمیر نازک‌تر باشد، لایه‌ها بیشتر و تردتر می‌شوند.","اگر فرتان المنت زیر جدا ندارد، سینی را در پایین‌ترین طبقه بگذارید."],"en":["One of the two must be hot and the other cold: cold syrup on hot kahi keeps it crisp. The Umm Marmar blog pours hot syrup on hot kahi, which gives a softer result.","The thinner the dough, the more and crisper the layers.","If your oven has no separate bottom element, use the lowest rack."],"ar":["يجب أن يكون أحدهما ساخنًا والآخر باردًا: شيرة باردة على كاهي ساخن ليبقى مقرمشًا. مدونة مطبخ أم مرمر تسكب شيرة ساخنة على كاهي ساخن فيكون أطرى.","كلما رقّت العجينة زادت الطبقات وصارت أكثر قرمشة.","إذا لم يكن في الفرن عنصر سفلي منفصل استخدم الرف الأسفل."]},"cover":{"src":"/recipes/kahi-gaimar/cover.webp","alt":"کاهی با قیمر: مربع‌های طلایی لایه‌لایه با شیره و تکهٔ قیمر سفید","width":1600,"height":1200},"serving":{"src":"/recipes/kahi-gaimar/serving.webp","alt":"یک تکه کاهی با قیمر در بشقاب کنار استکان چای","width":1200,"height":1500}},{"id":"kleicha","country":"IQ","slugs":{"fa":"کلیچه","en":"kleicha","ar":"كليجة"},"title":{"fa":"کلیچه","en":"Kleicha (Iraqi Date-Filled Cookies)","ar":"كليجة"},"summary":{"fa":"شیرینی عید عراقی: خمیر کره‌ای و معطر به هل که با خرمای تفت‌داده پر می‌شود، رویش زرده می‌زنند و در فر طلایی می‌شود.","en":"Iraq\'s Eid cookie: a buttery, cardamom-scented dough filled with saut\xe9ed dates, brushed with egg yolk and baked golden.","ar":"حلوى العيد العراقية: عجينة غنية بالزبدة ومعطرة بالهيل تُحشى بالتمر المحموس وتُدهن بصفار البيض وتُخبز حتى تتذهب."},"intro":{"fa":"در عراق یکی دو روز پیش از عید، زنان خانواده دور هم جمع می‌شوند تا کلیچه بپزند و سینی‌ها را در فر خانه یا نانوایی محله می‌گذارند. در نجف کلیچه را با روغن حیوانی، کره، هل و سیاه‌دانه می‌پزند و در برطله (نینوا) برای کریسمس و سال نو کلیچه‌های بسیار کوچک و نرم با کرهٔ زیاد درست می‌کنند. پرطرفدارترین مغز، خرماست.","en":"A day or two before Eid, Iraqi women gather to make kleicha and send the trays to the home oven or the neighbourhood bakery. In Najaf it is made with animal fat, butter, cardamom and nigella seeds; in Bartella (Nineveh) women bake tiny, very soft, butter-rich kleicha for Christmas and New Year. Dates are the most popular filling.","ar":"قبل العيد بيوم أو يومين تجتمع نساء العائلة العراقية لصنع الكليجة وتُخبز الصواني في فرن البيت أو فرن المنطقة. في النجف تُصنع بالدهن الحر والزبد والهيل والحبة السوداء، وفي برطلة (نينوى) تُعد كليجة صغيرة جدًا وناعمة غنية بالزبدة لأعياد الميلاد ورأس السنة. حشوة التمر هي الأكثر طلبًا."},"seoTitle":{"fa":"کلیچه؛ طرز تهیه شیرینی خرمایی عید به سبک عراقی","en":"Kleicha Recipe (Iraqi Date-Filled Cookies)","ar":"كليجة: طريقة عمل كليجة العيد بالتمر"},"seoDescription":{"fa":"طرز تهیه کلیچه، حدود ۳۰ عدد: خمیر کره‌ای معطر به هل با مغز خرمای تفت‌داده، زرده‌خورده و طلایی‌شده در فر؛ حدود ۲ ساعت با استراحت خمیر.","en":"Iraqi kleicha, about 30 cookies: buttery cardamom dough filled with saut\xe9ed dates, brushed with egg yolk and baked golden. About 2 h incl. dough rest.","ar":"طريقة عمل الكليجة، نحو ٣٠ قطعة: عجينة بالزبدة ومعطرة بالهيل محشوة بالتمر المحموس، تُدهن بصفار البيض وتُخبز حتى تتذهب؛ نحو ساعتين مع راحة العجين."},"servings":30,"prep":48,"cook":20,"rest":45,"total":113,"oven":180,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"آرد سفید","en":"All-purpose flour","ar":"طحين أبيض"},"amount":"4","unit":"پیمانه","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"حدود ۵۲۰ گرم.","en":"About 520 g.","ar":"نحو ٥٢٠ غرامًا."}},{"name":{"fa":"روغن حیوانی و کرهٔ آب‌شده (نصف‌نصف)","en":"Melted ghee and butter (half and half)","ar":"سمن وزبدة مذوبة (مناصفة)"},"amount":"1.5","unit":"پیمانه","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"ولرم، نه داغ.","en":"Lukewarm, not hot.","ar":"فاترة لا ساخنة."}},{"name":{"fa":"شکر","en":"Sugar","ar":"سكر"},"amount":"4","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شیرخشک","en":"Milk powder","ar":"حليب بودرة"},"amount":"5","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"هل سابیده","en":"Ground cardamom","ar":"هيل مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"مخمر فوری","en":"Instant yeast","ar":"خميرة فورية"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"تخم‌مرغ","en":"Egg","ar":"بيضة"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"هم‌زده.","en":"Beaten.","ar":"مخفوقة."}},{"name":{"fa":"آب یا شیر ولرم","en":"Warm water or milk","ar":"ماء أو حليب دافئ"},"amount":"120","unit":"میلی‌لیتر","optional":false,"group":{"fa":"خمیر","en":"Dough","ar":"العجينة"},"note":{"fa":"کم‌کم اضافه کنید تا خمیر نرم شود.","en":"Add gradually until the dough is soft.","ar":"يُضاف تدريجيًا حتى تلين العجينة."}},{"name":{"fa":"خرمای بی‌هسته یا رب خرمای سفت (عجوه)","en":"Pitted dates or firm date paste","ar":"تمر منزوع النوى أو عجوة"},"amount":"500","unit":"گرم","optional":false,"group":{"fa":"مغز خرما","en":"Date filling","ar":"حشوة التمر"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع یا کره","en":"Oil or butter","ar":"زيت أو زبدة"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"مغز خرما","en":"Date filling","ar":"حشوة التمر"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"هل سابیده","en":"Ground cardamom","ar":"هيل مطحون"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"مغز خرما","en":"Date filling","ar":"حشوة التمر"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زردهٔ تخم‌مرغ","en":"Egg yolk","ar":"صفار بيضة"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"رویه","en":"Glaze","ar":"الوجه"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شیر","en":"Milk","ar":"حليب"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"رویه","en":"Glaze","ar":"الوجه"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"سیاه‌دانه یا کنجد","en":"Nigella or sesame seeds","ar":"حبة سوداء أو سمسم"},"amount":"1","unit":"قاشق چای‌خوری","optional":true,"group":{"fa":"رویه","en":"Glaze","ar":"الوجه"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"ورز دادن آرد با روغن","en":"Rub the fat into the flour","ar":"فرك الطحين بالدهن"},"text":{"fa":"۱) در کاسهٔ بزرگ آرد، شکر، شیرخشک، هل و نمک را مخلوط کنید.\\n۲) وسط آرد گودی درست کنید و روغن ولرم را کم‌کم بریزید.\\n۳) با کف دست حدود ۸ دقیقه آرد را با روغن بمالید تا همهٔ آرد چرب و شبیه ماسهٔ مرطوب شود.","en":"1) In a large bowl mix the flour, sugar, milk powder, cardamom and salt.\\n2) Make a well and pour in the lukewarm fat little by little.\\n3) Rub the flour and fat between your palms for about 8 minutes until all the flour is coated and looks like damp sand.","ar":"١) في وعاء كبير اخلط الطحين والسكر والحليب البودرة والهيل والملح.\\n٢) اعمل حفرة في الوسط واسكب الدهن الفاتر تدريجيًا.\\n٣) افرك الطحين بالدهن بين كفيك نحو ٨ دقائق حتى يتشرب كله ويصبح كالرمل الرطب."},"time":10,"image":{"src":"/recipes/kleicha/step-01.webp","alt":"دست‌ها آرد کلیچه را با روغن در کاسهٔ بزرگ می‌مالند تا ماسه‌ای شود","width":1200,"height":900}},{"n":2,"title":{"fa":"خمیر کردن","en":"Knead the dough","ar":"العجن"},"text":{"fa":"۱) مخمر، تخم‌مرغ هم‌زده و نصف آب را اضافه کنید.\\n۲) بقیهٔ آب را کم‌کم بریزید و ۵ تا ۸ دقیقه ورز دهید تا خمیر نرم، صاف و غیرچسبناک شود.\\n۳) اگر خمیر ترک خورد کمی آب و اگر چسبید کمی آرد اضافه کنید.","en":"1) Add the yeast, beaten egg and half the water.\\n2) Add the rest of the water gradually and knead 5–8 minutes until soft, smooth and not sticky.\\n3) If it cracks add a little water; if it sticks add a little flour.","ar":"١) أضف الخميرة والبيضة المخفوقة ونصف الماء.\\n٢) أضف باقي الماء تدريجيًا واعجن ٥ إلى ٨ دقائق حتى تصبح العجينة طرية ناعمة لا تلتصق.\\n٣) إذا تشققت أضف قليلًا من الماء، وإذا التصقت أضف قليلًا من الطحين."},"time":8,"image":{"src":"/recipes/kleicha/step-02.webp","alt":"گلولهٔ خمیر نرم و صاف کلیچه در کاسه","width":1200,"height":900}},{"n":3,"title":{"fa":"استراحت خمیر","en":"Let the dough rise","ar":"تخمير العجينة"},"text":{"fa":"روی کاسه را بپوشانید و ۳۰ دقیقه در جای گرم بگذارید تا خمیر کمی پف کند (زمان استراحت).","en":"Cover the bowl and leave in a warm place for 30 minutes until slightly puffed (rest time).","ar":"غطِّ الوعاء واتركه في مكان دافئ ٣٠ دقيقة حتى تنتفخ العجينة قليلًا (وقت الراحة)."},"time":30,"image":{"src":"/recipes/kleicha/step-03.webp","alt":"کاسهٔ پوشیدهٔ خمیر کلیچه در حال استراحت","width":1200,"height":900}},{"n":4,"title":{"fa":"آماده کردن مغز خرما","en":"Make the date filling","ar":"تحضير حشوة التمر"},"text":{"fa":"هم‌زمان با استراحت خمیر (جدا شمرده نشده):\\n۱) روغن را در تابهٔ ۲۴ سانتی‌متری روی حرارت کم گرم کنید.\\n۲) خرما و هل را اضافه کنید و ۵ تا ۷ دقیقه با قاشق چوبی له کنید تا خمیری نرم و یکدست شود.\\n۳) بگذارید سرد شود و به ۳۰ گلولهٔ کوچک (اندازهٔ فندق) تقسیم کنید.","en":"While the dough rests (not counted separately):\\n1) Warm the oil in a 24 cm pan over low heat.\\n2) Add the dates and cardamom and mash with a wooden spoon for 5–7 minutes into a soft, even paste.\\n3) Let cool and divide into 30 hazelnut-sized balls.","ar":"أثناء تخمير العجينة (لا يُحسب منفصلًا):\\n١) سخّن الزيت في مقلاة ٢٤ سم على نار هادئة.\\n٢) أضف التمر والهيل واهرسه بملعقة خشبية ٥ إلى ٧ دقائق حتى يصبح عجينة طرية متجانسة.\\n٣) اتركه يبرد وقسّمه إلى ٣٠ كرة صغيرة بحجم البندقة."},"time":10,"image":{"src":"/recipes/kleicha/step-04.webp","alt":"خرمای له‌شده در تابه و گلوله‌های کوچک مغز کلیچه","width":1200,"height":900}},{"n":5,"title":{"fa":"شکل دادن و پر کردن","en":"Shape and fill","ar":"التشكيل والحشو"},"text":{"fa":"۱) فر را روی ۱۸۰ درجه روشن کنید و سینی را با کاغذ روغنی بپوشانید.\\n۲) خمیر را به ۳۰ گلولهٔ گردویی تقسیم کنید.\\n۳) هر گلوله را در کف دست پهن کنید، یک گلوله خرما وسطش بگذارید و لبه‌ها را جمع و محکم ببندید.\\n۴) گلوله را کمی صاف کنید و با چنگال یا قالب کلیچه رویش نقش بزنید. با فاصلهٔ ۳ سانتی‌متر در سینی بچینید.","en":"1) Heat the oven to 180\xb0C and line a tray with baking paper.\\n2) Divide the dough into 30 walnut-sized balls.\\n3) Flatten each in your palm, put a date ball in the centre, bring the edges up and seal well.\\n4) Flatten slightly and press a pattern with a fork or kleicha mould. Place 3 cm apart on the tray.","ar":"١) سخّن الفرن على ١٨٠ درجة وافرش الصينية بورق الزبدة.\\n٢) قسّم العجينة إلى ٣٠ كرة بحجم الجوزة.\\n٣) افرد كل كرة في كفك وضع كرة تمر في الوسط واجمع الأطراف وأغلقها جيدًا.\\n٤) اضغطها قليلًا وانقش وجهها بالشوكة أو بقالب الكليجة. رتبها في الصينية بمسافة ٣ سم."},"time":30,"image":{"src":"/recipes/kleicha/step-05.webp","alt":"پر کردن خمیر با خرما و کلیچه‌های نقش‌دار در سینی","width":1200,"height":900}},{"n":6,"title":{"fa":"رویه زدن و پخت","en":"Glaze and bake","ar":"الدهن والخبز"},"text":{"fa":"۱) زرده و شیر را هم بزنید و با قلم‌مو روی کلیچه‌ها بمالید؛ اگر خواستید سیاه‌دانه یا کنجد بپاشید.\\n۲) در طبقهٔ وسط فر ۱۸۰ درجه ۱۸ تا ۲۰ دقیقه بپزید.\\n۳) نشانهٔ پخت: رو طلایی براق و زیر کمی قهوه‌ای شده باشد.","en":"1) Beat the yolk with the milk and brush over the cookies; sprinkle nigella or sesame if you like.\\n2) Bake on the middle rack at 180\xb0C for 18–20 minutes.\\n3) Done when the tops are shiny golden and the bottoms lightly browned.","ar":"١) اخفق الصفار مع الحليب وادهن به الكليجة، وانثر الحبة السوداء أو السمسم إن رغبت.\\n٢) اخبزها على الرف الأوسط بحرارة ١٨٠ درجة من ١٨ إلى ٢٠ دقيقة.\\n٣) تنضج حين يصبح الوجه ذهبيًا لامعًا والقاع محمرًا قليلًا."},"time":20,"image":{"src":"/recipes/kleicha/step-06.webp","alt":"کلیچه‌های طلایی براق در سینی تازه از فر","width":1200,"height":900}},{"n":7,"title":{"fa":"سرد کردن","en":"Cool","ar":"التبريد"},"text":{"fa":"کلیچه‌ها را ۱۵ دقیقه روی توری بگذارید تا سفت شوند؛ داغ شکننده‌اند (زمان استراحت).","en":"Cool on a rack for 15 minutes to firm up; they are fragile when hot (rest time).","ar":"اترك الكليجة على شبك ١٥ دقيقة لتتماسك فهي هشة وهي ساخنة (وقت الراحة)."},"time":15,"image":{"src":"/recipes/kleicha/step-07.webp","alt":"کلیچه روی توری در حال سرد شدن","width":1200,"height":900}}],"tips":{"fa":["روغن باید ولرم باشد؛ روغن داغ مخمر را از کار می‌اندازد.","نسبت آرد به روغن را به‌هم نزنید: آرد حدود دو برابر روغن باشد تا کلیچه ترد شود ولی خرد نشود.","اگر خرما خشک است، ۱ تا ۲ قاشق آب داغ به آن اضافه کنید.","در منابع زمان تخمیر از نیم ساعت تا چند ساعت آمده؛ برای خانه ۳۰ دقیقه کافی است."],"en":["The fat should be lukewarm; hot fat kills the yeast.","Keep the ratio: about twice as much flour as fat gives a tender cookie that does not crumble.","If the dates are dry, add 1–2 tablespoons of hot water.","Sources give rising times from half an hour to several hours; 30 minutes is enough at home."],"ar":["يجب أن يكون الدهن فاترًا فالدهن الساخن يقتل الخميرة.","حافظ على النسبة: الطحين نحو ضعف الدهن لتكون الكليجة هشة لا تتفتت.","إذا كان التمر جافًا أضف ملعقة أو ملعقتين من الماء الساخن.","تتراوح مدة التخمير في المصادر من نصف ساعة إلى عدة ساعات، و٣٠ دقيقة تكفي في البيت."]},"cover":{"src":"/recipes/kleicha/cover.webp","alt":"کلیچه: شیرینی‌های گرد طلایی نقش‌دار و یکی شکسته با مغز خرما","width":1600,"height":1200},"serving":{"src":"/recipes/kleicha/serving.webp","alt":"بشقاب کوچک کلیچه کنار استکان چای","width":1200,"height":1500}},{"id":"masgouf","country":"IQ","slugs":{"fa":"مسگوف","en":"masgouf","ar":"مسكوف"},"title":{"fa":"مسگوف","en":"Masgouf (Iraqi Baked Split Carp)","ar":"مسكوف (سمك عراقي مشقوق ومشوي)"},"summary":{"fa":"ماهی کپور کاملِ بازشده که با نمک، ادویهٔ کاری و سرکه مزه‌دار می‌شود، در فر می‌پزد و در پایان سس پیاز، گوجه و جعفری رویش می‌نشیند؛ نسخهٔ خانگی غذای مشهور کنار دجله.","en":"A whole carp split open, seasoned with salt, curry spice and vinegar, baked, then finished with an onion, tomato and parsley sauce; a home version of the famous Tigris-side dish.","ar":"سمكة شبوط أو كارب كاملة مشقوقة تُتبل بالملح والكاري والخل، تُشوى في الفرن ثم تُغطى بصلصة البصل والطماطم والبقدونس؛ نسخة منزلية من الطبق الشهير على ضفاف دجلة."},"intro":{"fa":"مسگوف شناخته‌شده‌ترین غذای ماهی عراق است. در بغداد، به‌ویژه در خیابان ابونواس کنار دجله، ماهی کپور یا شبوط را از پشت باز می‌کنند، روی چوب‌هایی دور آتش هیزم می‌گذارند و آرام کباب می‌کنند. همین غذا امروز در کرکوک و حتی سنجار هم پخته می‌شود. چون آتش هیزم در خانه آسان نیست، این دستور روش فر را دنبال می‌کند که منابع عراقی برای آشپزخانهٔ خانگی پیشنهاد می‌دهند؛ روش سنتی در بخش جایگزین‌ها آمده است.","en":"Masgouf is Iraq\'s best-known fish dish. In Baghdad, especially along Abu Nuwas Street on the Tigris, carp or shabout is split along the back, propped on stakes around a wood fire and slowly roasted. Today it is also cooked in Kirkuk and even Sinjar. Because an open wood fire is hard at home, this recipe follows the oven method that Iraqi sources suggest for home kitchens; the traditional method is under alternatives.","ar":"المسكوف أشهر أطباق السمك في العراق. في بغداد، وخاصة في شارع أبي نؤاس على دجلة، يُشق سمك الكارب أو الشبوط من الظهر ويُثبت على أعواد حول نار الحطب ويُشوى ببطء. ويُحضَّر اليوم في كركوك وحتى سنجار. ولأن نار الحطب صعبة في البيت، تتبع هذه الوصفة طريقة الفرن التي تقترحها المصادر العراقية للمطبخ المنزلي، والطريقة التقليدية مذكورة في البدائل."},"seoTitle":{"fa":"مسگوف؛ طرز تهیه ماهی کپور شکم‌باز در فر به سبک عراقی","en":"Masgouf Recipe (Iraqi Baked Split Carp)","ar":"مسكوف: طريقة عمل السمك المسكوف في الفرن"},"seoDescription":{"fa":"طرز تهیه مسگوف آسان برای ۴ نفر: ماهی کپور کامل بازشده با نمک، ادویهٔ کاری و سرکه در فر، با سس پیاز، گوجه و جعفری؛ حدود ۱ ساعت.","en":"Easy masgouf for 4: whole carp split open, seasoned with salt, curry spice and vinegar, oven-baked and topped with onion, tomato and parsley. About 1 h.","ar":"طريقة عمل المسكوف السهلة لأربعة أشخاص: سمكة شبوط أو كارب مشقوقة تُتبل بالملح والكاري والخل وتُشوى في الفرن مع صلصة البصل والطماطم والبقدونس؛ نحو ساعة."},"servings":4,"prep":25,"cook":38,"rest":0,"total":63,"oven":180,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"ماهی کپور یا شبوط کامل","en":"Whole carp or shabout","ar":"سمكة كارب أو شبوط كاملة"},"amount":"1500","unit":"گرم","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"پولک‌گرفته، شکم خالی و از پشت یا شکم باز شده (از ماهی‌فروش بخواهید).","en":"Scaled, gutted and split open along the back or belly (ask the fishmonger).","ar":"منظفة من القشور والأحشاء ومشقوقة من الظهر أو البطن (اطلبه من بائع السمك)."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"پودر کاری","en":"Curry powder","ar":"كاري"},"amount":"2","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"منابع ۱ قاشق چای‌خوری تا ۱ قاشق غذاخوری می‌گویند.","en":"Sources give 1 tsp to 1 tbsp.","ar":"تذكر المصادر من ملعقة صغيرة إلى ملعقة كبيرة."}},{"name":{"fa":"سرکهٔ سفید، سیب یا خرما","en":"White, apple or date vinegar","ar":"خل أبيض أو خل تفاح أو خل تمر"},"amount":"60","unit":"میلی‌لیتر","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"فقط این سه نوع.","en":"Only these three kinds.","ar":"هذه الأنواع الثلاثة فقط."}},{"name":{"fa":"سیر رنده‌شده","en":"Grated garlic","ar":"ثوم مبشور"},"amount":"4","unit":"حبه","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن زیتون","en":"Olive oil","ar":"زيت زيتون"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"ماهی","en":"Fish","ar":"السمك"},"note":{"fa":"برای چرب کردن سینی و روی ماهی.","en":"For the tray and the fish.","ar":"لدهن الصينية والسمكة."}},{"name":{"fa":"پیاز درشت ریز‌خردشده","en":"Large onions, finely chopped","ar":"بصل كبير مفروم ناعمًا"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"سس روی ماهی","en":"Topping sauce","ar":"الصلصة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"گوجه‌فرنگی درشت ریز‌خردشده","en":"Large tomatoes, finely chopped","ar":"طماطم كبيرة مفرومة ناعمًا"},"amount":"2","unit":"عدد","optional":false,"group":{"fa":"سس روی ماهی","en":"Topping sauce","ar":"الصلصة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"جعفری ریز‌خردشده","en":"Chopped parsley","ar":"بقدونس مفروم"},"amount":"40","unit":"گرم","optional":false,"group":{"fa":"سس روی ماهی","en":"Topping sauce","ar":"الصلصة"},"note":{"fa":"حدود یک دسته.","en":"About one bunch.","ar":"نحو باقة واحدة."}},{"name":{"fa":"سیر ریز‌خردشده","en":"Chopped garlic","ar":"ثوم مفروم"},"amount":"4","unit":"حبه","optional":false,"group":{"fa":"سس روی ماهی","en":"Topping sauce","ar":"الصلصة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"روغن مایع","en":"Vegetable oil","ar":"زيت نباتي"},"amount":"2","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"سس روی ماهی","en":"Topping sauce","ar":"الصلصة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"رب گوجه‌فرنگی","en":"Tomato paste","ar":"معجون الطماطم"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"سس روی ماهی","en":"Topping sauce","ar":"الصلصة"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"آماده کردن ماهی و فر","en":"Prep the fish and oven","ar":"تحضير السمك والفرن"},"text":{"fa":"۱) فر را روی ۱۸۰ درجهٔ سانتی‌گراد روشن کنید.\\n۲) ماهی بازشده را زیر آب سرد بشویید و با دستمال کاغذی کاملاً خشک کنید.\\n۳) اگر ماهی‌فروش باز نکرده: با چاقوی تیز از کنار ستون فقرات، از دم تا سر، ببرید و ماهی را مثل کتاب باز کنید؛ پوست شکم را نبرید.","en":"1) Heat the oven to 180\xb0C.\\n2) Rinse the split fish under cold water and pat it completely dry with paper towels.\\n3) If it is not split: with a sharp knife cut along the backbone from tail to head and open the fish like a book, keeping the belly skin whole.","ar":"١) سخّن الفرن على ١٨٠ درجة مئوية.\\n٢) اغسل السمكة المشقوقة بالماء البارد وجففها تمامًا بورق المطبخ.\\n٣) إن لم تكن مشقوقة: شقها بسكين حاد بمحاذاة العمود الفقري من الذيل إلى الرأس وافتحها كالكتاب دون قطع جلد البطن."},"time":10,"image":{"src":"/recipes/masgouf/step-01.webp","alt":"ماهی کپور بازشده روی تخته که با دستمال کاغذی خشک می‌شود","width":1200,"height":900}},{"n":2,"title":{"fa":"مزه‌دار کردن","en":"Season the fish","ar":"تتبيل السمك"},"text":{"fa":"۱) سینی فر بزرگ (حدود ۳۰ در ۴۰ سانتی‌متر) را با روغن زیتون چرب کنید.\\n۲) ماهی را با پوست رو به پایین و گوشت رو به بالا در سینی پهن کنید.\\n۳) نمک را روی هر دو طرف بپاشید و با دست بمالید.\\n۴) کاری، سیر رنده‌شده و سرکه را روی گوشت پخش کنید و باقی روغن را رویش بریزید.","en":"1) Oil a large baking tray (about 30 \xd7 40 cm) with the olive oil.\\n2) Lay the fish open, skin side down and flesh side up.\\n3) Sprinkle salt on both sides and rub it in.\\n4) Spread the curry, grated garlic and vinegar over the flesh and drizzle with the rest of the oil.","ar":"١) ادهن صينية فرن كبيرة (نحو ٣٠ \xd7 ٤٠ سم) بزيت الزيتون.\\n٢) افرد السمكة والجلد إلى الأسفل واللحم إلى الأعلى.\\n٣) رش الملح على الجانبين وافركه جيدًا.\\n٤) وزّع الكاري والثوم المبشور والخل على اللحم واسكب باقي الزيت فوقه."},"time":10,"image":{"src":"/recipes/masgouf/step-02.webp","alt":"ماهی بازشدهٔ مسگوف در سینی با کاری زرد و سیر روی گوشت","width":1200,"height":900}},{"n":3,"title":{"fa":"پختن در فر","en":"Bake","ar":"الشوي في الفرن"},"text":{"fa":"۱) سینی را در طبقهٔ وسط فر بگذارید.\\n۲) حدود ۳۰ دقیقه بپزید.\\n۳) نشانهٔ پخت: گوشت کاملاً سفید و مات شده و نزدیک ستون فقرات با چنگال به‌راحتی ورقه می‌شود. اگر ماهی شما بزرگ‌تر از ۱/۵ کیلوگرم است، ۵ تا ۱۰ دقیقه بیشتر لازم دارد.","en":"1) Put the tray on the middle oven rack.\\n2) Bake about 30 minutes.\\n3) Done when the flesh is fully white and opaque and flakes easily with a fork near the backbone. A fish over 1.5 kg needs 5–10 minutes more.","ar":"١) ضع الصينية على الرف الأوسط.\\n٢) اشوِها نحو ٣٠ دقيقة.\\n٣) تنضج حين يصبح اللحم أبيض معتمًا تمامًا ويتفتت بالشوكة بسهولة قرب العمود الفقري. السمكة الأكبر من ١٫٥ كغ تحتاج ٥ إلى ١٠ دقائق إضافية."},"time":30,"image":{"src":"/recipes/masgouf/step-03.webp","alt":"ماهی مسگوف در فر که گوشتش سفید و کمی طلایی شده","width":1200,"height":900}},{"n":4,"title":{"fa":"سس پیاز و گوجه","en":"Onion and tomato sauce","ar":"صلصة البصل والطماطم"},"text":{"fa":"هم‌زمان با پخت ماهی (جدا شمرده نشده):\\n۱) روغن را در تابهٔ متوسط (۲۴ سانتی‌متر) روی حرارت متوسط داغ کنید.\\n۲) پیاز را ۴ دقیقه تفت دهید تا نرم و شفاف شود.\\n۳) گوجه، سیر و جعفری را اضافه کنید و ۳ دقیقه هم بزنید.\\n۴) رب را اضافه کنید و حدود ۳ دقیقه بپزید تا سس غلیظ شود و آبش کم شود.","en":"While the fish bakes (not counted separately):\\n1) Heat the oil in a medium frying pan (24 cm) over medium heat.\\n2) Cook the onion 4 minutes until soft and translucent.\\n3) Add the tomato, garlic and parsley and stir for 3 minutes.\\n4) Stir in the tomato paste and cook about 3 minutes until the sauce is thick and most liquid is gone.","ar":"أثناء شوي السمك (لا يُحسب منفصلًا):\\n١) سخّن الزيت في مقلاة متوسطة (٢٤ سم) على نار متوسطة.\\n٢) قلّب البصل ٤ دقائق حتى يذبل ويصبح شفافًا.\\n٣) أضف الطماطم والثوم والبقدونس وقلّب ٣ دقائق.\\n٤) أضف معجون الطماطم واطبخ نحو ٣ دقائق حتى تتماسك الصلصة ويقل سائلها."},"time":10,"image":{"src":"/recipes/masgouf/step-04.webp","alt":"تابهٔ سس پیاز، گوجه و جعفری برای مسگوف","width":1200,"height":900}},{"n":5,"title":{"fa":"سس روی ماهی","en":"Top and finish","ar":"إضافة الصلصة"},"text":{"fa":"۱) سینی را بیرون بیاورید و سس را یکنواخت روی گوشت ماهی پهن کنید.\\n۲) دوباره در فر بگذارید و حدود ۸ دقیقه بپزید تا سس داغ شود و لبه‌هایش کمی برشته شود.","en":"1) Take out the tray and spread the sauce evenly over the fish.\\n2) Return it to the oven for about 8 minutes until the sauce is hot and its edges just start to brown.","ar":"١) أخرج الصينية ووزّع الصلصة بالتساوي على السمكة.\\n٢) أعدها إلى الفرن نحو ٨ دقائق حتى تسخن الصلصة وتبدأ أطرافها بالتحمر."},"time":8,"image":{"src":"/recipes/masgouf/step-05.webp","alt":"مسگوف پخته با سس قرمز پیاز و گوجه روی گوشت","width":1200,"height":900}},{"n":6,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"۱) ماهی را با کفگیر پهن یا دو کفگیر به دیس بزرگ منتقل کنید.\\n۲) فوراً با نان، عمبه و ترشی سرو کنید. مراقب استخوان‌ها باشید، به‌ویژه برای کودکان.","en":"1) Slide the fish onto a large platter with a wide spatula or two.\\n2) Serve at once with bread, amba and pickles. Watch for bones, especially for children.","ar":"١) انقل السمكة إلى طبق كبير بملعقة مسطحة عريضة أو اثنتين.\\n٢) قدّمها فورًا مع الخبز والعمبة والطرشي. انتبه للعظام خاصة للأطفال."},"time":5,"image":{"src":"/recipes/masgouf/step-06.webp","alt":"دیس مسگوف با نان، ترشی و کاسهٔ عمبه","width":1200,"height":900}}],"tips":{"fa":["ماهی تازه چشم روشن و آبشش قرمز دارد.","خشک کردن کامل ماهی کمک می‌کند ادویه بهتر بچسبد.","اگر کبابی بیرونی دارید، روش هیزمی سنتی را در بخش جایگزین‌ها ببینید."],"en":["Fresh fish has clear eyes and red gills.","Drying the fish well helps the seasoning stick.","If you have an outdoor grill, see the traditional wood-fire method under alternatives."],"ar":["السمك الطازج عيناه لامعتان وخياشيمه حمراء.","تجفيف السمكة جيدًا يساعد التتبيلة على الالتصاق.","إن كان لديك مشواة خارجية فراجع طريقة الحطب التقليدية في البدائل."]},"cover":{"src":"/recipes/masgouf/cover.webp","alt":"مسگوف: ماهی کپور بازشده با سس پیاز و گوجه در دیس همراه نان و ترشی","width":1600,"height":1200},"serving":{"src":"/recipes/masgouf/serving.webp","alt":"بشقاب مسگوف با نان تنوری، کاسهٔ کوچک عمبه و ترشی","width":1200,"height":1500}},{"id":"pacha","country":"IQ","slugs":{"fa":"باجه","en":"pacha","ar":"باجة-عراقية"},"title":{"fa":"باجه","en":"Pacha (Iraqi Lamb Head and Trotters)","ar":"باجة"},"summary":{"fa":"کله و پاچهٔ گوسفند که پس از یک جوش و دور ریختن آب اول، با هل، دارچین، میخک و برگ بو ساعت‌ها آرام می‌پزد و روی نان خیس‌خورده در آبش با لیمو سرو می‌شود.","en":"Lamb head and trotters, blanched once, then simmered for hours with cardamom, cinnamon, cloves and bay, and served over bread soaked in the broth with lemon.","ar":"رأس الغنم وكوارعه تُسلق مرة ويُرمى ماؤها، ثم تُطهى ساعات على نار هادئة مع الهيل والقرفة والقرنفل وورق الغار، وتُقدَّم فوق خبز مشرّب بالمرق مع الليمون."},"intro":{"fa":"باجه غذای شب‌زنده‌داری عراقی‌هاست: در اربیل رستوران‌های باجه از ۷ شب تا ۷ صبح باز هستند و مشتری نان عراقی خیس‌خورده در آبگوشت را با زبان، گوشت، مغز و \xabممبار\xbb سفارش می‌دهد. در سنجار، برای برخی ایزدی‌ها باجه غذای متبرک آغاز سال است. آشپزهای حرفه‌ای می‌گویند راز کار تمیز کردن چندباره است.","en":"Pacha is Iraq\'s late-night dish: in Erbil pacha restaurants open from 7 pm to 7 am, and diners order Iraqi bread soaked in broth topped with tongue, meat, brain and stuffed intestine (mumbar). In Sinjar it is a blessed New Year dish for some Yazidis. Professional cooks say the secret is cleaning, more than once.","ar":"الباجة أكلة السهر عند العراقيين: في أربيل تفتح مطاعم الباجة من السابعة مساءً حتى السابعة صباحًا، ويطلب الزبون خبزًا عراقيًا مشرّبًا بالمرق مع اللسان واللحم والمخ والممبار. وفي سنجار هي طعام مبارك لرأس السنة عند بعض الإيزيديين. ويقول الطباخون إن السر في التنظيف أكثر من مرة."},"seoTitle":{"fa":"باجه عراقی؛ طرز تهیه با گوشت سر و پاچه گوسفند","en":"Pacha Recipe (Iraqi Lamb Head and Trotters)","ar":"باجة: طريقة عمل الباجة العراقية برأس الغنم والكوارع"},"seoDescription":{"fa":"طرز تهیه باجهٔ عراقی برای ۶ نفر: کله، پاچه و سیرابی گوسفند با هل، دارچین، میخک و برگ بو، سرو روی نان خیس‌خورده با لیمو؛ حدود ۳.۵ ساعت.","en":"Iraqi pacha for 6: lamb head, trotters and tripe simmered with cardamom, cinnamon, cloves and bay, served over broth-soaked bread with lemon. About 3.5 h.","ar":"طريقة عمل الباجة العراقية لستة أشخاص: رأس الغنم وكوارعه والكرشة مع الهيل والقرفة والقرنفل وورق الغار، تُقدم فوق خبز مشرّب بالمرق مع الليمون؛ نحو ثلاث ساعات ونصف."},"servings":6,"prep":60,"cook":155,"rest":0,"total":215,"oven":null,"difficulty":{"fa":"سخت","en":"Hard","ar":"صعب"},"showNutrition":false,"ingredients":[{"name":{"fa":"کلهٔ گوسفند، نصف‌شده (ذبح حلال، موکنده و تمیز)","en":"Lamb head, halved (halal-slaughtered, singed and cleaned)","ar":"رأس غنم مقسوم نصفين (مذبوح حلال، منظف ومشوّط)"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"باجه","en":"Pacha","ar":"الباجة"},"note":{"fa":"از قصاب بخواهید نصف کند.","en":"Ask the butcher to halve it.","ar":"اطلب من القصاب قسمه."}},{"name":{"fa":"پاچهٔ گوسفند (ذبح حلال، تمیز)","en":"Lamb trotters (halal-slaughtered, cleaned)","ar":"كوارع غنم (مذبوحة حلال، منظفة)"},"amount":"4","unit":"عدد","optional":false,"group":{"fa":"باجه","en":"Pacha","ar":"الباجة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شیردان یا سیرابی تمیزشده","en":"Cleaned lamb tripe","ar":"كرشة غنم منظفة"},"amount":"500","unit":"گرم","optional":true,"group":{"fa":"باجه","en":"Pacha","ar":"الباجة"},"note":{"fa":"از قصاب آماده بخرید.","en":"Buy ready-cleaned from the butcher.","ar":"تُشترى منظفة من القصاب."}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"4","unit":"لیتر","optional":false,"group":{"fa":"باجه","en":"Pacha","ar":"الباجة"},"note":{"fa":"برای پخت اصلی؛ آب جوش اول جداست.","en":"For the main simmer; blanching water is extra.","ar":"للسلق الأساسي؛ ماء الغلية الأولى منفصل."}},{"name":{"fa":"پیاز درشت","en":"Large onion","ar":"بصلة كبيرة"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"چهارقاچ.","en":"Quartered.","ar":"مقطعة أرباعًا."}},{"name":{"fa":"سیر","en":"Garlic","ar":"ثوم"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"یک بوتهٔ کامل، از وسط نصف‌شده.","en":"One whole head, halved across.","ar":"رأس كامل مقسوم بالعرض."}},{"name":{"fa":"چوب دارچین","en":"Cinnamon stick","ar":"عود قرفة"},"amount":"1","unit":"عدد","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"برگ بو","en":"Bay leaves","ar":"ورق غار"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"میخک","en":"Cloves","ar":"قرنفل"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"هل سبز","en":"Green cardamom pods","ar":"حبات هيل"},"amount":"5","unit":"عدد","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"کمی کوبیده.","en":"Lightly cracked.","ar":"مرضوضة قليلًا."}},{"name":{"fa":"جوز هندی رنده‌شده","en":"Grated nutmeg","ar":"جوزة الطيب مبشورة"},"amount":"0.25","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"فلفل سیاه","en":"Black pepper","ar":"فلفل أسود"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"1","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"معطرات","en":"Aromatics","ar":"المطيبات"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نان عراقی یا نان ساج","en":"Iraqi or saj bread","ar":"خبز عراقي أو خبز صاج"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"تکه‌تکه.","en":"Torn into pieces.","ar":"مقطع قطعًا."}},{"name":{"fa":"لیموترش","en":"Lemons","ar":"ليمون حامض"},"amount":"3","unit":"عدد","optional":false,"group":{"fa":"برای سرو","en":"To serve","ar":"للتقديم"},"note":{"fa":"قاچ‌شده.","en":"In wedges.","ar":"مقطع شرائح."}}],"steps":[{"n":1,"title":{"fa":"تمیز کردن","en":"Clean the offal","ar":"التنظيف"},"text":{"fa":"۱) کله و پاچه‌ها را زیر آب سرد بشویید. حتی اگر از قصاب تمیز خریده‌اید، دوباره تمیز کنید.\\n۲) موهای باقی‌مانده را روی شعلهٔ گاز بسوزانید و با پشت چاقو بتراشید.\\n۳) داخل بینی و گوش‌ها را با آب بشویید و غضروف نوک بینی را ببرید.\\n۴) نشانهٔ کار درست: پوست سفید تا کرم‌رنگ، بی‌مو و بدون بوی تند.","en":"1) Rinse the head and trotters under cold water. Even if bought cleaned, clean them again.\\n2) Singe any remaining hairs over a gas flame and scrape with the back of a knife.\\n3) Wash inside the nose and ears and cut off the tip of the nose cartilage.\\n4) Done when the skin is white to cream, hairless and has no strong smell.","ar":"١) اغسل الرأس والكوارع بالماء البارد. حتى لو اشتريتها منظفة نظّفها مرة أخرى.\\n٢) شوّط ما بقي من الشعر على لهب الغاز واكشطه بظهر السكين.\\n٣) اغسل داخل الأنف والأذنين واقطع طرف غضروف الأنف.\\n٤) يكتمل حين يصبح الجلد أبيض إلى كريمي بلا شعر ولا رائحة قوية."},"time":30,"image":{"src":"/recipes/pacha/step-01.webp","alt":"تمیز کردن پاچهٔ گوسفند برای باجه با پشت چاقو کنار سینک","width":1200,"height":900}},{"n":2,"title":{"fa":"جوش اول و دور ریختن آب","en":"Blanch and discard the water","ar":"الغلية الأولى ورمي الماء"},"text":{"fa":"۱) همه را در قابلمهٔ بزرگ (۱۰ تا ۱۲ لیتری) بگذارید و روی آن آب سرد بریزید تا ۵ سانتی‌متر بالاتر بیاید.\\n۲) روی حرارت زیاد بگذارید تا جوش بیاید و کف خاکستری روی آب جمع شود (حدود ۱۵ دقیقه).\\n۳) آب را دور بریزید، تکه‌ها و قابلمه را بشویید.","en":"1) Put everything in a large pot (10–12 L) and cover with cold water by 5 cm.\\n2) Bring to the boil over high heat until grey foam collects on top (about 15 minutes).\\n3) Discard the water and rinse the pieces and the pot.","ar":"١) ضع كل القطع في قدر كبير (١٠ إلى ١٢ لترًا) واغمرها بماء بارد يعلوها ٥ سم.\\n٢) اتركها على نار عالية حتى تغلي وتتجمع رغوة رمادية على السطح (نحو ١٥ دقيقة).\\n٣) ارمِ الماء واغسل القطع والقدر."},"time":20,"image":{"src":"/recipes/pacha/step-02.webp","alt":"قابلمهٔ بزرگ باجه با کف خاکستری روی آب جوش","width":1200,"height":900}},{"n":3,"title":{"fa":"پخت آرام با معطرات","en":"Simmer with aromatics","ar":"السلق مع المطيبات"},"text":{"fa":"۱) تکه‌ها را به قابلمه برگردانید و ۴ تا ۵ لیتر آب تازه بریزید.\\n۲) پیاز، سیر، دارچین، برگ بو، میخک، هل، جوز هندی، فلفل و نمک را اضافه کنید.\\n۳) روی حرارت زیاد بجوشانید و کف را با کفگیر بگیرید.\\n۴) در را بگذارید و روی حرارت کم ۲ ساعت بپزید؛ هر ۳۰ دقیقه آب را چک کنید و اگر کم شد آب جوش اضافه کنید.\\n۵) نشانهٔ پخت: گوشت گونه به‌راحتی جدا می‌شود و پوست پاچه با فشار انگشت نرم است.","en":"1) Return the pieces to the pot and add 4–5 L fresh water.\\n2) Add the onion, garlic, cinnamon, bay, cloves, cardamom, nutmeg, pepper and salt.\\n3) Bring to the boil over high heat and skim the foam.\\n4) Cover and simmer on low for 2 hours; check every 30 minutes and top up with boiling water if needed.\\n5) Done when the cheek meat comes away easily and the trotter skin is soft under your finger.","ar":"١) أعد القطع إلى القدر وأضف ٤ إلى ٥ لترات ماء جديد.\\n٢) أضف البصل والثوم والقرفة وورق الغار والقرنفل والهيل وجوزة الطيب والفلفل والملح.\\n٣) اترك القدر يغلي على نار عالية وأزل الرغوة.\\n٤) غطِّه واتركه على نار هادئة ساعتين، وتفقّد الماء كل ٣٠ دقيقة وأضف ماءً مغليًا عند الحاجة.\\n٥) تنضج حين ينفصل لحم الخد بسهولة ويلين جلد الكارع تحت الإصبع."},"time":135,"image":{"src":"/recipes/pacha/step-03.webp","alt":"قابلمهٔ بزرگ باجه با گوشت، برگ بو و دارچین در آبگوشت","width":1200,"height":900}},{"n":4,"title":{"fa":"جدا کردن گوشت و صاف کردن آب","en":"Separate the meat and strain","ar":"فصل اللحم وتصفية المرق"},"text":{"fa":"۱) با کفگیر تکه‌ها را در سینی بیاورید و ۵ دقیقه بگذارید کمی خنک شوند.\\n۲) گوشت گونه و سر را جدا کنید، پوست زبان را بکنید و مغز را با احتیاط بیرون بیاورید.\\n۳) آبگوشت را از صافی رد کنید و معطرات را دور بریزید. نمک را بچشید.","en":"1) Lift the pieces onto a tray with a slotted spoon and let them cool 5 minutes.\\n2) Pull off the cheek and head meat, peel the skin off the tongue and remove the brain carefully.\\n3) Strain the broth and discard the aromatics. Taste for salt.","ar":"١) ارفع القطع إلى صينية بالمغرفة المثقبة واتركها ٥ دقائق لتبرد قليلًا.\\n٢) افصل لحم الخد والرأس واقشر جلد اللسان وأخرج المخ بحذر.\\n٣) صفِّ المرق وارمِ المطيبات وتذوّق الملح."},"time":20,"image":{"src":"/recipes/pacha/step-04.webp","alt":"سینی گوشت سر، زبان پوست‌کنده و پاچه کنار آبگوشت صاف‌شدهٔ باجه","width":1200,"height":900}},{"n":5,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"۱) تکه‌های نان را در کاسهٔ گود بچینید.\\n۲) دو تا سه ملاقه آبگوشت داغ رویش بریزید تا نان خیس بخورد.\\n۳) گوشت، زبان و پاچه را روی نان بگذارید و با لیمو سرو کنید.","en":"1) Lay pieces of bread in a deep bowl.\\n2) Ladle 2–3 ladles of hot broth over until the bread is soaked.\\n3) Top with meat, tongue and trotters and serve with lemon.","ar":"١) رتّب قطع الخبز في صحن عميق.\\n٢) اسكب فوقها ٢ إلى ٣ مغارف من المرق الساخن حتى يتشرب الخبز.\\n٣) ضع اللحم واللسان والكوارع فوق الخبز وقدّمها مع الليمون."},"time":10,"image":{"src":"/recipes/pacha/step-05.webp","alt":"کاسهٔ باجه: نان خیس‌خورده با گوشت سر، پاچه و لیمو","width":1200,"height":900}}],"tips":{"fa":["هرچه تمیز کردن کامل‌تر باشد، بوی باجه کمتر است؛ آشپزهای حرفه‌ای حتی باجهٔ تمیزشدهٔ قصاب را دو بار دیگر می‌شویند.","آب جوش اول را حتماً دور بریزید؛ این کار بوی تند (زفرة) را می‌گیرد.","با زودپز: پس از جوش اول، ۲۰ تا ۳۰ دقیقه از زمان بالا آمدن فشار بپزید.","آبگوشت را شب در یخچال بگذارید تا چربی رویش ببندد و راحت جدا شود."],"en":["The better the cleaning, the milder the smell; professional cooks wash even butcher-cleaned pacha twice more.","Always discard the blanching water; it removes the strong odour (zafra).","Pressure cooker: after blanching, cook 20–30 minutes once at pressure.","Chill the broth overnight so the fat sets on top and lifts off easily."],"ar":["كلما كان التنظيف أدق قلّت الرائحة؛ يعيد الطباخون غسل الباجة المنظفة عند القصاب مرتين.","ارمِ ماء الغلية الأولى دائمًا فهو يزيل الزفرة.","بقدر الضغط: بعد الغلية الأولى اطبخها ٢٠ إلى ٣٠ دقيقة من بدء الضغط.","برّد المرق ليلة في الثلاجة ليتجمد الدهن على السطح ويُرفع بسهولة."]},"cover":{"src":"/recipes/pacha/cover.webp","alt":"باجه: نان خیس‌خورده در آبگوشت با گوشت سر، زبان و پاچه کنار لیمو","width":1600,"height":1200},"serving":{"src":"/recipes/pacha/serving.webp","alt":"یک پرس باجه در کاسهٔ فلزی با قاچ لیمو و ترشی","width":1200,"height":1500}},{"id":"qeema-najafiya","country":"IQ","slugs":{"fa":"قیمه-نجفی","en":"qeema-najafiya","ar":"قيمة-نجفية"},"title":{"fa":"قیمهٔ نجفی","en":"Qeema Najafiya (Najaf Meat and Chickpea Stew)","ar":"قيمة نجفية"},"summary":{"fa":"خورش غلیظ و یکدست گوشت گوساله و نخود که پس از پختن کوبیده می‌شود و با لیموعمانی، رب گوجه، زیره و دارچین جا می‌افتد؛ همیشه با برنج زعفرانی.","en":"A thick, smooth stew of veal and chickpeas, pounded together after cooking and finished with dried lime, tomato paste, cumin and cinnamon; always served with saffron rice.","ar":"مرقة كثيفة متجانسة من لحم العجل والحمص تُدق بعد السلق وتُطبخ مع النومي بصرة ومعجون الطماطم والكمون والدارسين، وتُقدم دائمًا مع التمن بالزعفران."},"intro":{"fa":"\xabتمن و قیمه\xbb غذای نذری محرم و صفر در عراق است و نسخهٔ نجفی آن مشهورترین است؛ در کربلا و کاظمین هم پخته می‌شود. در نجف رستوران‌هایی مثل حاج خفاجی نزدیک حرم امام علی (ع) تا سحر شلوغ‌اند و راز طعم را \xabیک کیلو نخود به یک کیلو گوشت\xbb و استفاده نکردن از جوش‌شیرین می‌دانند.","en":"\\"Timman and qeema\\" is the votive dish of Muharram and Safar in Iraq, and the Najaf version is the most famous; it is also cooked in Karbala and Kadhimiya. In Najaf, eateries such as Hajj al-Khafaji near the shrine of Imam Ali stay busy until dawn, crediting a rich one-kilo-chickpeas-to-one-kilo-meat ratio and no baking soda.","ar":"\xabالتمن والقيمة\xbb طبق النذر في محرم وصفر بالعراق، والنسخة النجفية أشهرها، وتُطبخ أيضًا في كربلاء والكاظمية. في النجف تزدحم مطاعم مثل مطعم الحاج الخفاجي قرب مرقد الإمام علي حتى السحور، ويقول إن السر نسبة كيلو حمص لكل كيلو لحم وعدم الإكثار من الصودا."},"seoTitle":{"fa":"قیمه نجفی؛ طرز تهیه خورش گوشت و نخود کوبیده عراقی","en":"Qeema Najafiya Recipe (Iraqi Meat and Chickpea Stew)","ar":"قيمة نجفية: طريقة عمل القيمة العراقية باللحم والحمص"},"seoDescription":{"fa":"طرز تهیه قیمه نجفی برای ۱۰ نفر: گوشت گوساله و نخود پخته و کوبیده با لیموعمانی، رب گوجه، زیره و دارچین، سرو با برنج زعفرانی؛ با ۱۲ ساعت خیساندن نخود.","en":"Qeema najafiya for 10: veal and chickpeas cooked, pounded smooth and simmered with dried lime, tomato paste, cumin and cinnamon; served with saffron rice.","ar":"طريقة عمل القيمة النجفية لعشرة أشخاص: لحم عجل وحمص يُسلقان ويُدقان ويُطبخان مع النومي بصرة ومعجون الطماطم والكمون والدارسين، وتُقدم مع التمن بالزعفران."},"servings":10,"prep":33,"cook":210,"rest":720,"total":963,"oven":null,"difficulty":{"fa":"متوسط","en":"Medium","ar":"متوسط"},"showNutrition":false,"ingredients":[{"name":{"fa":"گوشت گوسالهٔ بی‌استخوان (ذبح حلال)","en":"Boneless veal or beef (halal-slaughtered)","ar":"لحم عجل بلا عظم (مذبوح حلال)"},"amount":"1000","unit":"گرم","optional":false,"group":{"fa":"قیمه","en":"Qeema","ar":"القيمة"},"note":{"fa":"مکعب‌های ۴ سانتی‌متری.","en":"In 4 cm cubes.","ar":"مكعبات ٤ سم."}},{"name":{"fa":"نخود خشک","en":"Dried chickpeas","ar":"حمص يابس"},"amount":"750","unit":"گرم","optional":false,"group":{"fa":"قیمه","en":"Qeema","ar":"القيمة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"پیاز","en":"Onions","ar":"بصل"},"amount":"300","unit":"گرم","optional":false,"group":{"fa":"قیمه","en":"Qeema","ar":"القيمة"},"note":{"fa":"ریز خردشده؛ حدود ۲ عدد متوسط.","en":"Finely chopped; about 2 medium.","ar":"مفروم ناعمًا؛ نحو بصلتين متوسطتين."}},{"name":{"fa":"روغن حیوانی یا روغن مایع","en":"Ghee or vegetable oil","ar":"دهن حر أو زيت نباتي"},"amount":"4","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"قیمه","en":"Qeema","ar":"القيمة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"هل سابیده","en":"Ground cardamom","ar":"هيل مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"قیمه","en":"Qeema","ar":"القيمة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"3","unit":"لیتر","optional":false,"group":{"fa":"قیمه","en":"Qeema","ar":"القيمة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"رب گوجه‌فرنگی","en":"Tomato paste","ar":"معجون طماطم"},"amount":"5","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"در ۱ پیمانه آب حل‌شده.","en":"Diluted in 1 cup water.","ar":"مخفف بكوب ماء."}},{"name":{"fa":"لیموعمانی سیاه آسیاب‌شده (نومی بصره)","en":"Ground black dried lime (noomi Basra)","ar":"نومي بصرة مطحون"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زیره سبز آسیاب‌شده","en":"Ground cumin","ar":"كمون مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"دارچین","en":"Ground cinnamon","ar":"دارسين مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"ادویهٔ قیمه یا بهارات عراقی","en":"Iraqi qeema spice or baharat","ar":"بهارات قيمة"},"amount":"1","unit":"قاشق غذاخوری","optional":true,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"نخود بوداده و آسیاب‌شده","en":"Ground roasted chickpeas","ar":"حمص محمص مطحون"},"amount":"2","unit":"قاشق غذاخوری","optional":true,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"برای غلظت بیشتر.","en":"For extra thickness.","ar":"لمزيد من الكثافة."}},{"name":{"fa":"نمک","en":"Salt","ar":"ملح"},"amount":"2","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"چاشنی و رنگ","en":"Seasoning","ar":"التتبيل"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"خیساندن نخود","en":"Soak the chickpeas","ar":"نقع الحمص"},"text":{"fa":"شب قبل نخود را بشویید و در کاسه‌ای با ۳ برابر حجمش آب سرد بگذارید تا ۱۲ ساعت بماند؛ یکی دو بار آب را عوض کنید (زمان استراحت).","en":"The night before, rinse the chickpeas and cover with three times their volume of cold water for 12 hours; change the water once or twice (rest time).","ar":"في الليلة السابقة اغسل الحمص وانقعه في ثلاثة أضعاف حجمه من الماء البارد ١٢ ساعة، وغيّر الماء مرة أو مرتين (وقت الراحة)."},"time":720,"image":{"src":"/recipes/qeema-najafiya/step-01.webp","alt":"کاسهٔ نخود خیس‌خورده برای قیمهٔ نجفی","width":1200,"height":900}},{"n":2,"title":{"fa":"سرخ کردن پیاز","en":"Fry the onion","ar":"قلي البصل"},"text":{"fa":"۱) پیاز را ریز خرد کنید.\\n۲) روغن را در قابلمهٔ بزرگ (۸ لیتری، ترجیحاً ته‌ضخیم) روی حرارت متوسط داغ کنید.\\n۳) پیاز را ۱۰ تا ۱۲ دقیقه هم بزنید تا طلایی روشن شود.","en":"1) Finely chop the onion.\\n2) Heat the fat in a large heavy-based pot (8 L) over medium heat.\\n3) Stir the onion 10–12 minutes until light golden.","ar":"١) افرم البصل ناعمًا.\\n٢) سخّن الدهن في قدر كبير سميك القاع (٨ لترات) على نار متوسطة.\\n٣) قلّب البصل ١٠ إلى ١٢ دقيقة حتى يصبح أشقر."},"time":20,"image":{"src":"/recipes/qeema-najafiya/step-02.webp","alt":"پیاز طلایی روشن در روغن داخل قابلمهٔ بزرگ قیمه","width":1200,"height":900}},{"n":3,"title":{"fa":"تفت دادن گوشت","en":"Sear the meat","ar":"تقليب اللحم"},"text":{"fa":"گوشت و هل را به پیاز اضافه کنید و روی حرارت متوسط‌زیاد ۸ دقیقه هم بزنید تا رنگ صورتی گوشت از بین برود.","en":"Add the meat and cardamom to the onion and stir over medium-high heat for 8 minutes until no pink shows.","ar":"أضف اللحم والهيل إلى البصل وقلّب على نار متوسطة إلى عالية ٨ دقائق حتى يزول اللون الوردي."},"time":8,"image":{"src":"/recipes/qeema-najafiya/step-03.webp","alt":"مکعب‌های گوشت قیمه در حال تفت با پیاز طلایی","width":1200,"height":900}},{"n":4,"title":{"fa":"پختن گوشت و نخود","en":"Simmer meat and chickpeas","ar":"سلق اللحم والحمص"},"text":{"fa":"۱) نخود را آبکش کنید و با ۳ لیتر آب به قابلمه بریزید.\\n۲) روی حرارت زیاد بجوشانید و کف را بگیرید.\\n۳) در را بگذارید و روی حرارت کم حدود ۲/۵ ساعت بپزید تا گوشت با چنگال ریش شود و نخود بین دو انگشت به‌راحتی له شود.\\n۴) جوش‌شیرین اضافه نکنید.","en":"1) Drain the chickpeas and add to the pot with 3 L water.\\n2) Bring to the boil over high heat and skim.\\n3) Cover and simmer on low about 2\xbd hours until the meat shreds with a fork and a chickpea crushes easily between two fingers.\\n4) Do not add baking soda.","ar":"١) صفِّ الحمص وأضفه إلى القدر مع ٣ لترات ماء.\\n٢) اتركه يغلي على نار عالية وأزل الرغوة.\\n٣) غطِّه واتركه على نار هادئة نحو ساعتين ونصف حتى يتفتت اللحم بالشوكة وينهرس الحمص بين الإصبعين بسهولة.\\n٤) لا تضف الصودا."},"time":150,"image":{"src":"/recipes/qeema-najafiya/step-04.webp","alt":"قابلمهٔ گوشت و نخود قیمهٔ نجفی در حال پخت آرام","width":1200,"height":900}},{"n":5,"title":{"fa":"کوبیدن","en":"Pound","ar":"الدق"},"text":{"fa":"۱) با کفگیر گوشت و نخود را در کاسهٔ بزرگ بریزید؛ آب پخت را دور نریزید.\\n۲) با گوشت‌کوب یا هاون آن‌قدر بکوبید تا گوشت و نخود یکی شوند و خمیری رشته‌رشته بسازند (حدود ۱۵ تا ۲۰ دقیقه).\\n۳) می‌توانید چند ثانیه‌ای و متناوب از غذاساز استفاده کنید؛ زیاد نزنید که پوره نشود.","en":"1) Lift the meat and chickpeas into a large bowl with a slotted spoon; keep the cooking liquid.\\n2) Pound with a meat pounder or pestle until meat and chickpeas merge into one stringy mass (15–20 minutes).\\n3) A food processor in short pulses also works; do not overblend into a pur\xe9e.","ar":"١) ارفع اللحم والحمص بالمغرفة المثقبة إلى وعاء كبير، واحتفظ بماء السلق.\\n٢) دقّه بالطخماخ أو الهاون حتى يتجانس اللحم والحمص ويصبحا كتلة واحدة متليفة (١٥ إلى ٢٠ دقيقة).\\n٣) يمكن استخدام محضرة الطعام بضغطات قصيرة دون أن يصبح هريسًا ناعمًا."},"time":20,"image":{"src":"/recipes/qeema-najafiya/step-05.webp","alt":"کوبیدن گوشت و نخود قیمه با گوشت‌کوب در کاسه","width":1200,"height":900}},{"n":6,"title":{"fa":"جا انداختن","en":"Finish and thicken","ar":"الطبخ حتى التكثيف"},"text":{"fa":"۱) خمیر کوبیده را به قابلمه برگردانید و ۳ پیمانه از آب پخت را اضافه کنید.\\n۲) نمک، لیموعمانی، زیره، دارچین، ادویه و رب حل‌شده را بریزید و خوب هم بزنید.\\n۳) روی حرارت کم ۴۰ دقیقه بپزید و هر ۵ دقیقه از ته هم بزنید که نسوزد. اگر خیلی سفت شد کمی آب پخت اضافه کنید.\\n۴) نشانهٔ پخت: بسیار غلیظ و قهوه‌ای‌قرمز، قاشق رد باقی می‌گذارد و روغن روی سطح می‌آید. نمک و ترشی را بچشید.","en":"1) Return the pounded mixture to the pot and add 3 cups of the cooking liquid.\\n2) Stir in the salt, dried lime, cumin, cinnamon, spice and diluted paste.\\n3) Cook on low for 40 minutes, scraping the bottom every 5 minutes so it does not catch; add a little cooking liquid if too stiff.\\n4) Done when very thick and reddish brown, a spoon leaves a trail and fat rises to the top. Taste for salt and sourness.","ar":"١) أعد الخليط المدقوق إلى القدر وأضف ٣ أكواب من ماء السلق.\\n٢) أضف الملح والنومي بصرة والكمون والدارسين والبهارات والمعجون المخفف وحرّك جيدًا.\\n٣) اطبخه على نار هادئة ٤٠ دقيقة مع التحريك من القاع كل ٥ دقائق كي لا يلتصق، وأضف قليلًا من ماء السلق إذا ثقل كثيرًا.\\n٤) تنضج حين تصبح كثيفة جدًا بلون بني محمر وتترك الملعقة أثرًا ويطفو الدهن. تذوق الملح والحموضة."},"time":40,"image":{"src":"/recipes/qeema-najafiya/step-06.webp","alt":"قیمهٔ نجفی غلیظ قهوه‌ای‌قرمز در قابلمه که قاشق در آن رد می‌گذارد","width":1200,"height":900}},{"n":7,"title":{"fa":"سرو","en":"Serve","ar":"التقديم"},"text":{"fa":"برنج زعفرانی را در بشقاب بکشید و یک ملاقه قیمه کنار یا روی آن بریزید.","en":"Plate saffron rice and spoon a ladle of qeema beside or over it.","ar":"ضع التمن بالزعفران في الطبق وأضف مغرفة قيمة بجانبه أو فوقه."},"time":5,"image":{"src":"/recipes/qeema-najafiya/step-07.webp","alt":"بشقاب برنج زعفرانی با قیمهٔ نجفی","width":1200,"height":900}}],"tips":{"fa":["منابع نسبت گوشت به نخود را از ۲ به ۱ تا ۱ به ۱ می‌دهند؛ ۱ کیلو گوشت به ۷۵۰ گرم نخود حد وسط است.","قابلمهٔ ته‌ضخیم و هم زدن مرتب در مرحلهٔ آخر از ته‌گرفتن جلوگیری می‌کند.","قیمه روز بعد غلیظ‌تر و خوش‌طعم‌تر است؛ هنگام گرم کردن کمی آب اضافه کنید."],"en":["Sources give meat-to-chickpea ratios from 2:1 to 1:1; 1 kg meat to 750 g chickpeas is the middle.","A heavy pot and regular stirring at the end stop it catching.","Qeema thickens and tastes better the next day; add a little water when reheating."],"ar":["تتراوح نسبة اللحم إلى الحمص في المصادر من ٢ إلى ١ حتى ١ إلى ١، وكيلو لحم مع ٧٥٠ غرام حمص هو الوسط.","القدر السميك والتحريك المنتظم في المرحلة الأخيرة يمنعان الالتصاق.","تصبح القيمة أكثف وألذ في اليوم التالي؛ أضف قليلًا من الماء عند التسخين."]},"cover":{"src":"/recipes/qeema-najafiya/cover.webp","alt":"قیمهٔ نجفی غلیظ در کاسه کنار دیس برنج زعفرانی و ترشی","width":1600,"height":1200},"serving":{"src":"/recipes/qeema-najafiya/serving.webp","alt":"بشقاب برنج زعفرانی با یک ملاقه قیمهٔ نجفی","width":1200,"height":1500}},{"id":"zarda","country":"IQ","slugs":{"fa":"زرده-عراقی","en":"zarda","ar":"زردة"},"title":{"fa":"زرده","en":"Zarda (Iraqi Saffron Rice Pudding)","ar":"زردة"},"summary":{"fa":"دسر برنجی زرد و براق با شکر، زعفران، گلاب و هل که با دارچین و بادام تزئین و سرد سرو می‌شود؛ خویشاوند نزدیک شله‌زرد ایرانی.","en":"A glossy yellow rice pudding with sugar, saffron, rose water and cardamom, garnished with cinnamon and almonds and served cold; a close cousin of Persian sholeh zard.","ar":"حلوى رز صفراء لامعة بالسكر والزعفران وماء الورد والهيل، تُزين بالدارسين واللوز وتُقدم باردة."},"intro":{"fa":"زرده شیرینی شب مولد پیامبر (ص) در بغداد است، به‌ویژه در اعظمیه که خانواده‌ها آن را می‌پزند و در کوچه‌ها پخش می‌کنند. نامش از واژهٔ فارسی \xabزرد\xbb آمده، به خاطر رنگی که زعفران می‌دهد. در مناسبت‌های مذهبی دیگر هم پخته می‌شود.","en":"Zarda is the sweet of the Prophet\'s Mawlid night in Baghdad, especially in Adhamiya, where families cook it and hand it out in the streets. Its name comes from the Persian word zard, \\"yellow\\", for the colour saffron gives. It is also cooked for other religious occasions.","ar":"الزردة حلوى ليلة المولد النبوي في بغداد، خصوصًا في الأعظمية حيث تطبخها العائلات وتوزعها في الأزقة. يرتبط اسمها بكلمة \xabزرد\xbb الفارسية بمعنى الأصفر، إشارة إلى لون الزعفران. وتُطبخ أيضًا في مناسبات دينية أخرى."},"seoTitle":{"fa":"زرده عراقی؛ طرز تهیه دسر برنج زعفرانی با گلاب و هل","en":"Zarda Recipe (Iraqi Saffron Rice Pudding)","ar":"زردة: طريقة عمل الزردة العراقية بالزعفران وماء الورد"},"seoDescription":{"fa":"طرز تهیه زردهٔ عراقی آسان برای ۱۰ کاسه: برنج با شکر، زعفران، گلاب و هل، تزئین با دارچین و بادام و سرو سرد؛ حدود ۴ ساعت با سرد شدن.","en":"Easy Iraqi zarda for 10 bowls: rice with sugar, saffron, rose water and cardamom, topped with cinnamon and almonds, served cold. About 4 h incl. chilling.","ar":"طريقة عمل الزردة السهلة لعشرة أوعية: رز مع السكر والزعفران وماء الورد والهيل، يُزين بالدارسين واللوز ويُقدم باردًا؛ نحو ٤ ساعات مع التبريد."},"servings":10,"prep":10,"cook":65,"rest":180,"total":255,"oven":null,"difficulty":{"fa":"آسان","en":"Easy","ar":"سهل"},"showNutrition":false,"ingredients":[{"name":{"fa":"برنج عنبر یا برنج دانه‌کوتاه","en":"Amber or short-grain rice","ar":"رز عنبر أو رز قصير الحبة"},"amount":"500","unit":"گرم","optional":false,"group":{"fa":"زرده","en":"Zarda","ar":"الزردة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"آب","en":"Water","ar":"ماء"},"amount":"3","unit":"لیتر","optional":false,"group":{"fa":"زرده","en":"Zarda","ar":"الزردة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"شکر","en":"Sugar","ar":"سكر"},"amount":"800","unit":"گرم","optional":false,"group":{"fa":"زرده","en":"Zarda","ar":"الزردة"},"note":{"fa":"حدود ۴ پیمانه.","en":"About 4 cups.","ar":"نحو ٤ أكواب."}},{"name":{"fa":"روغن حیوانی یا کره","en":"Ghee or butter","ar":"سمن أو زبدة"},"amount":"0.25","unit":"پیمانه","optional":false,"group":{"fa":"زرده","en":"Zarda","ar":"الزردة"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"زعفران","en":"Saffron threads","ar":"زعفران"},"amount":"0.5","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"عطر و رنگ","en":"Aroma and colour","ar":"العطر واللون"},"note":{"fa":"در ۳ قاشق غذاخوری آب جوش دم‌شده.","en":"Bloomed in 3 tbsp boiling water.","ar":"منقوع في ٣ ملاعق كبيرة ماء مغلي."}},{"name":{"fa":"گلاب","en":"Rose water","ar":"ماء ورد"},"amount":"3","unit":"قاشق غذاخوری","optional":false,"group":{"fa":"عطر و رنگ","en":"Aroma and colour","ar":"العطر واللون"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"هل سابیده","en":"Ground cardamom","ar":"هيل مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"عطر و رنگ","en":"Aroma and colour","ar":"العطر واللون"},"note":{"fa":"","en":"","ar":""}},{"name":{"fa":"بادام پوست‌گرفته","en":"Blanched almonds","ar":"لوز مقشر"},"amount":"0.25","unit":"پیمانه","optional":false,"group":{"fa":"تزئین","en":"Garnish","ar":"التزيين"},"note":{"fa":"خلال یا نصف‌شده.","en":"Slivered or halved.","ar":"شرائح أو أنصاف."}},{"name":{"fa":"دارچین","en":"Ground cinnamon","ar":"دارسين مطحون"},"amount":"1","unit":"قاشق چای‌خوری","optional":false,"group":{"fa":"تزئین","en":"Garnish","ar":"التزيين"},"note":{"fa":"","en":"","ar":""}}],"steps":[{"n":1,"title":{"fa":"خیساندن برنج","en":"Soak the rice","ar":"نقع الرز"},"text":{"fa":"برنج را چند بار بشویید تا آبش تقریباً زلال شود و ۱ ساعت در آب سرد خیس کنید (زمان استراحت).","en":"Wash the rice several times until the water runs almost clear and soak 1 hour in cold water (rest time).","ar":"اغسل الرز عدة مرات حتى يصفو الماء تقريبًا وانقعه ساعة في ماء بارد (وقت الراحة)."},"time":60,"image":{"src":"/recipes/zarda/step-01.webp","alt":"کاسهٔ برنج خیس‌خورده برای زرده","width":1200,"height":900}},{"n":2,"title":{"fa":"دم کردن زعفران","en":"Bloom the saffron","ar":"نقع الزعفران"},"text":{"fa":"هم‌زمان با خیساندن (جدا شمرده نشده):\\n۱) زعفران را در هاون کوچک با یک حبه قند بسایید.\\n۲) در استکان بریزید، ۳ قاشق آب جوش اضافه کنید و دست‌کم ۱۰ دقیقه بگذارید تا رنگ بدهد.\\n۳) گلاب را به آن اضافه کنید.","en":"While the rice soaks (not counted separately):\\n1) Grind the saffron in a small mortar with a sugar cube.\\n2) Put in a small glass, add 3 tablespoons boiling water and leave at least 10 minutes to release its colour.\\n3) Add the rose water.","ar":"أثناء النقع (لا يُحسب منفصلًا):\\n١) اسحق الزعفران في هاون صغير مع مكعب سكر.\\n٢) ضعه في استكان وأضف ٣ ملاعق ماء مغلي واتركه ١٠ دقائق على الأقل ليعطي لونه.\\n٣) أضف ماء الورد."},"time":10,"image":{"src":"/recipes/zarda/step-02.webp","alt":"استکان آب زعفران نارنجی تند کنار هاون کوچک","width":1200,"height":900}},{"n":3,"title":{"fa":"پختن برنج","en":"Cook the rice","ar":"سلق الرز"},"text":{"fa":"۱) برنج را آبکش کنید و با ۳ لیتر آب در قابلمهٔ بزرگ (۶ لیتری، ته‌ضخیم) بریزید.\\n۲) روی حرارت زیاد بجوشانید، بعد حرارت را کم کنید.\\n۳) بدون در حدود ۴۵ دقیقه بپزید و هر ۵ تا ۱۰ دقیقه آرام هم بزنید.\\n۴) نشانهٔ آماده بودن: دانه‌ها کاملاً نرم‌اند و بین انگشت له می‌شوند و آب کمی غلیظ و نشاسته‌ای شده است. تا برنج کاملاً نپخته شکر نریزید.","en":"1) Drain the rice and put it in a large heavy pot (6 L) with 3 L water.\\n2) Bring to the boil over high heat, then turn to low.\\n3) Simmer uncovered about 45 minutes, stirring gently every 5–10 minutes.\\n4) Ready when the grains are completely soft and crush between your fingers and the liquid is slightly thick and starchy. Do not add sugar until the rice is fully cooked.","ar":"١) صفِّ الرز وضعه في قدر كبير سميك (٦ لترات) مع ٣ لترات ماء.\\n٢) اتركه يغلي على نار عالية ثم اخفض النار.\\n٣) اطبخه مكشوفًا نحو ٤٥ دقيقة مع تحريك هادئ كل ٥ إلى ١٠ دقائق.\\n٤) يجهز حين تصبح الحبات طرية تمامًا وتنهرس بين الأصابع ويكثف الماء قليلًا. لا تضف السكر قبل أن ينضج الرز تمامًا."},"time":50,"image":{"src":"/recipes/zarda/step-03.webp","alt":"قابلمهٔ بزرگ برنج نرم‌شده در آب نشاسته‌ای برای زرده","width":1200,"height":900}},{"n":4,"title":{"fa":"افزودن شکر و زعفران","en":"Add sugar and saffron","ar":"إضافة السكر والزعفران"},"text":{"fa":"۱) شکر را اضافه کنید و هم بزنید تا حل شود.\\n۲) آب زعفران و گلاب و هل را بریزید.\\n۳) روی حرارت کم ۱۵ دقیقه آرام و پیوسته هم بزنید که ته نگیرد.\\n۴) نشانه: زرد طلایی براق و غلیظ مثل فرنی شل؛ با سرد شدن سفت‌تر می‌شود.","en":"1) Add the sugar and stir until dissolved.\\n2) Pour in the saffron-rose water and cardamom.\\n3) Stir gently and constantly on low for 15 minutes so it does not catch.\\n4) Ready when glossy golden yellow and thick like loose porridge; it sets more as it cools.","ar":"١) أضف السكر وحرّك حتى يذوب.\\n٢) أضف ماء الزعفران وماء الورد والهيل.\\n٣) حرّك بهدوء وباستمرار على نار هادئة ١٥ دقيقة كي لا تلتصق.\\n٤) تجهز حين تصبح صفراء ذهبية لامعة كثيفة كالمهلبية الخفيفة، وتتماسك أكثر حين تبرد."},"time":15,"image":{"src":"/recipes/zarda/step-04.webp","alt":"زردهٔ زرد طلایی و براق در قابلمه در حال هم زدن","width":1200,"height":900}},{"n":5,"title":{"fa":"افزودن روغن و کشیدن","en":"Add fat and portion","ar":"إضافة الدهن والسكب"},"text":{"fa":"۱) قابلمه را از روی حرارت بردارید و روغن یا کره را هم بزنید تا جذب شود.\\n۲) داغ در کاسه‌های کوچک یا یک دیس بکشید.","en":"1) Take the pot off the heat and stir in the ghee or butter until absorbed.\\n2) Ladle hot into small bowls or a platter.","ar":"١) ارفع القدر عن النار وحرّك السمن أو الزبدة حتى يمتزج.\\n٢) اسكبها ساخنة في أوعية صغيرة أو طبق واسع."},"time":5,"image":{"src":"/recipes/zarda/step-05.webp","alt":"کشیدن زرده در کاسه‌های کوچک","width":1200,"height":900}},{"n":6,"title":{"fa":"تزئین","en":"Garnish","ar":"التزيين"},"text":{"fa":"روی هر کاسه با دارچین نقش بزنید (خط یا ضربدر) و بادام بچینید.","en":"Draw lines or a cross of cinnamon on each bowl and arrange the almonds.","ar":"ارسم خطوطًا أو صليبًا من الدارسين على كل وعاء ورتب اللوز."},"time":5,"image":{"src":"/recipes/zarda/step-06.webp","alt":"کاسه‌های زرده با خطوط دارچین و بادام","width":1200,"height":900}},{"n":7,"title":{"fa":"سرد کردن","en":"Chill","ar":"التبريد"},"text":{"fa":"بگذارید ۳۰ دقیقه در دمای اتاق خنک شود، بعد دست‌کم ۱/۵ ساعت در یخچال بگذارید تا سفت شود (زمان استراحت).","en":"Cool 30 minutes at room temperature, then refrigerate at least 1\xbd hours to set (rest time).","ar":"اتركها ٣٠ دقيقة بحرارة الغرفة ثم ضعها في الثلاجة ساعة ونصفًا على الأقل لتتماسك (وقت الراحة)."},"time":120,"image":{"src":"/recipes/zarda/step-07.webp","alt":"کاسه‌های زردهٔ سفت‌شده در یخچال","width":1200,"height":900}}],"tips":{"fa":["منابع نسبت شکر به برنج را از حدود ۱/۳ به ۱ تا ۲ به ۱ می‌دهند؛ ۸۰۰ گرم برای ۵۰۰ گرم برنج حد وسط است. برای شیرینی کمتر تا ۶۵۰ گرم کم کنید.","شکر را فقط وقتی برنج کاملاً پخت اضافه کنید؛ وگرنه دانه‌ها سفت می‌مانند.","اگر زرده پس از سرد شدن خیلی سفت شد، دفعهٔ بعد ۱۵ دقیقهٔ آخر را کوتاه‌تر کنید."],"en":["Sources give sugar-to-rice ratios from about 1.3:1 to 2:1; 800 g for 500 g rice is the middle. For less sweetness go down to 650 g.","Add the sugar only when the rice is fully cooked, or the grains stay hard.","If it sets too firm, shorten the last 15 minutes next time."],"ar":["تتراوح نسبة السكر إلى الرز في المصادر من ١٫٣ إلى ١ حتى ٢ إلى ١؛ و٨٠٠ غرام لنصف كيلو رز هو الوسط. لحلاوة أقل اخفضه إلى ٦٥٠ غرامًا.","أضف السكر فقط بعد نضج الرز تمامًا وإلا بقيت الحبات قاسية.","إذا تماسكت كثيرًا بعد التبريد قلّل الدقائق الخمس عشرة الأخيرة في المرة القادمة."]},"cover":{"src":"/recipes/zarda/cover.webp","alt":"زرده: کاسه‌های برنج زرد زعفرانی با خطوط دارچین و بادام","width":1600,"height":1200},"serving":{"src":"/recipes/zarda/serving.webp","alt":"یک کاسهٔ زردهٔ سرد با قاشق و دارچین و بادام","width":1200,"height":1500}}]}');function i(e){let a=arguments.length>1&&void 0!==arguments[1]?arguments[1]:"",t=a?"/".concat(a.replace(/^\//,"")):"";return"".concat("/noashpaz-preview","/").concat(e).concat(t,"/")}}}]);